-- Nạp toàn bộ 14 đề Reading, 14 đề Listening và 12 đề Complete the Words từ YouTube
-- Hướng dẫn: Mở Supabase Dashboard -> SQL Editor -> New Query -> Dán toàn bộ và bấm RUN
-- ====================================================================

BEGIN;

-- ====================================================================
-- 1. 14 BỘ ĐỀ READING 2026 TỪ YOUTUBE (MODULE 1 & MODULE 2 ĐẦY ĐỦ)
-- ====================================================================
INSERT INTO public.tests (id, title, skill, task_type, duration_seconds, content, created_at)
VALUES (
  'reading-practice-02',
  'Reading Practice Test 02 (TOEFL 2026 - Amazon & Sunk Costs)',
  'reading',
  'multistage',
  1800,
  '{"stages":[{"id":"read2_stage_1","title":"Reading - Module 1 (Stage 1)","duration_seconds":900,"description":"Module 1 gồm 4 thành phần: Complete the Words, Read a notice, Read an announcement, và Academic passage. Hãy hoàn thành trước khi hết 15 phút.","tasks":[{"id":"read2_m1_t1","title":"Task 1: Complete the Words","task_type":"complete_words","content":{"instructions":"Điền các chữ cái còn thiếu vào vị trí dấu gạch dưới `_` trong đoạn văn học thuật dưới đây.","paragraph":"The Amazon rainforest is one of the most biodiverse regions on Earth. It produ[ces] a signi[ficant] amount o[f] the planet''s ox[ygen] and regu[lates] global tempe[ratures]. However, defore[station] caused by logg[ing], agriculture, and ur[ban] expansion threa[tens] this delicate ecosystem. As trees are cut down, many species lose their habitats, and carbon dioxide levels rise. Conservation efforts focus on promoting sustainable practices, reforestation, and international cooperation to protect this vital natural resource for future generations.","blanks":[{"id":"read2_m1_t1_b1","prefix":"produ","missing":"ces","full":"produces"},{"id":"read2_m1_t1_b2","prefix":"signi","missing":"ficant","full":"significant"},{"id":"read2_m1_t1_b3","prefix":"o","missing":"f","full":"of"},{"id":"read2_m1_t1_b4","prefix":"ox","missing":"ygen","full":"oxygen"},{"id":"read2_m1_t1_b5","prefix":"regu","missing":"lates","full":"regulates"},{"id":"read2_m1_t1_b6","prefix":"tempe","missing":"ratures","full":"temperatures"},{"id":"read2_m1_t1_b7","prefix":"defore","missing":"station","full":"deforestation"},{"id":"read2_m1_t1_b8","prefix":"logg","missing":"ing","full":"logging"},{"id":"read2_m1_t1_b9","prefix":"ur","missing":"ban","full":"urban"},{"id":"read2_m1_t1_b10","prefix":"threa","missing":"tens","full":"threatens"}]}},{"id":"read2_m1_t2","title":"Task 2: Read a Notice","task_type":"daily_life","content":{"document_type":"Customer Notice - Return Policy","passage":"Subject: Important update\n\nDear Customers,\nStarting October 20, all returns must be initiated within 14 days of delivery. Items must be unused, in their original packaging, and accompanied by the receipt. For your convenience, online purchases can now be returned directly to any of our physical stores. Refunds will be processed within 5-7 business days.\nWe appreciate your understanding as we continue to improve your shopping experience.","questions":[{"id":"read2_m1_q11","type":"multiple_choice","prompt":"What is the main purpose of the notice?","options":{"A":"To clarify how to track shipped orders","B":"To thank customers for their recent purchases","C":"To inform customers about updated return procedures","D":"To remind customers about online shopping benefits"},"correct_answer":"C","explanation":"Thông báo cập nhật thủ tục và quy định đổi trả hàng mới (thời hạn 14 ngày, đổi trả trực tiếp tại cửa hàng, hoàn tiền trong 5-7 ngày)."},{"id":"read2_m1_q12","type":"multiple_choice","prompt":"What new option is available to customers?","options":{"A":"They can return items after the 14-day period","B":"They can exchange items without a receipt","C":"They can request a refund by phone only","D":"They can return online orders at store locations"},"correct_answer":"D","explanation":"Thông báo nêu rõ: ''online purchases can now be returned directly to any of our physical stores''."}]}},{"id":"read2_m1_t3","title":"Task 3: Read an Announcement","task_type":"daily_life","content":{"document_type":"Workplace Sustainability Announcement","passage":"Attention!\n\nIn an effort to reduce waste, our company is eliminating disposable cups and utensils in the break room. Employees are encouraged to bring reusable mugs and containers. Recycling bins for paper and plastic have also been added on each floor. These small steps will help us lower our environmental impact and create a more sustainable workplace.","questions":[{"id":"read2_m1_q13","type":"multiple_choice","prompt":"What is the main goal of the new initiative?","options":{"A":"To make the office look more modern","B":"To reduce the company''s negative effect on the environment","C":"To introduce new rules for employee behavior","D":"To promote teamwork through shared spaces"},"correct_answer":"B","explanation":"Mục tiêu trọng tâm nêu ở đầu và cuối: ''In an effort to reduce waste'' và ''lower our environmental impact and create a more sustainable workplace''."},{"id":"read2_m1_q14","type":"multiple_choice","prompt":"What are employees expected to do under the new policy?","options":{"A":"Use their own mugs and containers instead of disposable ones","B":"Avoid eating in the office during work hours","C":"Purchase all their meals from outside vendors","D":"Bring extra utensils for their coworkers"},"correct_answer":"A","explanation":"Thông báo nêu rõ: ''Employees are encouraged to bring reusable mugs and containers'' thay cho cốc và dụng cụ dùng 1 lần bị loại bỏ."}]}},{"id":"read2_m1_t4","title":"Task 4: Academic Passage","task_type":"academic_passage","content":{"document_type":"Biophysics & Animal Navigation Passage","passage":"The Enigma of Animal Magnetoreception\n\nMany species, from migratory birds to sea turtles, navigate vast distances with astonishing precision, a feat believed to be enabled by magnetoreception—the ability to detect Earth''s magnetic field. The exact biological mechanism, however, remains one of science''s most enduring mysteries.\n\nOne leading hypothesis posits the use of cryptochromes, light-sensitive proteins in the retina that may form a radical pair upon photon absorption, creating a quantum-entangled state whose chemistry is influenced by the geomagnetic field, effectively allowing the animal to \"see\" magnetic lines as visual patterns.\n\nA competing theory suggests the presence of magnetite, a magnetic iron oxide, in certain cells, which could act like a microscopic compass needle, translating magnetic information into neural signals.\n\nIntriguingly, these mechanisms are not necessarily mutually exclusive; an organism might employ both for different purposes, such as using a magnetite-based compass for a directional sense and a cryptochrome-based map for positional awareness. Unraveling this sensory modality not only illuminates animal behavior but also pushes the boundaries of biophysics and quantum biology.","questions":[{"id":"read2_m1_q15","type":"multiple_choice","prompt":"What is the primary purpose of the passage?","options":{"A":"To argue for the superiority of the cryptochrome hypothesis over the magnetite theory.","B":"To describe competing scientific explanations for a biological navigation ability.","C":"To detail the migratory patterns of specific bird and turtle species.","D":"To explain the quantum mechanical principles of radical pairs."},"correct_answer":"B","explanation":"Bài đọc trình bày hai giả thuyết khoa học cạnh tranh (cryptochromes vs magnetite) giải thích cơ chế định vị từ trường ở động vật."},{"id":"read2_m1_q16","type":"multiple_choice","prompt":"The word \"posits\" in the passage is closest in meaning to","options":{"A":"disproves.","B":"questions.","C":"proposes.","D":"complicates."},"correct_answer":"C","explanation":"Từ ''posits'' mang nghĩa đề xuất, đưa ra giả thuyết (proposes)."},{"id":"read2_m1_q17","type":"multiple_choice","prompt":"According to the passage, how might cryptochromes allow an animal to perceive magnetic fields?","options":{"A":"By creating a physical compass needle within the eye.","B":"By converting magnetic signals directly into sound.","C":"By influencing visual patterns through quantum chemistry.","D":"By storing iron oxide particles in retinal cells."},"correct_answer":"C","explanation":"Đoạn 2 giải thích phản ứng quang hóa lượng tử của cryptochrome tạo ra các họa tiết thị giác giúp con vật ''nhìn thấy'' từ trường."},{"id":"read2_m1_q18","type":"multiple_choice","prompt":"What can be inferred from the statement that the two mechanisms are \"not necessarily mutually exclusive\"?","options":{"A":"Most scientists now agree that magnetite is the primary mechanism.","B":"An animal could potentially use both a magnetic map and a compass.","C":"The cryptochrome theory has been definitively proven.","D":"Magnetoreception is a simple, well-understood process."},"correct_answer":"B","explanation":"''Not necessarily mutually exclusive'' có nghĩa là hai cơ chế không loại trừ nhau mà một sinh vật có thể kết hợp cả hai."},{"id":"read2_m1_q19","type":"multiple_choice","prompt":"The author mentions \"biophysics and quantum biology\" primarily to","options":{"A":"suggest that magnetoreception is an implausible phenomenon.","B":"highlight the interdisciplinary significance of the research.","C":"criticize the complexity of modern scientific theories.","D":"list the only two fields capable of solving the mystery."},"correct_answer":"B","explanation":"Tác giả nhắc đến hai ngành này để nhấn mạnh tầm quan trọng liên ngành (interdisciplinary significance) của việc giải mã bí ẩn."}]}}]},{"id":"read2_stage_2","title":"Reading - Module 2 (Stage 2 - Adaptive)","duration_seconds":900,"description":"Module 2 gồm 4 thành phần: Complete the Words, Read a post, Read a chain of messages, và Academic passage. Hãy hoàn thành trước khi hết 15 phút.","tasks":[{"id":"read2_m2_t1","title":"Task 1: Complete the Words","task_type":"complete_words","content":{"instructions":"Điền các chữ cái còn thiếu vào vị trí dấu gạch dưới `_` trong đoạn văn ngôn ngữ học dưới đây.","paragraph":"Language plays a crucial role in shaping how humans think and interact. Some lingu[ists] argue th[at] the stru[cture] of a lan[guage] influences the w[ay] its spea[kers] perceive the wo[rld]. For ex[ample], languages that have m[any] words f[or] colors may help speakers distinguish subtle shades more easily. Others claim that thought exists independently of language. Despite this debate, most researchers agree that language enables abstract thinking, social organization, and the transmission of culture across generations.","blanks":[{"id":"read2_m2_t1_b1","prefix":"lingu","missing":"ists","full":"linguists"},{"id":"read2_m2_t1_b2","prefix":"th","missing":"at","full":"that"},{"id":"read2_m2_t1_b3","prefix":"stru","missing":"cture","full":"structure"},{"id":"read2_m2_t1_b4","prefix":"lan","missing":"guage","full":"language"},{"id":"read2_m2_t1_b5","prefix":"w","missing":"ay","full":"way"},{"id":"read2_m2_t1_b6","prefix":"spea","missing":"kers","full":"speakers"},{"id":"read2_m2_t1_b7","prefix":"wo","missing":"rld","full":"world"},{"id":"read2_m2_t1_b8","prefix":"ex","missing":"ample","full":"example"},{"id":"read2_m2_t1_b9","prefix":"m","missing":"any","full":"many"},{"id":"read2_m2_t1_b10","prefix":"f","missing":"or","full":"for"}]}},{"id":"read2_m2_t2","title":"Task 2: Read a Post","task_type":"daily_life","content":{"document_type":"Community Animal Shelter Post","passage":"Stella:\n\"Just finished my first day volunteering at the animal shelter — what an amazing experience! The staff were welcoming, and the animals are so full of energy. It''s heartbreaking to see how many are waiting for adoption, but the team works hard to find each one a loving home. Can''t wait to go back next weekend!\"","questions":[{"id":"read2_m2_q11","type":"multiple_choice","prompt":"What is the writer''s attitude toward volunteering at the shelter?","options":{"A":"She thinks the work is meaningful but too emotionally difficult.","B":"She feels grateful for the experience and plans to continue.","C":"She is still getting used to the new environment.","D":"She believes the shelter could be better organized."},"correct_answer":"B","explanation":"Stella cảm thấy trải nghiệm tuyệt vời và hào hứng mong chờ quay lại tuần sau (''Can''t wait to go back next weekend!'')."},{"id":"read2_m2_q12","type":"multiple_choice","prompt":"What can be inferred about the animal shelter?","options":{"A":"It limits volunteer participation to special events.","B":"It mainly focuses on providing medical treatment to animals.","C":"It recently moved to a new location.","D":"It depends on volunteers as part of its daily operations."},"correct_answer":"D","explanation":"Trạm cứu hộ đón nhận các tình nguyện viên vào làm việc cùng đội ngũ nhân viên để hỗ trợ các hoạt động hàng ngày và tìm gia đình nhận nuôi."}]}},{"id":"read2_m2_t3","title":"Task 3: Read a Chain of Messages","task_type":"daily_life","content":{"document_type":"Instant Message Exchange","passage":"Liam: Hey, are we still meeting at the café at 5?\n\nNora: Let''s make it 5:30. Traffic is awful today.\n\nLiam: No problem. Should I get us a table?\n\nNora: Yes, please! I''ll be there as soon as I can.","questions":[{"id":"read2_m2_q13","type":"multiple_choice","prompt":"What does Liam agree to do?","options":{"A":"Arrive first to secure a place for them","B":"Wait for Nora outside the café","C":"Choose the best table","D":"Change the meeting place"},"correct_answer":"A","explanation":"Liam đề nghị vào lấy bàn trước (''Should I get us a table?'') và Nora đồng ý."},{"id":"read2_m2_q14","type":"multiple_choice","prompt":"Why is Nora going to arrive later than planned?","options":{"A":"She is worried about the traffic","B":"She has another appointment before meeting Liam","C":"She''s running behind because of traffic","D":"She had to take a different route to the café"},"correct_answer":"C","explanation":"Nora giải thích: ''Traffic is awful today'' dẫn đến việc cô ấy bị trễ và xin dời lịch sang 5:30."}]}},{"id":"read2_m2_t4","title":"Task 4: Academic Passage","task_type":"academic_passage","content":{"document_type":"Cognitive Psychology & Behavioral Economics Passage","passage":"The Fallacy of Sunk Costs\n\nThe sunk cost fallacy is a cognitive bias where individuals continue a behavior or endeavor based on previously invested resources (time, money, effort) rather than a rational assessment of future outcomes. This fallacy arises from an emotional aversion to loss, leading people to \"throw good money after bad\" to avoid feeling that their initial investment was wasted. For instance, someone might sit through a terrible movie because they paid for the ticket, even though leaving would free up time for a more enjoyable activity.\n\nEconomists argue that rational decision-making requires ignoring sunk costs, as they are irrecoverable and should not factor into marginal decisions.\n\nThe fallacy has significant implications in business, where projects with diminishing returns are often prolonged due to substantial prior investment, and in public policy, where governments may continue funding failing initiatives to avoid political embarrassment. Overcoming this bias requires a conscious shift in focus from past expenditures to prospective costs and benefits.","questions":[{"id":"read2_m2_q15","type":"multiple_choice","prompt":"Which of the following best summarizes the main idea of the passage?","options":{"A":"Financial investments should always be pursued to completion.","B":"Emotional attachment to past investments can lead to irrational decisions.","C":"Economists have successfully eliminated the sunk cost fallacy in business.","D":"Public policy is immune to cognitive biases like the sunk cost fallacy."},"correct_answer":"B","explanation":"Ý chính tóm tắt việc sự gắn bó cảm xúc với những nguồn lực đã bỏ ra khiến con người đưa ra các quyết định phi lý trí."},{"id":"read2_m2_q16","type":"multiple_choice","prompt":"The phrase \"throw good money after bad\" in the passage refers to","options":{"A":"making a wise investment based on past success.","B":"investing more in a failing venture due to prior losses.","C":"donating money to a charitable cause.","D":"carefully calculating future returns."},"correct_answer":"B","explanation":"Thành ngữ ''throw good money after bad'' chỉ hành động tiếp tục đổ thêm tiền bạc vào dự án thua lỗ vì tiếc tiền đã mất."},{"id":"read2_m2_q17","type":"multiple_choice","prompt":"According to the passage, a rational economic decision is one that","options":{"A":"prioritizes the recovery of all initial costs.","B":"is based solely on the amount of money already spent.","C":"considers the emotional weight of past investments.","D":"focuses on future outcomes, ignoring irrecoverable costs."},"correct_answer":"D","explanation":"Quyết định kinh tế hợp lý đòi hỏi phớt lờ chi phí đã mất và chỉ tập trung đánh giá kết quả tương lai."},{"id":"read2_m2_q18","type":"multiple_choice","prompt":"Why does the author mention public policy?","options":{"A":"To provide an example of a domain where the sunk cost fallacy is irrelevant.","B":"To illustrate the broad applicability and negative consequences of the bias.","C":"To argue that political embarrassment is a rational reason to continue projects.","D":"To suggest that governments are better at avoiding the fallacy than businesses."},"correct_answer":"B","explanation":"Tác giả nêu ví dụ về chính sách công để minh chứng sự ảnh hưởng sâu rộng và hậu quả tiêu cực của thiên kiến này ở cấp độ chính phủ."},{"id":"read2_m2_q19","type":"multiple_choice","prompt":"It can be inferred from the passage that overcoming the sunk cost fallacy involves","options":{"A":"increasing one''s emotional attachment to past decisions.","B":"conducting a more thorough analysis of already-spent resources.","C":"re-evaluating decisions based on their future potential.","D":"avoiding any project that requires significant initial investment."},"correct_answer":"C","explanation":"Đoạn cuối nhấn mạnh: vượt qua thiên kiến đòi hỏi chuyển hướng từ nhìn về chi phí quá khứ sang đánh giá tiềm năng và lợi ích tương lai."}]}}]}],"description":"Bộ đề TOEFL iBT Reading 2026 chuẩn ETS: Module 1 (Complete the Words Rừng Amazon, Đổi trả hàng, Giảm rác thải văn phòng, Lý sinh định vị từ trường) & Module 2 (Complete the Words Ngôn ngữ và tư duy, Tình nguyện trạm cứu hộ, Hẹn cà phê, Chi phí chìm Sunk Costs).","youtube_url":"https://www.youtube.com/watch?v=iAAuHU30Xns","source":"YouTube TOEFL 2026 Reading Practice 1","created_at_ms":1791231607963}'::jsonb,
  timezone('utc'::text, now())
)
ON CONFLICT (id) DO UPDATE SET
  title = EXCLUDED.title,
  skill = EXCLUDED.skill,
  task_type = EXCLUDED.task_type,
  duration_seconds = EXCLUDED.duration_seconds,
  content = EXCLUDED.content;

INSERT INTO public.tests (id, title, skill, task_type, duration_seconds, content, created_at)
VALUES (
  'reading-practice-03',
  'Reading Practice Test 03 (TOEFL 2026 - Biomimicry & Dunning-Kruger)',
  'reading',
  'multistage',
  1800,
  '{"stages":[{"id":"read3_stage_1","title":"Reading - Module 1 (Stage 1)","duration_seconds":900,"description":"Module 1 gồm 4 phần (19 câu hỏi). Hãy hoàn thành trước khi hết 15 phút.","tasks":[{"id":"read3_m1_t1","title":"Task 1: Complete the Words (Đoạn 1 - Solar Energy)","task_type":"complete_words","content":{"instructions":"Điền các chữ cái còn thiếu vào vị trí dấu gạch dưới `_` trong đoạn văn học thuật dưới đây.","paragraph":"Solar energy is a renewable resource that harnesses power from the sun using photovoltaic cells. These ce[lls] convert sunli[ght] directly in[to] electricity with[out] producing har[mful] emissions. Alt[hough] solar pan[els] can b[e] expensive to ins[tall], they signifi[cantly] reduce energy costs over time. In addition to powering homes and businesses, solar technology can provide electricity in remote areas where traditional grids are unavailable. Continued technological improvements are making solar energy more efficient, accessible, and essential for a sustainable future.","blanks":[{"id":"read3_m1_t1_b1","prefix":"ce","missing":"lls","full":"cells"},{"id":"read3_m1_t1_b2","prefix":"sunli","missing":"ght","full":"sunlight"},{"id":"read3_m1_t1_b3","prefix":"in","missing":"to","full":"into"},{"id":"read3_m1_t1_b4","prefix":"with","missing":"out","full":"without"},{"id":"read3_m1_t1_b5","prefix":"har","missing":"mful","full":"harmful"},{"id":"read3_m1_t1_b6","prefix":"Alt","missing":"hough","full":"Although"},{"id":"read3_m1_t1_b7","prefix":"pan","missing":"els","full":"panels"},{"id":"read3_m1_t1_b8","prefix":"b","missing":"e","full":"be"},{"id":"read3_m1_t1_b9","prefix":"ins","missing":"tall","full":"install"},{"id":"read3_m1_t1_b10","prefix":"signifi","missing":"cantly","full":"significantly"}]}},{"id":"read3_m1_t2","title":"Task 2: Read a Poster (Community Lecture Series)","task_type":"read_daily_life","content":{"document_type":"Poster","passage":"Community Lecture Series\nTopic: The Future of Urban Transportation\nDate: Wednesday, October 12\nTime: 6:30 pm\nLocation: City Hall Auditorium\nAdmission: Free\n\nJoin urban planner Dr. Mei Chen for a discussion on how electric vehicles, bike lanes, and improved public transit systems are shaping the future of city living. Open to the public – no registration required.","questions":[{"id":"read3_m1_q11","type":"multiple_choice","prompt":"What is the main purpose of this event?","options":{"A":"To promote new public transportation systems","B":"To gather feedback on new government policies","C":"To present a proposal for new city infrastructure","D":"To discuss recent trends in city transportation"},"correct_answer":"D","explanation":"Sự kiện được tổ chức để thảo luận về xu hướng tương lai của giao thông đô thị (''how electric vehicles, bike lanes, and improved public transit systems are shaping the future of city living'')."},{"id":"read3_m1_q12","type":"multiple_choice","prompt":"Who can attend the event?","options":{"A":"Only transportation professionals","B":"Public speakers only","C":"Anyone interested in the topic","D":"Registered participants only"},"correct_answer":"C","explanation":"Poster nêu rõ ''Open to the public – no registration required'', nghĩa là bất kỳ ai quan tâm đều có thể tham dự mà không cần đăng ký."}]}},{"id":"read3_m1_t3","title":"Task 3: Read an Email (Internship Information Session)","task_type":"read_daily_life","content":{"document_type":"Email Announcement","passage":"From: careercenter@unicitymail.edu\nSubject: Internship Information Session\n\nDear Students,\nAre you interested in gaining hands-on experience this summer? Join our internship information session this Friday at 2 p.m. in Room 204, where representatives from local companies will explain available positions and the application process. Attendance is free, but please register in advance using the link below.","questions":[{"id":"read3_m1_q13","type":"multiple_choice","prompt":"What is the main purpose of this email?","options":{"A":"To inform students about an opportunity to learn more about internships","B":"To encourage students to apply directly for summer internship positions","C":"To collect student registration data for local company programs","D":"To provide updates on changes to the summer internship schedule"},"correct_answer":"A","explanation":"Email thông báo và mời sinh viên tham gia buổi thông tin nhằm tìm hiểu về các cơ hội thực tập mùa hè."},{"id":"read3_m1_q14","type":"multiple_choice","prompt":"What are students asked to do before attending the session?","options":{"A":"Submit an internship application in advance","B":"Confirm attendance by paying a small deposit","C":"Bring a printed copy of their résumé","D":"Complete the online registration form"},"correct_answer":"D","explanation":"Email yêu cầu: ''Attendance is free, but please register in advance using the link below'' (hoàn thành đăng ký trực tuyến trước)."}]}},{"id":"read3_m1_t4","title":"Task 4: Academic Passage (Biomimicry in Material Science)","task_type":"academic_passage","content":{"document_type":"Material Science Passage","passage":"Biomimicry, the practice of emulating nature''s models to solve human problems, has led to groundbreaking advances in material science.\n\nThe lotus leaf, for example, with its self-cleaning properties, has inspired superhydrophobic coatings. Its microscopic, wax-covered structures cause water to bead up and roll off, carrying dirt particles away.\n\nSimilarly, the incredibly strong yet lightweight structure of spider silk, a protein fiber, has spurred research into synthetic polymers for use in bulletproof vests and medical sutures.\n\nPerhaps one of the most celebrated examples is the gecko''s foot. Geckos can scale vertical surfaces due to millions of microscopic hairs (setae) on their toes that exploit van der Waals forces – weak intermolecular attractions – providing strong adhesive power without liquid glue or suction. This principle has been adapted to create powerful yet reusable adhesive tapes.\n\nThese innovations demonstrate that nature, refined by billions of years of evolution, offers a vast repository of sustainable and efficient design solutions.","questions":[{"id":"read3_m1_q15","type":"multiple_choice","prompt":"What is the main point the author makes about biomimicry?","options":{"A":"It is a recent fad that has yielded few practical results.","B":"It provides a source of efficient and sustainable designs from nature.","C":"Its primary application is in the development of new adhesives.","D":"It is most useful for understanding biological processes rather than creating materials."},"correct_answer":"B","explanation":"Ý chính của bài viết được kết luận ở câu cuối: thiên nhiên cung cấp nguồn ý tưởng thiết kế hiệu quả và bền vững (sustainable and efficient design solutions)."},{"id":"read3_m1_q16","type":"multiple_choice","prompt":"The word \"exploit\" in the passage is closest in meaning to","options":{"A":"waste","B":"generate","C":"utilize","D":"misunderstand"},"correct_answer":"C","explanation":"''Exploit'' trong ngữ cảnh tận dụng cơ chế vật lý (van der Waals forces) đồng nghĩa với ''utilize'' (tận dụng, khai thác)."},{"id":"read3_m1_q17","type":"multiple_choice","prompt":"According to the passage, what do the lotus leaf and gecko''s foot have in common?","options":{"A":"Both rely on chemical secretions for their properties.","B":"Both have inspired practical human applications through their physical structures.","C":"Both are being used directly in commercial products.","D":"Their properties are primarily due to their chemical composition."},"correct_answer":"B","explanation":"Cả lá sen (cấu trúc vi mô phủ sáp) và chân tắc kè (hàng triệu sợi lông siêu vi) đều truyền cảm hứng ứng dụng thực tế thông qua các cấu trúc vật lý của chúng."},{"id":"read3_m1_q18","type":"multiple_choice","prompt":"The author mentions \"billions of years of evolution\" primarily to","options":{"A":"suggest that biomimicry is a slow process.","B":"highlight the proven efficacy of natural designs.","C":"argue that human science is inferior to natural selection.","D":"explain the complexity of van der Waals forces."},"correct_answer":"B","explanation":"Tác giả nhắc đến hàng tỷ năm tiến hóa để nhấn mạnh rằng các thiết kế của tự nhiên đã được tôi luyện và chứng minh hiệu quả vượt trội qua thời gian."},{"id":"read3_m1_q19","type":"multiple_choice","prompt":"Which of the following is NOT mentioned as an application of biomimicry?","options":{"A":"Self cleaning surfaces","B":"Medical sutures","C":"Energy generation","D":"Reusable adhesives"},"correct_answer":"C","explanation":"Bài đọc đề cập đến bề mặt tự làm sạch (lotus leaf), chỉ khâu y tế (spider silk), băng dính tái sử dụng (gecko''s foot); không hề đề cập đến ''Energy generation''."}]}}]},{"id":"read3_stage_2","title":"Reading - Module 2 (Stage 2)","duration_seconds":900,"description":"Module 2 gồm 4 phần (19 câu hỏi). Hãy hoàn thành trước khi hết 15 phút.","tasks":[{"id":"read3_m2_t1","title":"Task 1: Complete the Words (Đoạn 2 - Volcanoes)","task_type":"complete_words","content":{"instructions":"Điền các chữ cái còn thiếu vào vị trí dấu gạch dưới `_` trong đoạn văn học thuật dưới đây.","paragraph":"Volcanoes are geological structures that form when molten rock, or magma, rises from beneath the Earth''s crust. Eruptions c[an] be b[oth] destructive and bene[ficial]. While th[ey] may dest[roy] nearby settle[ments] and alt[er] landscapes, they al[so] enrich the so[il] with mine[rals] and create new landforms. Scientists monitor volcanic activity to predict eruptions and reduce the risk to human life. Understanding volcanic behavior contributes to both safety and knowledge about the dynamic processes of our planet.","blanks":[{"id":"read3_m2_t1_b1","prefix":"c","missing":"an","full":"can"},{"id":"read3_m2_t1_b2","prefix":"b","missing":"oth","full":"both"},{"id":"read3_m2_t1_b3","prefix":"bene","missing":"ficial","full":"beneficial"},{"id":"read3_m2_t1_b4","prefix":"th","missing":"ey","full":"they"},{"id":"read3_m2_t1_b5","prefix":"dest","missing":"roy","full":"destroy"},{"id":"read3_m2_t1_b6","prefix":"settle","missing":"ments","full":"settlements"},{"id":"read3_m2_t1_b7","prefix":"alt","missing":"er","full":"alter"},{"id":"read3_m2_t1_b8","prefix":"al","missing":"so","full":"also"},{"id":"read3_m2_t1_b9","prefix":"so","missing":"il","full":"soil"},{"id":"read3_m2_t1_b10","prefix":"mine","missing":"rals","full":"minerals"}]}},{"id":"read3_m2_t2","title":"Task 2: Read an Ad (Weekend Getaway Deal)","task_type":"read_daily_life","content":{"document_type":"Advertisement","passage":"Weekend Getaway Deal – Mountain Lodge Resort\n\nEscape city life and enjoy a peaceful weekend surrounded by nature!\n\nBook a two-night stay between Friday and Sunday and get 30% off spa treatments. Activities include guided hikes, yoga by the lake, and evening bonfires. Offer valid through November 30.","questions":[{"id":"read3_m2_q11","type":"multiple_choice","prompt":"What is being advertised?","options":{"A":"A seasonal wellness retreat featuring yoga and hiking","B":"A limited-time offer for weekend stays at a mountain resort","C":"A promotional campaign for outdoor fitness programs","D":"A special discount on luxury spa memberships"},"correct_answer":"B","explanation":"Mẩu quảng cáo giới thiệu gói ưu đãi cuối tuần tại khu nghỉ dưỡng trên núi Mountain Lodge Resort (''Weekend Getaway Deal – Mountain Lodge Resort... Offer valid through November 30'')."},{"id":"read3_m2_q12","type":"multiple_choice","prompt":"Which benefit is offered to guests?","options":{"A":"Complimentary guided activities","B":"Free room upgrades upon arrival","C":"Reduced prices on spa services during eligible stays","D":"Bonus nights for bookings over the weekend"},"correct_answer":"C","explanation":"Quảng cáo ghi: ''Book a two-night stay between Friday and Sunday and get 30% off spa treatments'' (giảm giá 30% dịch vụ spa)."}]}},{"id":"read3_m2_t3","title":"Task 3: Read an Announcement (School District Update)","task_type":"read_daily_life","content":{"document_type":"School Announcement","passage":"School District Update\nDue to ongoing construction at Lincoln Elementary, classes will temporarily move to Jefferson Middle School starting next Monday. The schedule and bus routes will remain the same. Families will receive more details via email later this week.","questions":[{"id":"read3_m2_q13","type":"multiple_choice","prompt":"What is the main purpose of the announcement?","options":{"A":"To inform parents about the completion of construction work","B":"To explain new transportation procedures for Lincoln students","C":"To announce improvements being made at Jefferson Middle School","D":"To notify families about a short-term relocation of classes"},"correct_answer":"D","explanation":"Mục đích chính là thông báo cho phụ huynh về việc chuyển tạm thời địa điểm học sang trường Jefferson Middle School trong thời gian thi công."},{"id":"read3_m2_q14","type":"multiple_choice","prompt":"What can be inferred from the notice?","options":{"A":"Students will attend classes at a different site but follow their usual routine.","B":"The construction work at Lincoln Elementary is nearly finished.","C":"Parents must arrange private transportation for their children.","D":"Classes at Jefferson Middle School are being suspended for Lincoln students to use the building."},"correct_answer":"A","explanation":"Thông báo nêu: học sinh chuyển địa điểm sang trường khác, nhưng ''The schedule and bus routes will remain the same'' (thời khóa biểu và lộ trình xe buýt vẫn như thường lệ)."}]}},{"id":"read3_m2_t4","title":"Task 4: Academic Passage (The Dunning-Kruger Effect)","task_type":"academic_passage","content":{"document_type":"Cognitive Psychology Passage","passage":"The Dunning-Kruger effect is a cognitive bias wherein individuals with low ability at a task overestimate their ability. The postulated mechanism is a dual burden: these individuals not only perform poorly but also lack the metacognitive skill to accurately evaluate their performance, creating a cycle of ignorance and confidence.\n\nConversely, highly competent individuals may underestimate their relative competence, assuming that tasks which are easy for them are equally easy for others.\n\nThis creates a perverse cognitive landscape where the unskilled are buoyed by illusory superiority, while the expert is plagued by doubt. The effect has been demonstrated across domains from logical reasoning to emotional intelligence.\n\nMitigating it is challenging, as the very skills needed for accurate self-assessment are the ones lacking. Education and training that focus on metacognition – \"thinking about thinking\" – can help calibrate self-perception, but the bias remains a robust feature of human psychology.","questions":[{"id":"read3_m2_q15","type":"multiple_choice","prompt":"The passage primarily discusses a cognitive bias that","options":{"A":"affects only experts in their respective fields.","B":"causes everyone to overestimate their abilities.","C":"creates a mismatch between ability and self-assessment.","D":"is easily corrected through simple self-reflection."},"correct_answer":"C","explanation":"Thiên kiến Dunning-Kruger tạo ra sự bất cân xứng, sai lệch lớn giữa năng lực thực tế và sự tự đánh giá của bản thân (người kém thì tự tin thái quá, người giỏi thì nghi ngờ năng lực)."},{"id":"read3_m2_q16","type":"multiple_choice","prompt":"According to the passage, what is the \"dual burden\" experienced by low-ability individuals?","options":{"A":"High intelligence and low confidence","B":"Poor performance and an inability to recognize it","C":"A desire to learn and a lack of opportunity","D":"Strong metacognitive skills and weak practical skills"},"correct_answer":"B","explanation":"Đoạn 1 chỉ rõ: ''dual burden: these individuals not only perform poorly but also lack the metacognitive skill to accurately evaluate their performance''."},{"id":"read3_m2_q17","type":"multiple_choice","prompt":"The word \"perverse\" in the passage is closest in meaning to","options":{"A":"straightforward","B":"irrational","C":"encouraging","D":"temporary"},"correct_answer":"B","explanation":"''Perverse'' trong ngữ cảnh nghịch lý, trái ngược với lý lẽ thông thường (kẻ dốt thì kiêu ngạo, người tài lại hoài nghi) đồng nghĩa với ''irrational'' (nghịch lý, phi lý)."},{"id":"read3_m2_q18","type":"multiple_choice","prompt":"Why does the author mention that \"tasks which are easy for them are equally easy for others\" when discussing experts?","options":{"A":"To illustrate the experts'' logical reasoning skills.","B":"To explain why experts often fail simple tasks.","C":"To describe the experts'' tendency toward underestimation.","D":"To show that experts are generally overconfident."},"correct_answer":"C","explanation":"Tác giả nêu điều này để giải thích xu hướng tự đánh giá thấp (underestimation) của các chuyên gia khi cho rằng điều gì dễ với mình cũng dễ với người khác."},{"id":"read3_m2_q19","type":"multiple_choice","prompt":"What does the passage suggest about mitigating the Dunning-Kruger effect?","options":{"A":"It is a simple process that requires minimal effort.","B":"It is impossible because the bias is a fundamental part of human nature.","C":"It can be addressed by focusing on metacognitive skills, though it is difficult.","D":"It is best achieved by avoiding education and training altogether."},"correct_answer":"C","explanation":"Đoạn cuối nhấn mạnh: việc giảm thiểu tuy thách thức nhưng có thể thực hiện thông qua đào tạo kỹ năng siêu nhận thức (metacognition – ''thinking about thinking'')."}]}}]}],"description":"Bộ đề TOEFL iBT 2026 Multistage Adaptive (YouTube Practice 2): Module 1 (Solar Energy, Community Lecture, Internship Info, Biomimicry) & Module 2 (Volcanoes, Mountain Lodge Resort, Lincoln Elementary Relocation, Dunning-Kruger Effect).","created_at_ms":1791231607964}'::jsonb,
  timezone('utc'::text, now())
)
ON CONFLICT (id) DO UPDATE SET
  title = EXCLUDED.title,
  skill = EXCLUDED.skill,
  task_type = EXCLUDED.task_type,
  duration_seconds = EXCLUDED.duration_seconds,
  content = EXCLUDED.content;

INSERT INTO public.tests (id, title, skill, task_type, duration_seconds, content, created_at)
VALUES (
  'reading-practice-04',
  'Reading Practice Test 04 (TOEFL 2026 - Linguistic Relativity & Epigenetics)',
  'reading',
  'multistage',
  1800,
  '{"stages":[{"id":"read4_stage_1","title":"Reading - Module 1 (Stage 1)","duration_seconds":900,"description":"Module 1 gồm 4 phần (20 câu hỏi). Hãy hoàn thành trước khi hết 15 phút.","tasks":[{"id":"read4_m1_t1","title":"Task 1: Complete the Words (Đoạn 1 - The Printing Press)","task_type":"complete_words","content":{"instructions":"Điền các chữ cái còn thiếu vào vị trí dấu gạch dưới `_` trong đoạn văn học thuật dưới đây.","paragraph":"The invention of the printing press by Johannes Gutenberg in the fifteenth century transformed human communication. Bef[ore] this inve[ntion], books we[re] copied b[y] hand, mak[ing] them expe[nsive] and ra[re]. The prin[ting] press allo[wed] ideas to spr[ead] rapidly, fueling the Renaissance and the Reformation. It also encouraged literacy and education among ordinary people. Today, Gutenberg''s innovation is regarded as one of the most important developments in human history, laying the foundation for the modern knowledge-based society.","blanks":[{"id":"read4_m1_t1_b1","prefix":"Bef","missing":"ore","full":"Before"},{"id":"read4_m1_t1_b2","prefix":"inve","missing":"ntion","full":"invention"},{"id":"read4_m1_t1_b3","prefix":"we","missing":"re","full":"were"},{"id":"read4_m1_t1_b4","prefix":"b","missing":"y","full":"by"},{"id":"read4_m1_t1_b5","prefix":"mak","missing":"ing","full":"making"},{"id":"read4_m1_t1_b6","prefix":"expe","missing":"nsive","full":"expensive"},{"id":"read4_m1_t1_b7","prefix":"ra","missing":"re","full":"rare"},{"id":"read4_m1_t1_b8","prefix":"prin","missing":"ting","full":"printing"},{"id":"read4_m1_t1_b9","prefix":"allo","missing":"wed","full":"allowed"},{"id":"read4_m1_t1_b10","prefix":"spr","missing":"ead","full":"spread"}]}},{"id":"read4_m1_t2","title":"Task 2: Read a Restaurant Menu (Lunch Specials)","task_type":"read_daily_life","content":{"document_type":"Restaurant Menu","passage":"MENU\nLunch Specials\n(11 a.m.–3 p.m.)\n\nGrilled Chicken Wrap – $10\n(served with chips)\nVegetarian Lasagna – $12\n(includes garlic bread)\nShrimp Tacos (3 pcs) – $14\n\nIncludes a drink of your choice: iced tea, coffee, or soda.\nAdd a side salad for $3 or upgrade your drink to fresh juice for $2.\nLunch specials are available Monday through Friday.","questions":[{"id":"read4_m1_q11","type":"multiple_choice","prompt":"What is true about the lunch specials?","options":{"A":"They come with a side salad.","B":"They are available every day of the week.","C":"They are available only in the afternoon.","D":"They are served with a drink included."},"correct_answer":"D","explanation":"Thực đơn nêu rõ: ''Includes a drink of your choice: iced tea, coffee, or soda'' (đã bao gồm đồ uống đi kèm)."},{"id":"read4_m1_q12","type":"multiple_choice","prompt":"How much would a Shrimp Taco meal with a side salad and a coffee cost?","options":{"A":"$14","B":"$16","C":"$17","D":"$19"},"correct_answer":"C","explanation":"Món Shrimp Tacos có giá $14 (đã kèm cà phê) + thêm side salad $3 = $17."}]}},{"id":"read4_m1_t3","title":"Task 3: Read a Webpage Notice (Campus IT Services)","task_type":"read_daily_life","content":{"document_type":"Webpage Notice","passage":"Update from Campus IT Services\n\nStarting this weekend, all university email passwords will automatically expire every 90 days.\nUsers will receive a reminder 10 days before expiration, containing a secure link to reset their passwords. Those who fail to reset their passwords in time may temporarily lose access to their email and online course platforms.\nThis new policy is part of the university''s effort to enhance data protection and prevent unauthorized access to student information.","questions":[{"id":"read4_m1_q13","type":"multiple_choice","prompt":"What is the reason for this policy update?","options":{"A":"To make logging in faster","B":"To protect sensitive data","C":"To simplify password recovery","D":"To comply with university attendance rules"},"correct_answer":"B","explanation":"Câu cuối nêu rõ mục đích: ''part of the university''s effort to enhance data protection and prevent unauthorized access to student information''."},{"id":"read4_m1_q14","type":"multiple_choice","prompt":"What will users receive before their passwords expire?","options":{"A":"A security code","B":"A call from IT support","C":"A warning message","D":"A list of old passwords"},"correct_answer":"C","explanation":"Thông báo nêu: ''Users will receive a reminder 10 days before expiration, containing a secure link to reset their passwords'' (một lời nhắc / cảnh báo trước khi hết hạn)."},{"id":"read4_m1_q15","type":"multiple_choice","prompt":"What may happen if users don''t reset their passwords on time?","options":{"A":"Their accounts will be permanently deleted","B":"They may be locked out of their accounts temporarily","C":"Their passwords will reset automatically","D":"They will need to create a new university email account"},"correct_answer":"B","explanation":"Bài đọc nêu: ''Those who fail to reset their passwords in time may temporarily lose access to their email and online course platforms''."}]}},{"id":"read4_m1_t4","title":"Task 4: Academic Passage (The Concept of Linguistic Relativity)","task_type":"academic_passage","content":{"document_type":"Linguistics & Cognitive Science Passage","passage":"The principle of linguistic relativity, often associated with the Sapir-Whorf hypothesis, posits that the structure of a language influences its speakers'' worldview and cognition.\n\nThe strong version, linguistic determinism, argues that language determines thought and that linguistic categories limit cognitive categories. This view is largely discredited.\n\nHowever, a weaker, more tenable version suggests that language influences thought processes, such as memory, perception, and attention.\n\nFor example, speakers of languages that have multiple distinct words for blue (e.g., light blue vs. dark blue) may be faster at discriminating between these shades. Similarly, languages that use cardinal directions (north, south) instead of egocentric coordinates (left, right) require their speakers to maintain a constant, subconscious awareness of their orientation in space.\n\nWhile evidence for the strong version is scant, a growing body of research supports the weak version, indicating that the language we speak can shape, though not imprison, our cognitive habits.","questions":[{"id":"read4_m1_q16","type":"multiple_choice","prompt":"What is the main idea of the passage?","options":{"A":"The strong version of the Sapir-Whorf hypothesis has been conclusively proven.","B":"Language may influence how we think, but it does not strictly determine it.","C":"All cognitive processes are entirely dependent on the language one speaks.","D":"The concept of linguistic relativity has been rejected by modern science."},"correct_answer":"B","explanation":"Ý chính của bài viết là ngôn ngữ có thể định hình và ảnh hưởng đến tư duy và nhận thức nhưng không quyết định hay trói buộc nó tuyệt đối (weak version được ủng hộ, strong version bị bác bỏ)."},{"id":"read4_m1_q17","type":"multiple_choice","prompt":"The word \"tenable\" in the passage is closest in meaning to","options":{"A":"defensible","B":"weak","C":"outdated","D":"radical"},"correct_answer":"A","explanation":"''Tenable'' có nghĩa là có thể bảo vệ được bằng lý lẽ hoặc chứng cứ thực tế, đồng nghĩa với ''defensible''."},{"id":"read4_m1_q18","type":"multiple_choice","prompt":"According to the passage, how might a language that uses cardinal directions affect its speakers?","options":{"A":"It would make them worse at giving directions.","B":"It would force them to think longer.","C":"It would require them to be constantly aware of their spatial orientation.","D":"It would limit their vocabulary for describing colors."},"correct_answer":"C","explanation":"Đoạn 4 nêu rõ: ''require their speakers to maintain a constant, subconscious awareness of their orientation in space''."},{"id":"read4_m1_q19","type":"multiple_choice","prompt":"The author discusses the example of words for blue primarily to","options":{"A":"prove the strong version of linguistic determinism.","B":"illustrate a potential influence of language on perception.","C":"argue that some languages are more descriptive than others.","D":"show that color perception is universal across cultures."},"correct_answer":"B","explanation":"Ví dụ về các từ chỉ màu xanh lam minh họa cho luận điểm phiên bản yếu: ngôn ngữ tác động đến quá trình tri giác thị giác (perception)."},{"id":"read4_m1_q20","type":"multiple_choice","prompt":"What is the relationship between the strong and weak versions of linguistic relativity as described in the passage?","options":{"A":"The weak version is a more extreme form of the strong version.","B":"The strong version is a widely accepted refinement of the weak version.","C":"The weak version is a less absolute and more supported alternative to the strong version.","D":"Both versions are considered equally valid by contemporary researchers."},"correct_answer":"C","explanation":"Phiên bản yếu (weak version) là một sự thay thế bớt tuyệt đối đoan hơn và nhận được nhiều bằng chứng khoa học ủng hộ hơn so với phiên bản quyết định luận cứng nhắc (strong version)."}]}}]},{"id":"read4_stage_2","title":"Reading - Module 2 (Stage 2)","duration_seconds":900,"description":"Module 2 gồm 4 phần (20 câu hỏi). Hãy hoàn thành trước khi hết 15 phút.","tasks":[{"id":"read4_m2_t1","title":"Task 1: Complete the Words (Đoạn 2 - Photosynthesis)","task_type":"complete_words","content":{"instructions":"Điền các chữ cái còn thiếu vào vị trí dấu gạch dưới `_` trong đoạn văn học thuật dưới đây.","paragraph":"Photosynthesis is the process by which green plants convert sunlight into chemical energy. Using chlorophyll, they abs[orb] light and trans[form] carbon diox[ide] and wat[er] into gluco[se] and oxy[gen]. This proc[ess] not on[ly] sustains pl[ant] life b[ut] also provides the oxygen that animals and humans breathe. Without photosynthesis, life on Earth would not exist in its current form. Scientists study this process to develop artificial methods of capturing solar energy efficiently for renewable power.","blanks":[{"id":"read4_m2_t1_b1","prefix":"abs","missing":"orb","full":"absorb"},{"id":"read4_m2_t1_b2","prefix":"trans","missing":"form","full":"transform"},{"id":"read4_m2_t1_b3","prefix":"diox","missing":"ide","full":"dioxide"},{"id":"read4_m2_t1_b4","prefix":"wat","missing":"er","full":"water"},{"id":"read4_m2_t1_b5","prefix":"gluco","missing":"se","full":"glucose"},{"id":"read4_m2_t1_b6","prefix":"oxy","missing":"gen","full":"oxygen"},{"id":"read4_m2_t1_b7","prefix":"proc","missing":"ess","full":"process"},{"id":"read4_m2_t1_b8","prefix":"on","missing":"ly","full":"only"},{"id":"read4_m2_t1_b9","prefix":"pl","missing":"ant","full":"plant"},{"id":"read4_m2_t1_b10","prefix":"b","missing":"ut","full":"but"}]}},{"id":"read4_m2_t2","title":"Task 2: Read a Sign (City Library Announcement)","task_type":"read_daily_life","content":{"document_type":"Library Sign","passage":"City Library Announcement\n\nDue to maintenance, the City Library will close early at 5 p.m. from Monday to Thursday next week. Weekend hours remain unchanged.\n\nDuring this period, you can still return borrowed books using the drop box at the main entrance or access digital materials through the library''s online portal. We apologize for any inconvenience.","questions":[{"id":"read4_m2_q11","type":"multiple_choice","prompt":"What is the main purpose of this notice?","options":{"A":"To advertise the library''s new online services","B":"To inform users about temporary changes in operating hours","C":"To announce the renovation of the entire building","D":"To explain how to borrow books"},"correct_answer":"B","explanation":"Thông báo nhằm cập nhật giờ mở cửa tạm thời (đóng cửa sớm lúc 5h chiều từ Thứ Hai đến Thứ Năm do bảo trì)."},{"id":"read4_m2_q12","type":"multiple_choice","prompt":"What will remain the same during the maintenance period?","options":{"A":"The library''s weekday closing time","B":"The main entrance location","C":"Access to physical books","D":"The schedule for the weekend"},"correct_answer":"D","explanation":"Thông báo chỉ rõ: ''Weekend hours remain unchanged'' (giờ mở cửa vào cuối tuần vẫn giữ nguyên)."}]}},{"id":"read4_m2_t3","title":"Task 3: Read a Social Media Post (Lunchtime Meditation Group)","task_type":"read_daily_life","content":{"document_type":"Social Media Post","passage":"Feeling overwhelmed at work? Take a mindful break and join our Lunchtime Meditation Group at Central Park, every Tuesday from 12:30 to 12:55 p.m.\n\nEach 25-minute session, led by a certified mindfulness coach, focuses on simple breathing and relaxation techniques that can help reduce stress and improve focus.\n\nParticipation is free, but please bring your own mat or towel. No prior experience is required – just come with an open mind and a calm spirit.","questions":[{"id":"read4_m2_q13","type":"multiple_choice","prompt":"What is the main purpose of the post?","options":{"A":"To advertise yoga classes","B":"To invite people to join short meditation sessions","C":"To provide detailed instructions for meditation","D":"To announce the opening of a new wellness center"},"correct_answer":"B","explanation":"Bài đăng mời mọi người tham gia nhóm thiền ngắn vào giờ nghỉ trưa thứ Ba hàng tuần tại Công viên Trung tâm."},{"id":"read4_m2_q14","type":"multiple_choice","prompt":"Who is most likely to attend these sessions?","options":{"A":"Employees looking for a quick way to unwind during lunch","B":"People exercising in the park","C":"People who have a towel","D":"Students taking online meditation courses"},"correct_answer":"A","explanation":"Đối tượng hướng tới là người đi làm muốn thư giãn đầu óc nhanh trong giờ nghỉ trưa (''Feeling overwhelmed at work? Take a mindful break and join our Lunchtime Meditation Group'')."},{"id":"read4_m2_q15","type":"multiple_choice","prompt":"What can be inferred about the sessions?","options":{"A":"They take place indoors during bad weather","B":"They require participants to register in advance","C":"They are mostly intended for experienced meditators","D":"They are designed to fit into people''s workday schedules"},"correct_answer":"D","explanation":"Các buổi tập chỉ kéo dài 25 phút vào khung giờ nghỉ trưa 12:30 - 12:55, được thiết kế phù hợp với lịch làm việc bận rộn."}]}},{"id":"read4_m2_t4","title":"Task 4: Academic Passage (Epigenetics: Beyond the Genetic Code)","task_type":"academic_passage","content":{"document_type":"Molecular Biology & Genetics Passage","passage":"The central dogma of biology long held that DNA sequence was the sole biological inheritance, a fixed blueprint for an organism.\n\nEpigenetics, however, has revolutionized this view. It refers to the study of heritable changes in gene expression that do not involve alterations to the underlying DNA sequence. These changes, such as DNA methylation or histone modification, act as \"switches\" that turn genes on or off in response to environmental factors like diet, stress, and toxin exposure.\n\nThis means that experiences can leave a molecular scar or a benefit that can be passed to subsequent generations. For instance, studies have shown that the nutritional status of grandparents can affect the health outcomes of their grandchildren, even in the absence of continued exposure.\n\nThis Lamarckian-like inheritance challenges the strict Darwinian model and has profound implications for our understanding of evolution, disease susceptibility, and the complex interplay between nature and nurture.","questions":[{"id":"read4_m2_q16","type":"multiple_choice","prompt":"The primary purpose of the passage is to","options":{"A":"defend the central dogma of biology against new evidence.","B":"describe a field that studies non-sequence-based genetic inheritance.","C":"argue that DNA sequence is irrelevant to gene expression.","D":"detail the specific biochemical processes of DNA methylation."},"correct_answer":"B","explanation":"Mục đích chính của bài là giới thiệu và giải thích về biểu sinh học (epigenetics) - lĩnh vực nghiên cứu sự di truyền biểu hiện gen không làm biến đổi trình tự ADN gốc."},{"id":"read4_m2_q17","type":"multiple_choice","prompt":"The word \"heritable\" in the passage is closest in meaning to","options":{"A":"temporary","B":"observable","C":"transmissible","D":"harmful"},"correct_answer":"C","explanation":"''Heritable'' (có thể di truyền được sang các thế hệ sau) đồng nghĩa với ''transmissible'' (có thể truyền lại)."},{"id":"read4_m2_q18","type":"multiple_choice","prompt":"According to the passage, what is the role of environmental factors in epigenetics?","options":{"A":"They directly change the DNA sequence.","B":"They have no impact on gene expression.","C":"They can influence the chemical markers that control gene activity.","D":"They only affect the individual exposed, not their offspring."},"correct_answer":"C","explanation":"Yếu tố môi trường (dinh dưỡng, căng thẳng, độc chất) hoạt động như ''công tắc'' làm thay đổi các dấu ấn hóa học điều khiển bật/tắt hoạt động của gen mà không thay đổi trình tự ADN."},{"id":"read4_m2_q19","type":"multiple_choice","prompt":"The author mentions the \"nutritional status of grandparents\" to provide an example of","options":{"A":"the irrelevance of past generations to current health.","B":"a purely genetic disease.","C":"the transgenerational impact of epigenetic changes.","D":"a flaw in epigenetic research methodology."},"correct_answer":"C","explanation":"Tác giả dẫn chứng tình trạng dinh dưỡng của ông bà ảnh hưởng tới đời cháu để minh họa cho tác động di truyền qua nhiều thế hệ (transgenerational impact) của các biến đổi biểu sinh."},{"id":"read4_m2_q20","type":"multiple_choice","prompt":"It can be inferred from the passage that epigenetics challenges traditional views by suggesting that","options":{"A":"acquired characteristics can never be inherited.","B":"the environment can play a role in what is passed to offspring.","C":"DNA is the only source of biological information.","D":"Darwin''s theory of evolution is entirely incorrect."},"correct_answer":"B","explanation":"Biểu sinh học thách thức quan niệm truyền thống bằng việc chỉ ra rằng môi trường sống và trải nghiệm có thể đóng vai trò quyết định những gì được truyền sang thế hệ con cháu."}]}}]}],"description":"Bộ đề TOEFL iBT 2026 Multistage Adaptive (YouTube Practice 3): Module 1 (Printing Press, Lunch Menu, Campus IT, Linguistic Relativity) & Module 2 (Photosynthesis, City Library, Lunchtime Meditation, Epigenetics).","created_at_ms":1791231607964}'::jsonb,
  timezone('utc'::text, now())
)
