  content = EXCLUDED.content;

INSERT INTO public.tests (id, title, skill, task_type, duration_seconds, content, created_at)
VALUES (
  'reading-practice-05',
  'Reading Practice Test 05 (TOEFL 2026 - Keystone Species & Utilitarianism)',
  'reading',
  'multistage',
  1800,
  '{"stages":[{"id":"read5_stage_1","title":"Reading - Module 1 (Stage 1)","duration_seconds":900,"description":"Module 1 gồm 4 phần (20 câu hỏi). Hãy hoàn thành trước khi hết 15 phút.","tasks":[{"id":"read5_m1_t1","title":"Task 1: Complete the Words (Đoạn 1 - The Great Wall of China)","task_type":"complete_words","content":{"instructions":"Điền các chữ cái còn thiếu vào vị trí dấu gạch dưới `_` trong đoạn văn học thuật dưới đây.","paragraph":"The Great Wall of China is one of the most iconic structures in the world. Built ov[er] centuries, it orig[inally] served a[s] a def[ence] system ag[ainst] invasions fr[om] northern tri[bes]. Stretching thou[sands] of kil[ometers], it demon[strates] remarkable engineering and human perseverance. Although no longer used for military purposes, it remains a symbol of Chinese history and culture. Today, it attracts millions of visitors each year, highlighting the importance of preserving historical monuments.","blanks":[{"id":"read5_m1_t1_b1","prefix":"ov","missing":"er","full":"over"},{"id":"read5_m1_t1_b2","prefix":"orig","missing":"inally","full":"originally"},{"id":"read5_m1_t1_b3","prefix":"a","missing":"s","full":"as"},{"id":"read5_m1_t1_b4","prefix":"def","missing":"ence","full":"defence"},{"id":"read5_m1_t1_b5","prefix":"ag","missing":"ainst","full":"against"},{"id":"read5_m1_t1_b6","prefix":"fr","missing":"om","full":"from"},{"id":"read5_m1_t1_b7","prefix":"tri","missing":"bes","full":"tribes"},{"id":"read5_m1_t1_b8","prefix":"thou","missing":"sands","full":"thousands"},{"id":"read5_m1_t1_b9","prefix":"kil","missing":"ometers","full":"kilometers"},{"id":"read5_m1_t1_b10","prefix":"demon","missing":"strates","full":"demonstrates"}]}},{"id":"read5_m1_t2","title":"Task 2: Read an Email (Orientation Reminder)","task_type":"read_daily_life","content":{"document_type":"Email Reminder","passage":"From: StudentServices@modernuni.edu\nSubject: Orientation Reminder\n\nDear Students,\nWe look forward to welcoming you to campus! Please note that orientation will begin at 9:30 a.m. in the Main Hall this Friday. You''ll receive your student ID, meet your academic advisor, and attend a brief tour of the campus. Light refreshments will be provided. Be sure to bring a valid photo ID.\nSincerely,\nStudent Services","questions":[{"id":"read5_m1_q11","type":"multiple_choice","prompt":"What is the purpose of this email?","options":{"A":"To confirm the start of classes","B":"To announce changes in the orientation schedule","C":"To request missing student information","D":"To invite students to attend an introductory event"},"correct_answer":"D","explanation":"Email thông báo và mời sinh viên tham gia buổi định hướng chào đón tân sinh viên (''welcoming you to campus... orientation will begin at 9:30 a.m. in the Main Hall'')."},{"id":"read5_m1_q12","type":"multiple_choice","prompt":"What should students bring to the orientation?","options":{"A":"Student ID cards","B":"Academic transcripts","C":"A photo identification","D":"Admission letters"},"correct_answer":"C","explanation":"Email nhắc nhở rõ ràng: ''Be sure to bring a valid photo ID'' (giấy tờ tùy thân có ảnh hợp lệ)."}]}},{"id":"read5_m1_t3","title":"Task 3: Read an Advertisement (SkyReach Language App)","task_type":"read_daily_life","content":{"document_type":"App Advertisement","passage":"SkyReach Language App\n\nWant to learn a new language without feeling overwhelmed? SkyReach helps you practice in short, fun lessons designed by professional teachers. Track your progress, earn badges, and review tricky vocabulary anytime.\n\nStart your free 7-day trial today and experience how quickly you can improve!","questions":[{"id":"read5_m1_q13","type":"multiple_choice","prompt":"What is being promoted in this advertisement?","options":{"A":"A study-abroad program","B":"A digital learning platform","C":"A live online course with teachers","D":"A vocabulary book"},"correct_answer":"B","explanation":"Quảng cáo giới thiệu ứng dụng học ngoại ngữ số SkyReach (''SkyReach Language App... Track your progress, earn badges...'')."},{"id":"read5_m1_q14","type":"multiple_choice","prompt":"Why might users find SkyReach appealing?","options":{"A":"It offers a 7-day free trial","B":"It provides access to professional teachers","C":"It allows flexible, short practice sessions","D":"It guarantees fluency within a week"},"correct_answer":"C","explanation":"Điểm thu hút được nhấn mạnh là các bài học ngắn và linh hoạt (''helps you practice in short, fun lessons... review tricky vocabulary anytime'')."},{"id":"read5_m1_q15","type":"multiple_choice","prompt":"What feature of SkyReach is emphasized as a way to support ongoing learning?","options":{"A":"Tracking progress and earning rewards","B":"Personalized one-on-one lessons","C":"Intensive daily homework assignments","D":"Group discussion forums"},"correct_answer":"A","explanation":"Tính năng hỗ trợ duy trì động lực học tập liên tục là theo dõi tiến độ và nhận huy hiệu thưởng (''Track your progress, earn badges'')."}]}},{"id":"read5_m1_t4","title":"Task 4: Academic Passage (Trophic Cascades and Keystone Species)","task_type":"academic_passage","content":{"document_type":"Ecology & Conservation Passage","passage":"The concept of a keystone species, one that exerts a disproportionate influence on its ecosystem relative to its abundance, is central to understanding ecological stability. The removal of such a species can trigger a trophic cascade – a series of indirect effects that ripple through the food web, dramatically altering ecosystem structure and function.\n\nThe classic example is the grey wolf in Yellowstone National Park. Following their extirpation in the 1920s, elk populations surged, leading to overgrazing of willow and aspen saplings. This denudation negatively impacted beaver populations, which rely on these trees for food and dam building. The loss of beaver dams reduced aquatic habitats, affecting fish, amphibians, and riverbank structure.\n\nUpon the wolves'' reintroduction in 1995, a remarkable reversal began. The presence of wolves not only directly reduced elk numbers but also changed elk behavior, a phenomenon known as the \"ecology of fear\". Elk avoided vulnerable valleys and gorges, allowing riparian vegetation to recover. This, in turn, supported the return of beavers and the biodiversity associated with their wetlands.\n\nThis case illustrates that apex predators are not merely passengers in an ecosystem but are often fundamental architects, maintaining balance through both predation and the intimidation they inspire.","questions":[{"id":"read5_m1_q16","type":"multiple_choice","prompt":"Which of the following best expresses the main idea of the passage?","options":{"A":"Elk are the most important species in the Yellowstone ecosystem.","B":"The reintroduction of wolves was a controversial policy.","C":"Beaver dams are the primary factor in maintaining riverbank health.","D":"Keystone species can shape entire ecosystems through direct and indirect effects."},"correct_answer":"D","explanation":"Ý chính của bài là các loài chủ chốt (keystone species) có thể định hình toàn bộ hệ sinh thái thông qua các tác động trực tiếp và gián tiếp nhiều tầng bậc (trophic cascade)."},{"id":"read5_m1_q17","type":"multiple_choice","prompt":"The word \"denudation\" in the passage is closest in meaning to","options":{"A":"stripping","B":"planting","C":"fertilization","D":"cultivation"},"correct_answer":"A","explanation":"''Denudation'' trong ngữ cảnh cây cối bị chăn thả quá mức dẫn đến trơ trụi đất đai đồng nghĩa với ''stripping'' (làm trơ trụi, tước đoạt thảm thực vật)."},{"id":"read5_m1_q18","type":"multiple_choice","prompt":"According to the passage, how did the reintroduction of wolves affect elk behavior?","options":{"A":"It caused elk to congregate in larger herds in open valleys.","B":"It made elk less fearful of other predators.","C":"It led elk to avoid certain areas, allowing plants to regrow.","D":"It had no significant impact on elk behavior."},"correct_answer":"C","explanation":"Đoạn 3 nêu: ''Elk avoided vulnerable valleys and gorges, allowing riparian vegetation to recover'' (nai né tránh các thung lũng hiểm trở, tạo điều kiện cho thực vật ven bờ phục hồi)."},{"id":"read5_m1_q19","type":"multiple_choice","prompt":"The author refers to the \"ecology of fear\" in order to","options":{"A":"describe a negative consequence of wolf reintroduction.","B":"highlight a psychological problem in elk populations.","C":"argue that fear is the most important factor in ecosystem management.","D":"explain a mechanism by which wolves indirectly affect vegetation."},"correct_answer":"D","explanation":"Thuật ngữ ''ecology of fear'' giải thích cơ chế gián tiếp: nỗi sợ bị sói săn bắt làm thay đổi hành vi kiếm ăn của nai, từ đó gián tiếp giúp thảm thực vật phục hồi."},{"id":"read5_m1_q20","type":"multiple_choice","prompt":"Based on the passage, what can be inferred about the role of beavers in this trophic cascade?","options":{"A":"They were the primary cause of the overgrazing problem.","B":"Their population decline was a direct result of wolf predation.","C":"Their return was a secondary effect of the wolves'' influence on elk and vegetation.","D":"They are considered the keystone species in Yellowstone."},"correct_answer":"C","explanation":"Sự quay trở lại của hải ly là một hiệu ứng thứ cấp bắt nguồn từ việc sói kiểm soát đàn nai, giúp cây liễu mọc lại và cung cấp thức ăn cũng như vật liệu xây đập cho hải ly."}]}}]},{"id":"read5_stage_2","title":"Reading - Module 2 (Stage 2)","duration_seconds":900,"description":"Module 2 gồm 4 phần (20 câu hỏi). Hãy hoàn thành trước khi hết 15 phút.","tasks":[{"id":"read5_m2_t1","title":"Task 1: Complete the Words (Đoạn 2 - Water Resource)","task_type":"complete_words","content":{"instructions":"Điền các chữ cái còn thiếu vào vị trí dấu gạch dưới `_` trong đoạn văn học thuật dưới đây.","paragraph":"Water is a vital resource for all living organisms. It suppo[rts] plant gro[wth], regulates clim[ate], and ena[bles] biological proce[sses] in ani[mals] and hu[mans]. Despite i[ts] abundance, on[ly] a small perce[ntage] of Earth''s water is fresh and available for consumption. Increasing population and industrial pollution are putting this resource under pressure. Governments and scientists promote water conservation, improved infrastructure, and sustainable agriculture to ensure future generations have access to clean water.","blanks":[{"id":"read5_m2_t1_b1","prefix":"suppo","missing":"rts","full":"supports"},{"id":"read5_m2_t1_b2","prefix":"gro","missing":"wth","full":"growth"},{"id":"read5_m2_t1_b3","prefix":"clim","missing":"ate","full":"climate"},{"id":"read5_m2_t1_b4","prefix":"ena","missing":"bles","full":"enables"},{"id":"read5_m2_t1_b5","prefix":"proce","missing":"sses","full":"processes"},{"id":"read5_m2_t1_b6","prefix":"ani","missing":"mals","full":"animals"},{"id":"read5_m2_t1_b7","prefix":"hu","missing":"mans","full":"humans"},{"id":"read5_m2_t1_b8","prefix":"i","missing":"ts","full":"its"},{"id":"read5_m2_t1_b9","prefix":"on","missing":"ly","full":"only"},{"id":"read5_m2_t1_b10","prefix":"perce","missing":"ntage","full":"percentage"}]}},{"id":"read5_m2_t2","title":"Task 2: Read an Online Review (Mountain Peak Hotel)","task_type":"read_daily_life","content":{"document_type":"Hotel Review","passage":"I stayed at the Mountain Peak Hotel last weekend. The location is perfect – just a short walk from the hiking trails. The staff were friendly, but the Wi-Fi connection was unreliable, and breakfast choices were limited. Overall, it''s a comfortable place if you value peace and scenery more than modern facilities.","questions":[{"id":"read5_m2_q11","type":"multiple_choice","prompt":"What aspect of the hotel does the reviewer praise most?","options":{"A":"The food options","B":"The staff","C":"The setting","D":"The modern facilities"},"correct_answer":"C","explanation":"Người đánh giá khen ngợi nhất về vị trí và khung cảnh thiên nhiên (''The location is perfect – just a short walk from the hiking trails... peace and scenery'')."},{"id":"read5_m2_q12","type":"multiple_choice","prompt":"What can be inferred about the hotel?","options":{"A":"It''s more suitable for people who enjoy nature","B":"It''s mainly used for business trips","C":"It offers luxury-level comfort","D":"It''s under renovation"},"correct_answer":"A","explanation":"Khách sạn thích hợp nhất cho những người yêu thiên nhiên và sự yên tĩnh hơn là tiện nghi hiện đại (''suitable for people who enjoy nature'')."}]}},{"id":"read5_m2_t3","title":"Task 3: Read a Web Announcement (Volunteer with EcoSteps)","task_type":"read_daily_life","content":{"document_type":"Community Announcement","passage":"Volunteer with EcoSteps!\n\nEcoSteps is looking for enthusiastic volunteers for its annual river cleanup event. Participants will meet at the Riverside Park entrance at 8 a.m. on April 22. Gloves and trash bags will be provided, but please bring your own reusable water bottle. Help us protect wildlife habitats and make a tangible difference in your community!","questions":[{"id":"read5_m2_q13","type":"multiple_choice","prompt":"What is the primary aim of the EcoSteps event?","options":{"A":"To educate participants about waste management","B":"To fundraise for EcoSteps","C":"To clean the river area","D":"To provide reusable bottles to participants"},"correct_answer":"C","explanation":"Mục đích chính của sự kiện là dọn sạch rác tại khu vực sông (''annual river cleanup event'')."},{"id":"read5_m2_q14","type":"multiple_choice","prompt":"What item are volunteers advised to bring?","options":{"A":"Gloves","B":"A water bottle","C":"Trash bags","D":"Cleaning products"},"correct_answer":"B","explanation":"Găng tay và túi đựng rác sẽ được cung cấp, tình nguyện viên được khuyên mang theo bình nước cá nhân (''please bring your own reusable water bottle'')."},{"id":"read5_m2_q15","type":"multiple_choice","prompt":"What additional benefit of volunteering is mentioned in the text?","options":{"A":"Building a supportive community","B":"Gaining practical skills in environmental science","C":"Meeting professional environmentalists","D":"Making a visible difference in the community"},"correct_answer":"D","explanation":"Thông báo nêu lợi ích thiết thực: ''Help us protect wildlife habitats and make a tangible difference in your community'' (tạo nên sự khác biệt hữu hình cho cộng đồng)."}]}},{"id":"read5_m2_t4","title":"Task 4: Academic Passage (The Philosophical Underpinnings of Utilitarianism)","task_type":"academic_passage","content":{"document_type":"Philosophy & Ethics Passage","passage":"Utilitarianism is an ethical theory that posits that the right action is the one that creates the most happiness and the least suffering for the greatest number of people. Philosophers like Jeremy Bentham and John Stuart Mill developed it to give a clear way to make moral decisions: compare the benefits and harms of different actions and choose the one that produces the best overall result.\n\nBentham suggested measuring happiness with a \"hedonic calculus,\" looking at how much pleasure an action brings and how long it lasts. Mill added that some pleasures, like intellectual ones, are better than simple physical pleasures. He argued that it is better to be a dissatisfied human than a satisfied pig. This idea responded to criticism that utilitarianism could justify wrong actions if they created more overall happiness.\n\nDespite being appealing and logical, utilitarianism faces significant challenges. It can be demanding to calculate the effects of every action. It also struggles with justice and rights, as it seems to allow sacrificing an innocent individual if it benefits the majority. These criticisms highlight that focusing only on outcomes can conflict with following moral rules.","questions":[{"id":"read5_m2_q16","type":"multiple_choice","prompt":"What is the main purpose of the text?","options":{"A":"To argue that happiness is the only moral value.","B":"To prove that Jeremy Bentham''s ideas were superior to John Stuart Mill''s.","C":"To explain that utilitarianism is always wrong.","D":"To trace the development and outline key criticisms of a philosophical theory."},"correct_answer":"D","explanation":"Bài viết phác thảo nguồn gốc phát triển của thuyết vị lợi (Bentham, Mill) đồng thời chỉ ra những chỉ trích, thách thức cơ bản đối với thuyết này."},{"id":"read5_m2_q17","type":"multiple_choice","prompt":"The word \"criticisms\" in paragraph 3 is closest in meaning to:","options":{"A":"praise","B":"complaints","C":"instructions","D":"rules"},"correct_answer":"B","explanation":"''Criticisms'' (những lời chỉ trích, phê bình, phàn nàn về hạn chế của thuyết) đồng nghĩa với ''complaints''."},{"id":"read5_m2_q18","type":"multiple_choice","prompt":"According to the passage, what was the key difference between Bentham''s and Mill''s versions of utilitarianism?","options":{"A":"Bentham focused on the quantity of pleasure, while Mill emphasized the quality of pleasures.","B":"Mill rejected the idea of increasing happiness.","C":"Mill focused only on physical pleasures.","D":"Bentham believed only humans deserved moral consideration, while Mill included animals."},"correct_answer":"A","explanation":"Bentham tập trung vào lượng khoái lạc qua ''hedonic calculus'', trong khi Mill bổ sung yếu tố phẩm chất/chất lượng của khoái lạc (khoái lạc trí tuệ cao quý hơn khoái lạc thể xác đơn thuần)."},{"id":"read5_m2_q19","type":"multiple_choice","prompt":"Why does the author mention the \"sacrificing of an innocent individual\"?","options":{"A":"To provide an example of a utilitarian successful decision.","B":"To illustrate a potential problem with utilitarianism.","C":"To demonstrate how utilitarianism protects individual rights.","D":"To show that this scenario never happens in real life."},"correct_answer":"B","explanation":"Tác giả dẫn ví dụ hy sinh người vô tội để minh họa cho lỗ hổng nghiêm trọng của thuyết vị lợi khi chỉ nhìn vào kết quả tổng thể mà bỏ qua công lý và quyền cơ bản của cá nhân."},{"id":"read5_m2_q20","type":"multiple_choice","prompt":"What can be inferred about utilitarianism from the text?","options":{"A":"It is the easiest ethical theory to apply in daily life.","B":"It was developed without any consideration for human happiness.","C":"It may conflict with fairness or moral rules.","D":"It is too concerned with individual rights and freedoms."},"correct_answer":"C","explanation":"Câu cuối cùng của bài đọc kết luận: việc chỉ chăm chú vào kết quả có thể xung đột trực tiếp với các nguyên tắc đạo đức và sự công bằng (''conflict with following moral rules'')."}]}}]}],"description":"Bộ đề TOEFL iBT 2026 Multistage Adaptive (YouTube Practice 4): Module 1 (Great Wall of China, Orientation Reminder, SkyReach Language App, Keystone Species) & Module 2 (Water Resource, Mountain Peak Hotel, EcoSteps Volunteer, Utilitarianism).","created_at_ms":1791231607964}'::jsonb,
  timezone('utc'::text, now())
)
ON CONFLICT (id) DO UPDATE SET
  title = EXCLUDED.title,
  skill = EXCLUDED.skill,
  task_type = EXCLUDED.task_type,
  duration_seconds = EXCLUDED.duration_seconds,
  content = EXCLUDED.content;

INSERT INTO public.tests (id, title, skill, task_type, duration_seconds, content, created_at)
VALUES (
  'reading-practice-06',
  'Reading Practice Test 06 (TOEFL 2026 - Migration & Green Revolution)',
  'reading',
  'multistage',
  1800,
  '{"stages":[{"id":"read6_stage_1","title":"Reading - Module 1 (Stage 1)","duration_seconds":900,"description":"Module 1 gồm 4 phần (20 câu hỏi). Hãy hoàn thành trước khi hết 15 phút.","tasks":[{"id":"read6_m1_t1","title":"Task 1: Complete the Words (Đoạn 1 - Migration)","task_type":"complete_words","content":{"instructions":"Điền các chữ cái còn thiếu vào vị trí dấu gạch dưới `_` trong đoạn văn sau:","paragraph":"Migration is a natural phenomenon observed throughout history in both humans and animals. People mo[ve] in sea[rch] of be[tter] opportunities, saf[ety], or climate cond[itions]. Similarly, ani[mals] migrate seaso[nally] to fi[nd] food or bree[ding] grounds. Wh[ile] migration promotes cultural exchange and genetic diversity, it can also cause social and political challenges. Understanding migration patterns helps societies develop fair policies and encourages cooperation between nations to manage movement responsibly.","blanks":[{"id":"read6_m1_t1_b1","prefix":"mo","missing":"ve","full":"move"},{"id":"read6_m1_t1_b2","prefix":"sea","missing":"rch","full":"search"},{"id":"read6_m1_t1_b3","prefix":"be","missing":"tter","full":"better"},{"id":"read6_m1_t1_b4","prefix":"saf","missing":"ety","full":"safety"},{"id":"read6_m1_t1_b5","prefix":"cond","missing":"itions","full":"conditions"},{"id":"read6_m1_t1_b6","prefix":"ani","missing":"mals","full":"animals"},{"id":"read6_m1_t1_b7","prefix":"seaso","missing":"nally","full":"seasonally"},{"id":"read6_m1_t1_b8","prefix":"fi","missing":"nd","full":"find"},{"id":"read6_m1_t1_b9","prefix":"bree","missing":"ding","full":"breeding"},{"id":"read6_m1_t1_b10","prefix":"Wh","missing":"ile","full":"While"}]}},{"id":"read6_m1_t2","title":"Task 2: Read a Notice (Important: Parking Policy Update)","task_type":"read_daily_life","content":{"document_type":"Notice","passage":"Important: Parking Policy Update\n\nStarting next Monday, all employees must display a new parking permit on their vehicle dashboards. Old permits will no longer be valid. You can pick up your new permit from the Facilities Office before Friday. Vehicles without valid permits may be ticketed or towed.","questions":[{"id":"read6_m1_q11","type":"multiple_choice","prompt":"What is the purpose of this notice?","options":{"A":"To announce the closure of the parking lot","B":"To inform employees of a new parking rule","C":"To advertise available parking spaces","D":"To remind employees to pay parking fees"},"correct_answer":"B","explanation":"Thông báo nhắc nhở và thông tin đến nhân viên quy định mới về thẻ đỗ xe mới (''to inform employees of a new parking rule'')."},{"id":"read6_m1_q12","type":"multiple_choice","prompt":"What will happen to vehicles without new permits?","options":{"A":"They will lose access to the building","B":"They will be allowed to park temporarily","C":"They will be relocated automatically","D":"They will be fined or removed"},"correct_answer":"D","explanation":"Thông báo nêu rõ: ''Vehicles without valid permits may be ticketed or towed'' (bị phạt vé hoặc bị cẩu xe đi)."}]}},{"id":"read6_m1_t3","title":"Task 3: Read a Short Article (Coral Reefs)","task_type":"read_daily_life","content":{"document_type":"Short Article","passage":"Many people associate coral reefs with tropical beauty, but few realize their vital ecological role. Reefs provide food and shelter for about 25% of all marine species, despite covering less than 1% of the ocean floor. Unfortunately, climate change and pollution are causing widespread coral bleaching. Scientists are now experimenting with coral \"gardening,\" where healthy fragments are grown and transplanted to restore damaged reefs.","questions":[{"id":"read6_m1_q13","type":"multiple_choice","prompt":"What is the main purpose of this article?","options":{"A":"To promote tourism in tropical regions","B":"To compare coral reefs and forests","C":"To explain how coral forms naturally","D":"To describe the importance and threats to coral reefs"},"correct_answer":"D","explanation":"Bài viết nêu rõ vai trò sinh thái quan trọng của rạn san hô cùng các hiểm họa (biến đổi khí hậu, ô nhiễm) đang đe dọa chúng."},{"id":"read6_m1_q14","type":"multiple_choice","prompt":"What does \"coral gardening\" involve?","options":{"A":"Cleaning coral with special equipment","B":"Building artificial reefs from plastic","C":"Growing coral in controlled environments and replanting it","D":"Monitoring coral growth from satellites"},"correct_answer":"C","explanation":"Đoạn văn nêu rõ: ''where healthy fragments are grown and transplanted to restore damaged reefs''."},{"id":"read6_m1_q15","type":"multiple_choice","prompt":"What can be inferred about the future of coral reefs?","options":{"A":"They will recover naturally without human intervention.","B":"Restoration efforts may help reefs, but the main threats still need to be addressed.","C":"Coral reefs will disappear completely within a decade.","D":"Tourism is the main cause of coral reef destruction."},"correct_answer":"B","explanation":"Các nỗ lực phục hồi (coral gardening) có ích nhưng hiểm họa cốt lõi (biến đổi khí hậu, ô nhiễm) vẫn cần được giải quyết triệt để."}]}},{"id":"read6_m1_t4","title":"Task 4: Academic Passage (The Complex Legacy of the Green Revolution)","task_type":"academic_passage","content":{"document_type":"Agriculture & History Passage","passage":"The Green Revolution, a period of technological transfer initiatives from the 1940s to the late 1970s, dramatically increased agricultural production worldwide, particularly in the developing world. It centered on the development of high-yielding varieties of cereal grains, expansion of irrigation infrastructure, and the widespread distribution of synthetic fertilizers and pesticides.\n\nPioneers like Norman Borlaug are credited with saving over a billion people from starvation by introducing dwarf wheat varieties that allocated more energy to grain production. However, the revolution''s legacy is deeply nuanced. The intensification of agriculture came with significant environmental costs, including soil degradation, water table depletion, and pollution from agrochemicals.\n\nFurthermore, the technological package was often most accessible to wealthier landowners, exacerbating socioeconomic disparities and consolidating land ownership. The focus on monocultures also reduced agricultural biodiversity, increasing vulnerability to pests and diseases.\n\nConsequently, while the Green Revolution stands as a monumental achievement in confronting Malthusian predictions of famine, it also serves as a cautionary tale about the unintended consequences of technological fixes, highlighting the need for sustainable approaches that balance productivity with ecological health and social equity.","questions":[{"id":"read6_m1_q16","type":"multiple_choice","prompt":"What is the main point of the passage?","options":{"A":"The Green Revolution was an unqualified success that permanently solved world hunger.","B":"The Green Revolution had significant benefits but also serious negative consequences.","C":"Norman Borlaug''s work was ultimately harmful to the environment.","D":"The technological innovations of the Green Revolution were only accessible to wealthy individuals."},"correct_answer":"B","explanation":"Ý chính của bài là Cách mạng Xanh mang lại năng suất lương thực to lớn nhưng đi kèm nhiều hệ lụy tiêu cực về môi trường và xã hội."},{"id":"read6_m1_q17","type":"multiple_choice","prompt":"The word \"nuanced\" in the passage is closest in meaning to","options":{"A":"straightforward.","B":"positive.","C":"subtle and complex.","D":"negligible and forgotten."},"correct_answer":"C","explanation":"''nuanced'' có nghĩa là tinh tế, phức tạp nhiều khía cạnh (''subtle and complex'')."},{"id":"read6_m1_q18","type":"multiple_choice","prompt":"According to the passage, one of the environmental costs of the Green Revolution was","options":{"A":"an increase in agricultural biodiversity.","B":"the consolidation of land ownership among the poor.","C":"the exhaustion of water resources.","D":"a decrease in the use of synthetic chemicals."},"correct_answer":"C","explanation":"Đoạn 2 nêu rõ chi phí môi trường: ''water table depletion'' (suy kiệt tầng nước ngầm / exhaustion of water resources)."},{"id":"read6_m1_q19","type":"multiple_choice","prompt":"The author mentions \"socioeconomic disparities\" in order to","options":{"A":"highlight a social problem that was worsened by the Green Revolution''s implementation.","B":"argue that the Green Revolution successfully reduced poverty.","C":"suggest that environmental costs were more important than social ones.","D":"show that the revolution benefited only the poorest farmers."},"correct_answer":"A","explanation":"Tác giả đề cập đến sự chênh lệch kinh tế xã hội để làm nổi bật vấn đề xã hội bị trầm trọng hóa do gói công nghệ ưu tiên người giàu."},{"id":"read6_m1_q20","type":"multiple_choice","prompt":"Why does the author refer to the Green Revolution as a \"cautionary tale\"?","options":{"A":"It demonstrates that increasing food production is impossible.","B":"It shows that technological solutions can create new problems even as they solve old ones.","C":"It proves that Malthusian predictions were correct.","D":"It suggests that sustainable agriculture is not a worthwhile goal."},"correct_answer":"B","explanation":"''Cautionary tale'' (bài học cảnh tỉnh) vì các giải pháp công nghệ có thể tạo ra hệ lụy mới ngoài ý muốn dù giải quyết được vấn đề cũ."}]}}]},{"id":"read6_stage_2","title":"Reading - Module 2 (Stage 2 - Adaptive)","duration_seconds":900,"description":"Module 2 thích ứng gồm 4 phần (20 câu hỏi). Hãy hoàn thành trước khi hết 15 phút.","tasks":[{"id":"read6_m2_t1","title":"Task 1: Complete the Words (Đoạn 1 - Electric Vehicles)","task_type":"complete_words","content":{"instructions":"Điền các chữ cái còn thiếu vào vị trí dấu gạch dưới `_` trong đoạn văn sau:","paragraph":"Electric vehicles are becoming more popular as technology advances and environmental awareness grows. Unlike trad[itional] cars, th[ey] run o[n] electricity ra[ther] than gasol[ine], reducing green[house] gas emi[ssions]. Although t[he] initial co[st] can be hig[her], maintenance expenses are lower because electric engines have fewer moving parts. Governments around the world offer incentives to encourage their use. As charging infrastructure expands, electric vehicles are expected to play a major role in reducing pollution.","blanks":[{"id":"read6_m2_t1_b1","prefix":"trad","missing":"itional","full":"traditional"},{"id":"read6_m2_t1_b2","prefix":"th","missing":"ey","full":"they"},{"id":"read6_m2_t1_b3","prefix":"o","missing":"n","full":"on"},{"id":"read6_m2_t1_b4","prefix":"ra","missing":"ther","full":"rather"},{"id":"read6_m2_t1_b5","prefix":"gasol","missing":"ine","full":"gasoline"},{"id":"read6_m2_t1_b6","prefix":"green","missing":"house","full":"greenhouse"},{"id":"read6_m2_t1_b7","prefix":"emi","missing":"ssions","full":"emissions"},{"id":"read6_m2_t1_b8","prefix":"t","missing":"he","full":"the"},{"id":"read6_m2_t1_b9","prefix":"co","missing":"st","full":"cost"},{"id":"read6_m2_t1_b10","prefix":"hig","missing":"her","full":"higher"}]}},{"id":"read6_m2_t2","title":"Task 2: Read an Online Post (GreenWays Travel Blog)","task_type":"read_daily_life","content":{"document_type":"Blog Post","passage":"GreenWays Travel Blog\n\nPlanning your next eco-friendly adventure? Choose destinations that prioritize sustainability, even if they require more research to find. Many accommodations now reduce their carbon footprint through renewable energy and by offering meals prepared with ingredients from nearby farms. When exploring natural areas, remain on established routes to avoid disturbing sensitive habitats. Ultimately, mindful travel not only lessens environmental impact but also deepens your connection to the places you visit.","questions":[{"id":"read6_m2_q11","type":"multiple_choice","prompt":"What is the main purpose of the post?","options":{"A":"To encourage readers to adopt sustainable travel practices","B":"To persuade travelers to avoid popular destinations","C":"To promote energy-efficient hotels exclusively","D":"To highlight the dangers of exploring unfamiliar landscapes"},"correct_answer":"A","explanation":"Mục đích chính của bài đăng là khuyến khích du khách thực hiện các thói quen du lịch bền vững và thân thiện môi trường."},{"id":"read6_m2_q12","type":"multiple_choice","prompt":"According to the post, what is one recommended practice for responsible travel?","options":{"A":"Choosing routes freely to discover untouched nature","B":"Avoiding locally sourced food to reduce spending","C":"Staying on official paths when exploring natural areas","D":"Relying on private vehicles for greater convenience"},"correct_answer":"C","explanation":"Bài viết khuyến nghị: ''remain on established routes to avoid disturbing sensitive habitats'' (đi theo tuyến đường định sẵn)."}]}},{"id":"read6_m2_t3","title":"Task 3: Read an Email (Your Interview Schedule)","task_type":"read_daily_life","content":{"document_type":"Email Notice","passage":"From: admissions@lakeviewcollege.edu\nSubject: Your Interview Schedule\n\nDear Applicant,\n\nThank you for your interest in Lakeview College. Your admissions interview has been scheduled for Thursday, June 14, at 10:00 a.m. in Room 212 of the Main Building. Please arrive 15 minutes early and bring a copy of your ID and your application confirmation email.\n\nIf you need to make any changes to the appointment, please respond to this message no later than Tuesday.\n\nBest regards,\nAdmissions Office","questions":[{"id":"read6_m2_q13","type":"multiple_choice","prompt":"What is the main purpose of this email?","options":{"A":"To remind the applicant about documents needed after enrollment","B":"To confirm details of an upcoming interview","C":"To provide instructions for submitting a new application","D":"To inform the applicant that their interview has been cancelled"},"correct_answer":"B","explanation":"Email gửi để xác nhận thời gian, địa điểm cụ thể của buổi phỏng vấn tuyển sinh (''Your admissions interview has been scheduled...'')."},{"id":"read6_m2_q14","type":"multiple_choice","prompt":"What should the applicant do if they cannot attend the interview?","options":{"A":"Fill out a rescheduling form on the college website","B":"Call the main office on Thursday","C":"Reply to the email before Tuesday","D":"Arrive earlier than the scheduled time"},"correct_answer":"C","explanation":"Email dặn dò: ''If you need to make any changes... please respond to this message no later than Tuesday''."},{"id":"read6_m2_q15","type":"multiple_choice","prompt":"Which of the following is explicitly required on the day of the interview?","options":{"A":"A printed copy of the applicant''s academic transcripts","B":"A valid ID and the application confirmation email","C":"A letter of recommendation","D":"Proof of payment for the application fee"},"correct_answer":"B","explanation":"Đoạn văn yêu cầu rõ: ''bring a copy of your ID and your application confirmation email''."}]}},{"id":"read6_m2_t4","title":"Task 4: Academic Passage (Neuroplasticity: Rewiring the Adult Brain)","task_type":"academic_passage","content":{"document_type":"Neuroscience Passage","passage":"For much of the 20th century, a central dogma of neuroscience held that the adult brain was largely static and immutable, incapable of generating new neurons or fundamentally changing its structure after childhood. This doctrine has been completely overturned by the discovery of neuroplasticity — the brain''s lifelong capacity to reorganize itself by forming new neural connections.\n\nThis plasticity manifests in several ways. Synaptic plasticity allows the strength of connections between neurons to change with experience, a process underlying learning and memory. Cortical remapping can occur on a larger scale; for instance, if a limb is amputated, the brain region that processed sensory input from that limb may be recruited for other functions. Even neurogenesis, the birth of new neurons, occurs in certain adult brain regions.\n\nThis dynamic nature is driven by experience and learning; complex activities like playing a musical instrument or learning a language can physically alter brain structure. The implications are profound, offering hope for recovery from stroke and brain injury through rehabilitative training that encourages the brain to rewire itself. It also suggests that cognitive decline in aging is not an inevitable, linear process but can be mitigated through continued mental engagement.","questions":[{"id":"read6_m2_q16","type":"multiple_choice","prompt":"The passage primarily aims to","options":{"A":"describe the outdated belief that the brain is unchangeable.","B":"explain the concept of neuroplasticity and its significant implications.","C":"argue that brain injury recovery is impossible.","D":"detail the specific biochemical process of neurogenesis."},"correct_answer":"B","explanation":"Bài đọc giải thích khái niệm tính dẻo của não bộ (neuroplasticity) và các ý nghĩa sâu sắc của nó trong phục hồi và học tập."},{"id":"read6_m2_q17","type":"multiple_choice","prompt":"The word \"immutable\" in the passage is closest in meaning to","options":{"A":"changeable.","B":"intelligent.","C":"unchangeable.","D":"complex."},"correct_answer":"C","explanation":"''immutable'' nghĩa là bất biến, không thể thay đổi (''unchangeable'')."},{"id":"read6_m2_q18","type":"multiple_choice","prompt":"According to the passage, what is \"cortical remapping\"?","options":{"A":"The process of learning a new fact.","B":"The death of neurons due to aging.","C":"The large-scale reassignment of a brain area to a new function.","D":"The creation of new neurons in the hippocampus."},"correct_answer":"C","explanation":"''Cortical remapping'' là sự tái cấu trúc/phân công lại trên quy mô lớn của một vùng não sang chức năng mới (như ví dụ sau khi bị cắt cụt chi)."},{"id":"read6_m2_q19","type":"multiple_choice","prompt":"The author mentions \"playing a musical instrument\" to provide an example of an activity that","options":{"A":"can lead to physical changes in the brain''s structure.","B":"is only effective for brain development in children.","C":"has no impact on synaptic plasticity.","D":"is the best way to recover from a stroke."},"correct_answer":"A","explanation":"Tác giả nêu ví dụ chơi nhạc cụ hoặc học ngôn ngữ để minh họa hoạt động có thể làm thay đổi trực tiếp cấu trúc vật lý của não bộ."},{"id":"read6_m2_q20","type":"multiple_choice","prompt":"What is a key implication of neuroplasticity mentioned in the passage?","options":{"A":"The brain''s structure is fixed by the age of 18.","B":"Cognitive decline in old age is an inevitable, linear process.","C":"Rehabilitation can help the brain recover lost functions after injury.","D":"Learning is solely a chemical process with no physical correlates."},"correct_answer":"C","explanation":"Ý nghĩa then chốt là huấn luyện phục hồi chức năng có thể giúp não bộ tự tái kết nối dây thần kinh để hồi phục sau chấn thương."}]}}]}],"description":"Bộ đề TOEFL iBT 2026 Multistage Adaptive (YouTube Practice 5): Module 1 (Migration, Parking Policy Update, Coral Reefs, Green Revolution) & Module 2 (Electric Vehicles, GreenWays Travel Blog, Lakeview Admissions, Neuroplasticity).","created_at_ms":1791231607964}'::jsonb,
  timezone('utc'::text, now())
)
ON CONFLICT (id) DO UPDATE SET
  title = EXCLUDED.title,
  skill = EXCLUDED.skill,
  task_type = EXCLUDED.task_type,
  duration_seconds = EXCLUDED.duration_seconds,
  content = EXCLUDED.content;

INSERT INTO public.tests (id, title, skill, task_type, duration_seconds, content, created_at)
VALUES (
  'reading-practice-07',
  'Reading Practice Test 07 (TOEFL 2026 - Flow & Freud''s Superego - HARD M2)',
  'reading',
  'multistage',
  1800,
  '{"stages":[{"id":"read7_stage_1","title":"Reading - Module 1 (Stage 1)","duration_seconds":900,"description":"Module 1 gồm 4 phần (20 câu hỏi). Hãy hoàn thành trước khi hết 15 phút.","tasks":[{"id":"read7_m1_t1","title":"Task 1: Complete the Words (Đoạn 1 - Bioluminescence)","task_type":"complete_words","content":{"instructions":"Điền các chữ cái còn thiếu vào vị trí dấu gạch dưới `_` trong đoạn văn sau:","paragraph":"Bioluminescence is the natural production of light by living organisms, found in species ranging from deep-sea fish to certain fungi. This li[ght] is cre[ated] through chemi[cal] reactions th[at] involve ox[ygen] and a molec[ule] called luciferin. Organ[isms] use biolumine[scence] for vari[ous] purposes, s[uch] as communication, camouflage, and attracting prey. In recent years, scientists have studied these organisms to develop new technologies, including medical imaging techniques. However, many bioluminescent species live in fragile ecosystems threatened by pollution and climate change, making conservation efforts essential.","blanks":[{"id":"read7_m1_t1_b1","prefix":"li","missing":"ght","full":"light"},{"id":"read7_m1_t1_b2","prefix":"cre","missing":"ated","full":"created"},{"id":"read7_m1_t1_b3","prefix":"chemi","missing":"cal","full":"chemical"},{"id":"read7_m1_t1_b4","prefix":"th","missing":"at","full":"that"},{"id":"read7_m1_t1_b5","prefix":"ox","missing":"ygen","full":"oxygen"},{"id":"read7_m1_t1_b6","prefix":"molec","missing":"ule","full":"molecule"},{"id":"read7_m1_t1_b7","prefix":"Organ","missing":"isms","full":"Organisms"},{"id":"read7_m1_t1_b8","prefix":"biolumine","missing":"scence","full":"bioluminescence"},{"id":"read7_m1_t1_b9","prefix":"vari","missing":"ous","full":"various"},{"id":"read7_m1_t1_b10","prefix":"s","missing":"uch","full":"such"}]}},{"id":"read7_m1_t2","title":"Task 2: Read an Email (SmartPrint Maintenance Requirement)","task_type":"read_daily_life","content":{"document_type":"Customer Service Email","passage":"From: techsupport@smartprint.com\nSubject: Scheduled Maintenance Requirement\n\nDear Customer,\n\nAccording to our records, your SmartPrint 2500 printer is approaching its annual maintenance deadline. Routine servicing is essential to maintain optimal performance, reduce the likelihood of technical issues, and ensure consistent print quality.\n\nTo remain compliant with warranty conditions, please arrange maintenance through the SmartPrint app or by contacting our support line at 555-2345. Failure to complete the recommended service within the specified period may affect your warranty coverage.\n\nSincerely,\nSmartPrint Support Team","questions":[{"id":"read7_m1_q11","type":"multiple_choice","prompt":"What is the primary purpose of this email?","options":{"A":"To warn customers that their printer is no longer functional","B":"To encourage customers to upgrade to a newer printer model","C":"To inform customers of a required maintenance procedure","D":"To announce changes to customer support services"},"correct_answer":"C","explanation":"Mục đích chính của email là thông báo cho khách hàng về thủ tục bảo trì định kỳ bắt buộc (''inform customers of a required maintenance procedure'')."},{"id":"read7_m1_q12","type":"multiple_choice","prompt":"What is implied if the customer does not follow the instructions in the email?","options":{"A":"The printer will immediately stop working","B":"Technical support will no longer be available","C":"The customer may lose warranty protection","D":"The company will charge an additional maintenance fee"},"correct_answer":"C","explanation":"Email cảnh báo rõ: ''Failure to complete the recommended service... may affect your warranty coverage'' (có thể mất quyền lợi bảo hành)."}]}},{"id":"read7_m1_t3","title":"Task 3: Read a Short Article (Online Education Platforms)","task_type":"read_daily_life","content":{"document_type":"Short Article","passage":"Online education platforms have significantly reshaped modern learning by offering flexible schedules and a wide variety of courses accessible from almost anywhere. This model allows learners to progress at their own pace and balance education with other responsibilities. However, the absence of fixed class times and direct supervision means that students must take greater responsibility for managing their learning. Research and experience suggest that individuals who establish clear goals and consistent study routines are more likely to succeed than those who rely solely on motivation.","questions":[{"id":"read7_m1_q13","type":"multiple_choice","prompt":"What benefit of online education does the passage emphasize most strongly?","options":{"A":"Constant guidance from instructors","B":"Greater flexibility and accessibility","C":"Reduced academic workload","D":"Having a balanced life"},"correct_answer":"B","explanation":"Lợi ích được nhấn mạnh nhất là tính linh hoạt và khả năng tiếp cận (''flexible schedules and a wide variety of courses accessible from almost anywhere'')."},{"id":"read7_m1_q14","type":"multiple_choice","prompt":"According to the passage, why do some students perform better in online courses than others?","options":{"A":"They are more motivated","B":"They have stronger technical skills","C":"They apply effective self-management strategies","D":"They spend more time watching lectures"},"correct_answer":"C","explanation":"Học viên thành công hơn là những người có chiến lược tự quản lý hiệu quả (''establish clear goals and consistent study routines'')."},{"id":"read7_m1_q15","type":"multiple_choice","prompt":"What can be inferred about students who struggle with online learning environments?","options":{"A":"They lack interest in education altogether","B":"They may depend too heavily on external structure","C":"They prefer learning in isolation","D":"They are unwilling to set academic goals"},"correct_answer":"B","explanation":"Những sinh viên gặp khó khăn thường phụ thuộc quá nhiều vào kỷ luật ngoại cảnh hoặc thời khóa biểu cố định sẵn có."}]}},{"id":"read7_m1_t4","title":"Task 4: Academic Passage (The Psychological Phenomenon of Flow)","task_type":"academic_passage","content":{"document_type":"Psychology Passage","passage":"The concept of \"flow,\" a term coined by psychologist Mihaly Csikszentmihalyi, describes a state of intense, focused concentration on a present activity to the point of becoming fully absorbed and losing a sense of time and self. This optimal experience is characterized by a perfect balance between the perceived challenges of a task and one''s perceived skills; the activity must be sufficiently difficult to avoid boredom but not so difficult as to cause anxiety.\n\nIn this state, action and awareness merge, self-consciousness disappears, and the individual exercises a sense of personal control over the situation. Common examples include artists lost in their work, athletes in \"the zone,\" or programmers deeply engaged in solving a complex problem.\n\nFlow is not merely a pleasurable state; it is linked to enhanced performance, creativity, and long-term personal growth. Achieving flow consistently is considered a cornerstone of a fulfilling life. However, it requires clear goals, immediate feedback, and an environment with few distractions. In an age of constant digital interruption, the ability to cultivate deep work and enter a flow state is becoming both more challenging and more valuable, representing a key differentiator in high-level cognitive and creative achievements.","questions":[{"id":"read7_m1_q16","type":"multiple_choice","prompt":"Which of the following best states the main idea of the passage?","options":{"A":"Flow is a rare state that only a few people can ever achieve","B":"Mihaly Csikszentmihalyi discovered that flow is identical to relaxation","C":"The primary requirement for flow is a task that is extremely easy","D":"Flow is a state of deep absorption that enhances performance and fulfillment"},"correct_answer":"D","explanation":"Ý chính của bài: Flow (dòng chảy tâm trí) là trạng thái tập trung sâu sắc giúp nâng cao hiệu suất và mang lại cảm giác thỏa mãn trong cuộc sống."},{"id":"read7_m1_q17","type":"multiple_choice","prompt":"The word \"optimal\" in the passage is closest in meaning to","options":{"A":"optional","B":"first","C":"best","D":"easiest"},"correct_answer":"C","explanation":"''optimal'' nghĩa là tối ưu, tốt nhất (''best'')."},{"id":"read7_m1_q18","type":"multiple_choice","prompt":"According to the passage, what is necessary for a flow state to occur?","options":{"A":"A perfect match between the challenge of a task and one''s skill level","B":"A task that is far beyond one''s current abilities","C":"A high degree of self-consciousness and awareness of time","D":"A distracting environment to provide stimulation"},"correct_answer":"A","explanation":"Bài đọc nêu rõ điều kiện cốt lõi: ''a perfect balance between the perceived challenges of a task and one''s perceived skills''."},{"id":"read7_m1_q19","type":"multiple_choice","prompt":"The author mentions \"an age of constant digital interruption\" primarily to","options":{"A":"suggest that flow states are now impossible to achieve","B":"highlight a modern obstacle to achieving deep concentration","C":"argue that digital tools are the best way to achieve flow","D":"suggest that people in the past had easier lives"},"correct_answer":"B","explanation":"Cụm từ này nhằm làm nổi bật trở ngại lớn của thời hiện đại (sự gián đoạn từ thiết bị số) đối với khả năng tập trung sâu."},{"id":"read7_m1_q20","type":"multiple_choice","prompt":"What is the relationship between the second and third paragraphs?","options":{"A":"The third paragraph shifts the discussion from descriptive illustration to broader implications and constraints","B":"The third paragraph challenges the validity of the situations described in the second paragraph","C":"The third paragraph narrows the focus of the passage to a single professional domain mentioned earlier","D":"The third paragraph provides a chronological account explaining how the examples in the second paragraph developed"},"correct_answer":"A","explanation":"Đoạn 2 minh họa ví dụ thực tế (nghệ sĩ, vận động viên), còn đoạn 3 mở rộng sang các ý nghĩa rộng hơn về năng suất và các điều kiện ràng buộc để đạt được flow."}]}}]},{"id":"read7_stage_2","title":"Reading - Module 2 (Stage 2 - HARD C1 Adaptive)","duration_seconds":900,"description":"Module 2 khó (C1) gồm 4 phần (20 câu hỏi). Hãy hoàn thành trước khi hết 15 phút.","tasks":[{"id":"read7_m2_t1","title":"Task 1: Complete the Words (Đoạn 1 - Ancient Papermaking)","task_type":"complete_words","content":{"instructions":"Điền các chữ cái còn thiếu vào vị trí dấu gạch dưới `_` trong đoạn văn sau:","paragraph":"Papermaking originated in ancient China around the second century CE and revolutionized the spread of knowledge. Tradition[ally], fibers f[rom] plants s[uch] as mulberry bark we[re] soaked, mash[ed], and pressed in[to] thin shee[ts]. As the techn[ique] spread ac[ross] continents, it contrib[uted] to the growth of literacy, education, and record-keeping. The Industrial Revolution introduced mechanized production, greatly increasing output and reducing costs. Today, digital media has reduced paper consumption in some areas, yet papermaking remains important for packaging, publishing, and cultural preservation.","blanks":[{"id":"read7_m2_t1_b1","prefix":"Tradition","missing":"ally","full":"Traditionally"},{"id":"read7_m2_t1_b2","prefix":"f","missing":"rom","full":"from"},{"id":"read7_m2_t1_b3","prefix":"s","missing":"uch","full":"such"},{"id":"read7_m2_t1_b4","prefix":"we","missing":"re","full":"were"},{"id":"read7_m2_t1_b5","prefix":"mash","missing":"ed","full":"mashed"},{"id":"read7_m2_t1_b6","prefix":"in","missing":"to","full":"into"},{"id":"read7_m2_t1_b7","prefix":"shee","missing":"ts","full":"sheets"},{"id":"read7_m2_t1_b8","prefix":"techn","missing":"ique","full":"technique"},{"id":"read7_m2_t1_b9","prefix":"ac","missing":"ross","full":"across"},{"id":"read7_m2_t1_b10","prefix":"contrib","missing":"uted","full":"contributed"}]}},{"id":"read7_m2_t2","title":"Task 2: Read a Short Article (NASA''s Perseverance Rover)","task_type":"read_daily_life","content":{"document_type":"Short Science Article","passage":"NASA''s Perseverance rover has recently cached geological samples that scientists believe may preserve chemical signatures of ancient microbial activity. These materials are intended to be transported to Earth as part of a future sample-return mission, allowing researchers to apply analytical techniques that are currently impossible to conduct on Mars. Beyond the question of past life, the mission is expected to deepen scientific understanding of Mars''s early climate and its potential parallels with primordial Earth.","questions":[{"id":"read7_m2_q11","type":"multiple_choice","prompt":"What is the primary aim of the article?","options":{"A":"To confirm that microbial life once existed on Mars","B":"To explain the technological limitations of conducting research on Mars","C":"To report on a mission milestone and its broader scientific significance","D":"To argue that Mars and Earth followed identical evolutionary paths"},"correct_answer":"C","explanation":"Mục tiêu chính của bài viết là tường thuật cột mốc lấy mẫu của robot tự hành Perseverance và ý nghĩa khoa học sâu rộng của nó."},{"id":"read7_m2_q12","type":"multiple_choice","prompt":"Why are the samples planned to be returned to Earth?","options":{"A":"Because the rover lacks the capability to preserve them on Mars","B":"Because Earth-based laboratories allow for more advanced analysis","C":"Because NASA intends to display them for public education","D":"Because Mars''s environment may contaminate the samples over time"},"correct_answer":"B","explanation":"Đoạn văn nêu rõ mang mẫu về Trái Đất giúp áp dụng các kỹ thuật phân tích hiện đại mà hiện không thể tiến hành trên Sao Hỏa (''analytical techniques that are currently impossible to conduct on Mars'')."}]}},{"id":"read7_m2_t3","title":"Task 3: Read a Social Media Post (Community Clean-Up Day)","task_type":"read_daily_life","content":{"document_type":"Social Media Announcement","passage":"A huge thank you to everyone who took part in yesterday''s Community Clean-Up Day! With collective effort and remarkable energy, volunteers removed more than 500 kilograms of waste from our parks and shoreline. Initiatives like this show what sustained community involvement can achieve. We''re already preparing for our next event on June 10 — more information to follow soon.","questions":[{"id":"read7_m2_q13","type":"multiple_choice","prompt":"What is the main communicative purpose of this post?","options":{"A":"To evaluate the long-term impact of environmental activism","B":"To express appreciation while encouraging continued participation","C":"To criticize the authorities responsible for waste management","D":"To announce a similar future event"},"correct_answer":"B","explanation":"Mục đích chính là bày tỏ lòng biết ơn tới tình nguyện viên và khuyến khích mọi người tiếp tục tham gia trong tương lai."},{"id":"read7_m2_q14","type":"multiple_choice","prompt":"What can reasonably be inferred about the group behind the post?","options":{"A":"It operates primarily as a governmental environmental agency","B":"It focuses exclusively on short-term volunteer actions","C":"It engages in recurring community-based environmental initiatives","D":"It was established specifically for this single clean-up effort"},"correct_answer":"C","explanation":"Nhóm tổ chức này thực hiện các hoạt động môi trường định kỳ tại cộng đồng (''We''re already preparing for our next event on June 10'')."},{"id":"read7_m2_q15","type":"multiple_choice","prompt":"What does the post suggest about the upcoming event on June 10?","options":{"A":"Its objectives differ significantly from the previous clean-up","B":"Its organization is already complete and finalized","C":"Some logistical details are still being arranged","D":"Participation will be limited to returning volunteers"},"correct_answer":"C","explanation":"''more information to follow soon'' hàm ý rằng một số chi tiết hậu cần vẫn đang được chuẩn bị hoàn tất."}]}},{"id":"read7_m2_t4","title":"Task 4: Academic Passage (The Superego and the Psychic Apparatus)","task_type":"academic_passage","content":{"document_type":"Psychoanalysis Passage","passage":"Sigmund Freud''s structural model of the psyche posits a tripartite division into the id, ego, and superego. While the id represents primal drives and the ego mediates with reality, the superego functions as the internalized moral arbiter, embodying the values and ideals of society as transmitted primarily by parental figures. Its development is a critical process in childhood, emerging from the resolution of the Oedipal complex.\n\nThe superego has two distinct subsystems: the conscience, which punishes transgressions with feelings of guilt and shame, and the ego-ideal, which rewards adherence to moral standards with feelings of pride. [A] A poorly integrated superego can lead to various psychopathologies. [B] An excessively harsh superego may result in crippling anxiety, obsessive self-reproach, and an inability to experience pleasure, as the individual is perpetually plagued by a sense of their own unworthiness. [C] Conversely, a weak or underdeveloped superego is associated with antisocial behavior, a lack of remorse, and an inability to conform to social norms. [D]\n\nFreud thus conceptualized the superego not as a benign guide but as a potentially tyrannical force, whose demands are often as irrational and uncompromising as the id''s drives. Its formation represents the price of civilization — the installation of a permanent internal authority that both enables social cohesion and generates profound intrapsychic conflict.","questions":[{"id":"read7_m2_q16","type":"multiple_choice","prompt":"The word \"arbiter\" in the passage is closest in meaning to","options":{"A":"follower","B":"student","C":"judge","D":"opponent"},"correct_answer":"C","explanation":"''arbiter'' là người phân xử, thẩm phán/người phán quyết đạo đức (''judge'')."},{"id":"read7_m2_q17","type":"multiple_choice","prompt":"Where would the following sentence best fit: \"Both extremes reflect imbalances in the regulation of moral standards and self-evaluation.\"?","options":{"A":"Location A","B":"Location B","C":"Location C","D":"Location D"},"correct_answer":"D","explanation":"Câu này kết luận cho cả 2 thái cực cực đoan được nêu trước đó (quá khắt khe ở [B]-[C] và quá yếu ớt ở [C]-[D]), do đó vị trí phù hợp nhất là [D]."},{"id":"read7_m2_q18","type":"multiple_choice","prompt":"Which of the following sentences best expresses the essential information in the highlighted sentence: \"Freud thus conceptualized the superego not as a benign guide but as a potentially tyrannical force, whose demands are often as irrational and uncompromising as the id''s drives.\"?","options":{"A":"Freud viewed the superego as a helpful moral guide that regulates the irrational impulses of the id","B":"Freud argued that the superego can function as an oppressive internal authority with rigid and irrational demands, similar to those of the id","C":"Freud believed that the superego is less rational than the id and therefore incapable of guiding moral behavior","D":"Freud suggested that the superego becomes tyrannical only when it fails to control the id''s instinctual drives"},"correct_answer":"B","explanation":"Lựa chọn B truyền tải chính xác và đầy đủ ý cốt lõi: siêu tôi có thể đóng vai trò là một quyền lực nội tâm áp bức độc đoán với các đòi hỏi cứng nhắc và phi lý không kém gì bản năng (id)."},{"id":"read7_m2_q19","type":"multiple_choice","prompt":"The author describes the superego as a \"tyrannical force\" in order to emphasize its","options":{"A":"benevolent and guiding nature","B":"weakness compared to the ego","C":"role in promoting antisocial behavior","D":"potential for being irrational and oppressive"},"correct_answer":"D","explanation":"Cụm từ ''tyrannical force'' (lực lượng bạo quyền/chuyên chế) dùng để nhấn mạnh tính chất phi lý và áp bức nặng nề của siêu tôi đối với tâm trí."},{"id":"read7_m2_q20","type":"multiple_choice","prompt":"What can be inferred about the formation of the superego from the passage?","options":{"A":"It is a process that is entirely conscious and voluntary","B":"It is necessary for social living but can also be a source of internal conflict","C":"It completely eliminates the influence of the id","D":"It is fully formed at birth and does not develop over time"},"correct_answer":"B","explanation":"Đoạn cuối khẳng định: sự hình thành siêu tôi là cái giá của nền văn minh, vừa giúp gắn kết xã hội nhưng đồng thời cũng tạo ra xung đột nội tâm sâu sắc (''both enables social cohesion and generates profound intrapsychic conflict'')."}]}}]}],"description":"Bộ đề TOEFL iBT 2026 Multistage Adaptive (YouTube Practice 6 - HARD Module 2 C1): Module 1 (Bioluminescence, SmartPrint Maintenance, Online Education, State of Flow) & Module 2 (Papermaking, NASA Perseverance, Community Clean-Up, Freud''s Superego).","created_at_ms":1791231607964}'::jsonb,
  timezone('utc'::text, now())
)
ON CONFLICT (id) DO UPDATE SET
  title = EXCLUDED.title,
  skill = EXCLUDED.skill,
  task_type = EXCLUDED.task_type,
