INSERT INTO public.tests (id, title, skill, task_type, duration_seconds, content, created_at)
VALUES (
  'reading-practice-08',
  'Reading Practice Test 08 (TOEFL 2026 - Urban Heat & Neolithic Agriculture - HARD M2)',
  'reading',
  'multistage',
  1800,
  '{"stages":[{"id":"read8_stage_1","title":"Reading - Module 1 (Stage 1)","duration_seconds":900,"description":"Module 1 gồm 4 phần (20 câu hỏi). Hãy hoàn thành trước khi hết 15 phút.","tasks":[{"id":"read8_m1_t1","title":"Task 1: Complete the Words (Đoạn 1 - Cultural Traditions)","task_type":"complete_words","content":{"instructions":"Điền các chữ cái còn thiếu vào vị trí dấu gạch dưới `_` trong đoạn văn sau:","paragraph":"Cultural traditions help maintain social cohesion and collective identity. They a[re] transmitted thr[ough] shared practi[ces], language, and symb[ols] ac[ross] generations. Wh[ile] traditions prov[ide] continuity, th[ey] are n[ot] static and of[ten] evolve in response to social change. Globalization and modernization can weaken certain traditions, particularly among younger generations. However, cultural adaptation allows societies to preserve core values while remaining flexible. Studying cultural traditions helps explain how communities balance change and stability in a rapidly transforming world.","blanks":[{"id":"read8_m1_t1_b1","prefix":"a","missing":"re","full":"are"},{"id":"read8_m1_t1_b2","prefix":"thr","missing":"ough","full":"through"},{"id":"read8_m1_t1_b3","prefix":"practi","missing":"ces","full":"practices"},{"id":"read8_m1_t1_b4","prefix":"symb","missing":"ols","full":"symbols"},{"id":"read8_m1_t1_b5","prefix":"ac","missing":"ross","full":"across"},{"id":"read8_m1_t1_b6","prefix":"Wh","missing":"ile","full":"While"},{"id":"read8_m1_t1_b7","prefix":"prov","missing":"ide","full":"provide"},{"id":"read8_m1_t1_b8","prefix":"th","missing":"ey","full":"they"},{"id":"read8_m1_t1_b9","prefix":"n","missing":"ot","full":"not"},{"id":"read8_m1_t1_b10","prefix":"of","missing":"ten","full":"often"}]}},{"id":"read8_m1_t2","title":"Task 2: Read a Social Media Post (New Campus Café)","task_type":"read_daily_life","content":{"document_type":"Social Media Review","passage":"I visited the new café near campus this afternoon and was pleasantly surprised by the overall experience. The coffee had a rich flavor and clearly tasted freshly prepared. In addition, the staff went out of their way to make customers feel welcome, which created a relaxed atmosphere. However, because the café is relatively small, it tends to become overcrowded during peak hours. Despite this inconvenience, I would still recommend it to others.","questions":[{"id":"read8_m1_q11","type":"multiple_choice","prompt":"What problem does the writer mention?","options":{"A":"The drinks are overpriced","B":"The service is slow","C":"The café becomes too crowded","D":"The location is inconvenient"},"correct_answer":"C","explanation":"Vấn đề duy nhất người viết nhắc đến là quán khá nhỏ nên thường quá đông đúc vào giờ cao điểm (''tends to become overcrowded during peak hours'')."},{"id":"read8_m1_q12","type":"multiple_choice","prompt":"What can be inferred about the writer''s opinion?","options":{"A":"The disadvantages outweigh the advantages","B":"The writer will probably return","C":"The café needs new management","D":"The coffee quality is inconsistent"},"correct_answer":"B","explanation":"Người viết khen trải nghiệm nhìn chung và khẳng định vẫn sẽ giới thiệu quán cho người khác (''I would still recommend it to others''), ngụ ý rằng họ có khả năng sẽ quay lại."}]}},{"id":"read8_m1_t3","title":"Task 3: Read an Email from a Professor (Class Schedule Change)","task_type":"read_daily_life","content":{"document_type":"Email Announcement","passage":"Dear students,\n\nI am writing to inform you that tomorrow''s class will start 15 minutes later than usual due to an important meeting that was scheduled unexpectedly. Although I do not anticipate a significant delay, the meeting may run slightly over time. Please adjust your plans accordingly and arrive at the new starting time. We will still cover all the planned material this week, so there is no need to worry about missing essential content.\n\nBest regards,\nProfessor Lewis","questions":[{"id":"read8_m1_q13","type":"multiple_choice","prompt":"Why has the schedule changed?","options":{"A":"The classroom is unavailable","B":"The professor has another commitment","C":"Students requested a later time","D":"Technical equipment needs repair"},"correct_answer":"B","explanation":"Lịch học dời lại vì giáo sư có một cuộc họp đột xuất (''due to an important meeting that was scheduled unexpectedly'')."},{"id":"read8_m1_q14","type":"multiple_choice","prompt":"What does the professor suggest about the meeting?","options":{"A":"It will definitely end on time","B":"It might take longer than expected","C":"It has been canceled","D":"It will shorten the class"},"correct_answer":"B","explanation":"Giáo sư lưu ý rằng cuộc họp có thể kéo dài hơn một chút (''the meeting may run slightly over time'')."},{"id":"read8_m1_q15","type":"multiple_choice","prompt":"What are students expected to do?","options":{"A":"Arrive according to the revised schedule","B":"Come earlier than usual","C":"Skip the class if they are busy","D":"Prepare additional assignments"},"correct_answer":"A","explanation":"Giáo sư đề nghị sinh viên điều chỉnh kế hoạch và đến lớp theo giờ mới muộn hơn 15 phút (''arrive at the new starting time'')."}]}},{"id":"read8_m1_t4","title":"Task 4: Academic Passage (Urban Heat Islands)","task_type":"academic_passage","content":{"document_type":"Environmental Science Passage","passage":"Cities tend to be significantly warmer than surrounding rural areas, a phenomenon known as the \"urban heat island\" effect. This temperature difference arises primarily from human-built surfaces such as asphalt and concrete, which absorb and retain heat more efficiently than vegetation-covered land. During the day, these materials store solar radiation and gradually release it at night, preventing cities from cooling down. In addition, reduced tree cover limits natural cooling through shade and evapotranspiration, further intensifying heat accumulation.\n\nBeyond altering temperature patterns, urban heat islands substantially increase energy consumption, as residents rely more heavily on air conditioning systems to maintain comfortable indoor environments. Higher temperatures can also worsen air pollution because heat accelerates chemical reactions that produce ground-level ozone. Consequently, public health risks rise, particularly for elderly individuals and those with respiratory conditions during prolonged heat waves.\n\nTo mitigate these effects, urban planners have introduced strategies such as green roofs, reflective building materials, expanded tree canopies, and redesigned public spaces. These interventions not only lower surface and air temperatures but also improve air quality, reduce energy demand, and enhance overall urban livability.","questions":[{"id":"read8_m1_q16","type":"multiple_choice","prompt":"All of the following are mentioned as consequences of urban heat islands EXCEPT","options":{"A":"Higher electricity use","B":"Increased air pollution","C":"Greater risk during heat waves","D":"Expanded public transportation"},"correct_answer":"D","explanation":"Bài đọc liệt kê tăng tiêu thụ điện, ô nhiễm ozone, nguy cơ sức khỏe trong đợt nắng nóng, nhưng không đề cập việc mở rộng giao thông công cộng."},{"id":"read8_m1_q17","type":"multiple_choice","prompt":"It can be inferred that green roofs are effective because they","options":{"A":"increase commercial profits","B":"replace heat-retaining surfaces with vegetation","C":"eliminate the need for electricity","D":"reduce urban population density"},"correct_answer":"B","explanation":"Mái nhà xanh hiệu quả vì thay thế bê tông/nhựa đường giữ nhiệt bằng lớp thực vật có khả năng làm mát tự nhiên qua bóng râm và thoát hơi nước."},{"id":"read8_m1_q18","type":"multiple_choice","prompt":"What is the relationship between paragraphs 1 and 2?","options":{"A":"Paragraph 2 challenges the explanation in paragraph 1","B":"Paragraph 2 describes the historical origins of the phenomenon","C":"Paragraph 2 outlines the consequences of the process explained in paragraph 1","D":"Paragraph 2 presents an unrelated environmental issue"},"correct_answer":"C","explanation":"Đoạn 1 giải thích nguyên nhân và cơ chế tạo ra đảo nhiệt đô thị, đoạn 2 phác thảo các hệ quả tiêu cực của hiện tượng đó đối với năng lượng, ô nhiễm và sức khỏe."},{"id":"read8_m1_q19","type":"multiple_choice","prompt":"In the passage, the word \"mitigate\" is closest in meaning to","options":{"A":"measure","B":"worsen","C":"reduce","D":"predict"},"correct_answer":"C","explanation":"''mitigate'' có nghĩa là giảm nhẹ, giảm bớt tác động (''reduce'')."},{"id":"read8_m1_q20","type":"multiple_choice","prompt":"Which sentence best expresses the essential information in the following sentence: \"Beyond altering temperature patterns, urban heat islands substantially increase energy consumption, as residents rely more heavily on air conditioning systems to maintain comfortable indoor environments.\"?","options":{"A":"Urban heat islands change temperature patterns, which is uncomfortable.","B":"Because cities are warmer, people use more air conditioning, increasing energy use.","C":"Excessive air conditioning use results in creation of urban heat islands.","D":"Energy consumption reduces temperature differences, which has a positive influence on cities."},"correct_answer":"B","explanation":"Lựa chọn B diễn đạt ngắn gọn và chính xác mối quan hệ nhân quả cốt lõi: thành phố nóng hơn khiến người dân dùng nhiều máy lạnh hơn, làm tăng tiêu thụ năng lượng."}]}}]},{"id":"read8_stage_2","title":"Reading - Module 2 (Stage 2 - HARD C1 Adaptive)","duration_seconds":900,"description":"Module 2 khó (C1) gồm 4 phần (20 câu hỏi). Hãy hoàn thành trước khi hết 15 phút.","tasks":[{"id":"read8_m2_t1","title":"Task 1: Complete the Words (Đoạn 1 - Sleep Quality)","task_type":"complete_words","content":{"instructions":"Điền các chữ cái còn thiếu vào vị trí dấu gạch dưới `_` trong đoạn văn sau:","paragraph":"Sleep quality is essential for physical health, emotional regulation, and cognitive functioning. During sl[eep], the bo[dy] restores ene[rgy] and the br[ain] processes infor[mation] learned du[ring] the d[ay]. Insufficient sleep is assoc[iated] with redu[ced] concentration, weak[ened] immune response, and increased risk of chronic illness. Modern lifestyles, including screen use and irregular schedules, often disrupt healthy sleep patterns. As awareness of sleep science grows, individuals and institutions are emphasizing better sleep habits. Improving sleep quality supports long-term health and productivity.","blanks":[{"id":"read8_m2_t1_b1","prefix":"sl","missing":"eep","full":"sleep"},{"id":"read8_m2_t1_b2","prefix":"bo","missing":"dy","full":"body"},{"id":"read8_m2_t1_b3","prefix":"ene","missing":"rgy","full":"energy"},{"id":"read8_m2_t1_b4","prefix":"br","missing":"ain","full":"brain"},{"id":"read8_m2_t1_b5","prefix":"infor","missing":"mation","full":"information"},{"id":"read8_m2_t1_b6","prefix":"du","missing":"ring","full":"during"},{"id":"read8_m2_t1_b7","prefix":"d","missing":"ay","full":"day"},{"id":"read8_m2_t1_b8","prefix":"assoc","missing":"iated","full":"associated"},{"id":"read8_m2_t1_b9","prefix":"redu","missing":"ced","full":"reduced"},{"id":"read8_m2_t1_b10","prefix":"weak","missing":"ened","full":"weakened"}]}},{"id":"read8_m2_t2","title":"Task 2: Read an Online Review (Hotel Business Stay)","task_type":"read_daily_life","content":{"document_type":"Online Hotel Review","passage":"I stayed at this hotel for one night while traveling on business. The room was spotless, and the staff was courteous and efficient, which certainly got the trip off to a good start. That said, the Wi-Fi was painfully slow, and when you are up against the clock preparing for an important meeting, that can be a deal-breaker. Although the stay was manageable in the short term, I would think twice before booking again if reliable internet access were essential.","questions":[{"id":"read8_m2_q11","type":"multiple_choice","prompt":"What does the phrase \"up against the clock\" suggest?","options":{"A":"The reviewer had plenty of spare time","B":"The reviewer was working under time pressure","C":"The meeting was canceled","D":"The reviewer arrived too early"},"correct_answer":"B","explanation":"''up against the clock'' là thành ngữ chỉ tình trạng bị gấp rút, chịu áp lực thời gian lớn (''working under time pressure'')."},{"id":"read8_m2_q12","type":"multiple_choice","prompt":"What overall evaluation does the reviewer imply?","options":{"A":"The hotel exceeded expectations","B":"The reviewer would strongly recommend it for long stays","C":"The stay was entirely unsatisfactory","D":"The experience was acceptable but limited"},"correct_answer":"D","explanation":"Đánh giá chung: khách sạn tạm ổn cho chuyến đi ngắn (sạch sẽ, nhân viên lịch sự) nhưng bị hạn chế nghiêm trọng bởi Wi-Fi yếu (''acceptable but limited'')."}]}},{"id":"read8_m2_t3","title":"Task 3: Read an Announcement (Fitness Center Schedule)","task_type":"read_daily_life","content":{"document_type":"Facility Notice","passage":"Beginning this month, the fitness center will close at 8 p.m. on Saturdays rather than 10 p.m. After reviewing attendance data, the administration concluded that keeping the facility open later was simply not worth the candle, as usage dropped off significantly in the late evening. By adjusting the schedule, the center aims to cut costs without compromising overall access. Weekday hours remain unchanged, and Sunday operations will continue as usual. Please plan your workouts accordingly to avoid being caught off guard.","questions":[{"id":"read8_m2_q13","type":"multiple_choice","prompt":"What modification has been introduced?","options":{"A":"Saturday opening hours have been extended","B":"Saturday closing time has been brought forward","C":"Weekday hours have been reduced","D":"The center will temporarily suspend operations"},"correct_answer":"B","explanation":"Giờ đóng cửa thứ Bảy được đẩy sớm lên 8 giờ tối thay vì 10 giờ tối (''Saturday closing time has been brought forward'')."},{"id":"read8_m2_q14","type":"multiple_choice","prompt":"What rationale is provided for the decision?","options":{"A":"Members demanded shorter hours","B":"Staffing shortages made operation impossible","C":"Major renovations are about to begin","D":"Late-evening attendance was too low to justify costs"},"correct_answer":"D","explanation":"Lý do: lượng người tập cuối buổi tối thứ Bảy sụt giảm mạnh, không bõ chi phí vận hành (''usage dropped off significantly... not worth the candle'')."},{"id":"read8_m2_q15","type":"multiple_choice","prompt":"What tone does the announcement adopt?","options":{"A":"Apologetic and defensive","B":"Informal and humorous","C":"Practical and matter-of-fact","D":"Urgent and alarming"},"correct_answer":"C","explanation":"Giọng văn thông báo mang tính thực tế, dựa trên số liệu và thẳng thắn (''practical and matter-of-fact'')."}]}},{"id":"read8_m2_t4","title":"Task 4: Academic Passage (The Origins of Agriculture)","task_type":"academic_passage","content":{"document_type":"Anthropology & Archaeology Passage","passage":"[A] For the vast majority of human history, communities sustained themselves through hunting wild animals and gathering edible plants. [B] However, approximately 10,000 years ago, certain populations began deliberately cultivating crops and domesticating animals, initiating a profound transformation commonly referred to as the Neolithic Revolution. [C] This shift did not occur uniformly across regions, yet wherever it emerged, it fundamentally altered patterns of social organization and human interaction with the environment. [D]\n\nThe development of agriculture generated more predictable food supplies, which in turn facilitated sustained population growth and the establishment of permanent settlements. As agricultural techniques improved, communities were able to produce surpluses that exceeded immediate subsistence needs. These surpluses enabled occupational specialization, allowing some individuals to devote themselves to crafts, trade, religious leadership, or governance. Over time, such differentiation contributed to increasingly hierarchical and administratively complex societies.\n\nNevertheless, agriculture also introduced significant challenges. Dependence on a limited number of crops heightened vulnerability to drought, pests, and disease, while densely populated settlements accelerated the transmission of infectious illnesses, reshaping demographic patterns in lasting ways.","questions":[{"id":"read8_m2_q16","type":"multiple_choice","prompt":"Which of the following best captures the central argument of the passage?","options":{"A":"The adoption of agriculture marked a turning point that restructured human societies","B":"Early agricultural societies were more egalitarian than hunter-gatherer groups","C":"Infectious diseases were the primary driver of social hierarchy","D":"Nomadic lifestyles prevented technological innovation"},"correct_answer":"A","explanation":"Luận điểm trung tâm: Việc chuyển sang canh tác nông nghiệp đánh dấu một bước ngoặt tái cấu trúc toàn diện xã hội loài người."},{"id":"read8_m2_q17","type":"multiple_choice","prompt":"The word \"subsistence\" in the second paragraph is closest in meaning to","options":{"A":"migration","B":"basic survival","C":"trade expansion","D":"political influence"},"correct_answer":"B","explanation":"''subsistence'' nghĩa là mức sinh kế / duy trì sự sống cơ bản (''basic survival'')."},{"id":"read8_m2_q18","type":"multiple_choice","prompt":"What is the author''s primary purpose in the third paragraph?","options":{"A":"To emphasize that agricultural societies were technologically advanced","B":"To qualify the earlier discussion by introducing the drawbacks of agriculture","C":"To argue that hunting and gathering was more sustainable","D":"To describe regional differences in farming practices"},"correct_answer":"B","explanation":"Mục đích đoạn 3: Bổ sung góc nhìn đa chiều bằng cách phân tích những khó khăn và mặt trái mà nông nghiệp mang lại (dịch bệnh, hạn hán, mất mùa)."},{"id":"read8_m2_q19","type":"multiple_choice","prompt":"What is the relationship between paragraphs 1 and 2?","options":{"A":"Paragraph 2 challenges the historical interpretation introduced in paragraph 1","B":"Paragraph 2 shifts the focus to a different historical period","C":"Paragraph 2 provides specific consequences of the transformation outlined in paragraph 1","D":"Paragraph 2 presents a contrasting example from a separate civilization"},"correct_answer":"C","explanation":"Đoạn 1 giới thiệu cuộc cách mạng đồ đá mới (bắt đầu trồng trọt, thuần hóa động vật), đoạn 2 nêu chi tiết các hệ quả cụ thể (dư thừa lương thực, phân công lao động, phân tầng xã hội)."},{"id":"read8_m2_q20","type":"multiple_choice","prompt":"Where would the following sentence best fit: \"This nomadic lifestyle required mobility and limited the accumulation of material possessions.\"?","options":{"A":"Location A","B":"Location B","C":"Location C","D":"Location D"},"correct_answer":"B","explanation":"Câu này bổ sung chi tiết trực tiếp cho lối sống săn bắt hái lượm du mục được nhắc đến ở câu đầu tiên, ngay trước từ chuyển ý ''However'' tại vị trí [B]."}]}}]}],"description":"Bộ đề TOEFL iBT 2026 Multistage Adaptive (YouTube Practice 7 - HARD Module 2 C1): Module 1 (Cultural Traditions, Campus Café, Professor Lewis Email, Urban Heat Islands) & Module 2 (Sleep Quality, Business Hotel Review, Fitness Center Announcement, Neolithic Agriculture).","created_at_ms":1791231607964}'::jsonb,
  timezone('utc'::text, now())
)
ON CONFLICT (id) DO UPDATE SET
  title = EXCLUDED.title,
  skill = EXCLUDED.skill,
  task_type = EXCLUDED.task_type,
  duration_seconds = EXCLUDED.duration_seconds,
  content = EXCLUDED.content;

INSERT INTO public.tests (id, title, skill, task_type, duration_seconds, content, created_at)
VALUES (
  'reading-practice-09',
  'Reading Practice Test 09 (TOEFL 2026 - Attention Economy & AI - HARD M2)',
  'reading',
  'multistage',
  1800,
  '{"stages":[{"id":"read9_stage_1","title":"Reading - Module 1 (Stage 1)","duration_seconds":900,"description":"Module 1 gồm 4 phần (20 câu hỏi). Hãy hoàn thành trước khi hết 15 phút.","tasks":[{"id":"read9_m1_t1","title":"Task 1: Complete the Words (Đoạn 1 - Critical Reading)","task_type":"complete_words","content":{"instructions":"Điền các chữ cái còn thiếu vào vị trí dấu gạch dưới `_` trong đoạn văn sau:","paragraph":"Critical reading is the ability to understand not only what a text says but also how it communicates meaning through structure, tone, and evidence. Skilled rea[ders] examine the auth[or]''s purpose, assump[tions], and cho[ice] of examp[les]. They comp[are] arguments, iden[tify] bias, and evalu[ate] the streng[th] of suppor[ting] details. In academic contexts, this skill leads to deeper comprehension and more accurate interpretation of complex materials. Critical reading also encourages independence of thought. Instead of accepting information passively, readers learn to question ideas and form reasoned conclusions based on careful analysis.","blanks":[{"id":"read9_m1_t1_b1","prefix":"rea","missing":"ders","full":"readers"},{"id":"read9_m1_t1_b2","prefix":"auth","missing":"or","full":"author"},{"id":"read9_m1_t1_b3","prefix":"assump","missing":"tions","full":"assumptions"},{"id":"read9_m1_t1_b4","prefix":"cho","missing":"ice","full":"choice"},{"id":"read9_m1_t1_b5","prefix":"examp","missing":"les","full":"examples"},{"id":"read9_m1_t1_b6","prefix":"comp","missing":"are","full":"compare"},{"id":"read9_m1_t1_b7","prefix":"iden","missing":"tify","full":"identify"},{"id":"read9_m1_t1_b8","prefix":"evalu","missing":"ate","full":"evaluate"},{"id":"read9_m1_t1_b9","prefix":"streng","missing":"th","full":"strength"},{"id":"read9_m1_t1_b10","prefix":"suppor","missing":"ting","full":"supporting"}]}},{"id":"read9_m1_t2","title":"Task 2: Read a Short Blog Entry (Biking to Campus)","task_type":"read_daily_life","content":{"document_type":"Personal Blog","passage":"Today I finally tried biking to campus instead of taking the bus, and it went much better than I expected. The whole ride took only 12 minutes, which is actually faster than my usual bus route. The only difficult part was the long hill near my dorm — I didn''t realize how steep it was, and my legs were burning by the time I reached the top. Still, I think I''ll bike more often now.","questions":[{"id":"read9_m1_q11","type":"multiple_choice","prompt":"What is one benefit mentioned?","options":{"A":"It''s cheaper than the bus","B":"Biking is faster than the bus","C":"Going up the hill provides exercise","D":"The road is very quiet"},"correct_answer":"B","explanation":"Lợi ích được tác giả nêu: đạp xe chỉ mất 12 phút, nhanh hơn so với tuyến xe buýt thường ngày (''faster than my usual bus route'')."},{"id":"read9_m1_q12","type":"multiple_choice","prompt":"How does the writer feel about the hill?","options":{"A":"It''s exhausting","B":"It''s fun","C":"It''s dangerous","D":"It''s boring"},"correct_answer":"A","explanation":"Đoạn văn miêu tả: ngọn đồi quá dốc và ''my legs were burning'' (chân mỏi nhừ/kiệt sức - exhausting) khi lên đến đỉnh."}]}},{"id":"read9_m1_t3","title":"Task 3: Read a Campus Library Update (Exam Week Extended Hours)","task_type":"read_daily_life","content":{"document_type":"Library Announcement","passage":"To support students during exam week, the campus library will extend its weekday hours until midnight. This change is intended to give everyone more time to study, especially those who prefer a quiet environment late at night. Study rooms must be reserved in advance through the online system because they fill up quickly. The café inside the library will also stay open until 10 p.m. to offer snacks and drinks.","questions":[{"id":"read9_m1_q13","type":"multiple_choice","prompt":"Why are the hours being extended?","options":{"A":"To test a new system","B":"Because of exam week","C":"Because volunteers requested it","D":"Because the study rooms fill up quickly"},"correct_answer":"B","explanation":"Thông báo ghi rõ: ''To support students during exam week, the campus library will extend its weekday hours until midnight''."},{"id":"read9_m1_q14","type":"multiple_choice","prompt":"What needs to be reserved?","options":{"A":"Computer use","B":"Café tables","C":"Study rooms","D":"Textbooks"},"correct_answer":"C","explanation":"Đoạn văn yêu cầu: ''Study rooms must be reserved in advance through the online system''."},{"id":"read9_m1_q15","type":"multiple_choice","prompt":"What can be inferred about the café work hours?","options":{"A":"It will stay open until the library closes","B":"It is usually open until 10 p.m.","C":"It usually closes earlier","D":"It will not offer snacks in the evening"},"correct_answer":"C","explanation":"Việc quán cà phê ''sẽ cũng mở cửa đến 10 giờ tối để phục vụ đồ ăn nhẹ'' cho thấy bình thường quán đóng cửa sớm hơn thời điểm này."}]}},{"id":"read9_m1_t4","title":"Task 4: Academic Passage (The Economics of Attention)","task_type":"academic_passage","content":{"document_type":"Digital Economy & Media Studies Passage","passage":"In modern digital environments, human attention has become a scarce and valuable resource. As a result, companies compete not only for consumers'' money, but also for their time and focus. This shift has created what economists call the \"attention economy,\" in which platforms are designed to capture and retain user engagement for extended periods. Unlike traditional markets, where goods and services are exchanged, this system monetizes user behavior through advertising and data collection.\n\nMany digital services rely on sophisticated algorithms that personalize content based on user activity. These systems analyze patterns such as viewing history, clicks, and interaction time to predict what users are most likely to engage with next. They often prioritize emotionally engaging material because it increases sharing and interaction. Consequently, users may spend more time on platforms than they originally intended, often without fully realizing it.\n\nHowever, this model has significant implications for individuals and society. Critics argue that constant competition for attention can reduce concentration and encourage the spread of sensationalized or misleading information. Because engagement determines visibility, content creators may feel pressured to produce extreme or polarizing material. Despite these concerns, the attention economy continues to expand, influencing entertainment, news consumption, education, and even social relationships.","questions":[{"id":"read9_m1_q16","type":"multiple_choice","prompt":"What is the main idea of the passage?","options":{"A":"Some digital platforms are losing popularity among users","B":"The attention economy is based on capturing and monetizing human attention","C":"Algorithms are unreliable tools for personalization","D":"Users are fully aware of how platforms influence them"},"correct_answer":"B","explanation":"Ý chính của bài: Nền kinh tế chú ý dựa trên việc thu hút và kiếm tiền từ thời gian và sự chú ý của người dùng."},{"id":"read9_m1_q17","type":"multiple_choice","prompt":"The word \"sophisticated\" in the passage is closest in meaning to","options":{"A":"simple","B":"advanced","C":"unclear","D":"ineffective"},"correct_answer":"B","explanation":"''sophisticated'' nghĩa là tinh vi, tiên tiến, hiện đại (''advanced'')."},{"id":"read9_m1_q18","type":"multiple_choice","prompt":"What can be inferred about personalized algorithms?","options":{"A":"They reduce user engagement over time","B":"They are controlled entirely by users","C":"They provide only factual information","D":"They aim to keep users on platforms longer"},"correct_answer":"D","explanation":"Thuật toán cá nhân hóa phân tích dữ liệu để dự đoán và giữ chân người dùng ở lại nền tảng lâu hơn (''capture and retain user engagement for extended periods'')."},{"id":"read9_m1_q19","type":"multiple_choice","prompt":"What is the relationship between the second and third paragraphs?","options":{"A":"The third paragraph provides consequences of the processes described in the second","B":"The third paragraph contradicts the second","C":"The second paragraph summarizes the third","D":"The paragraphs describe unrelated topics"},"correct_answer":"A","explanation":"Đoạn 2 miêu tả cách thức hoạt động của thuật toán giữ chân người dùng; đoạn 3 trình bày các hệ quả và tác động tiêu cực của mô hình này đối với cá nhân và xã hội."},{"id":"read9_m1_q20","type":"multiple_choice","prompt":"What does \"this model\" in the third paragraph refer to?","options":{"A":"Traditional economic systems","B":"The use of algorithms to capture and monetize attention","C":"The decline of advertising","D":"The growth of education platforms"},"correct_answer":"B","explanation":"''this model'' ám chỉ mô hình sử dụng thuật toán cá nhân hóa để thu hút và thương mại hóa sự chú ý của người dùng được phân tích ở các đoạn trên."}]}}]},{"id":"read9_stage_2","title":"Reading - Module 2 (Stage 2 - HARD C1 Adaptive)","duration_seconds":900,"description":"Module 2 khó (C1) gồm 4 phần (20 câu hỏi). Hãy hoàn thành trước khi hết 15 phút.","tasks":[{"id":"read9_m2_t1","title":"Task 1: Complete the Words (Đoạn 1 - Cultural Diversity)","task_type":"complete_words","content":{"instructions":"Điền các chữ cái còn thiếu vào vị trí dấu gạch dưới `_` trong đoạn văn sau:","paragraph":"Cultural diversity enriches societies by bringing together a wide range of perspectives, traditions, and values. Exposure to diffe[rent] cultures promo[tes] tolerance, empa[thy], and mutu[al] understanding amo[ng] community memb[ers]. Diverse environ[ments] often stimu[late] creativity bec[ause] people exch[ange] ideas shaped by varied experiences. At the same time, managing diversity requires inclusive policies, open dialogue, and respect for differences. When diversity is recognized and appreciated, it strengthens social cohesion. Communities that embrace cultural variety are often more dynamic, innovative, and resilient in the face of social change.","blanks":[{"id":"read9_m2_t1_b1","prefix":"diffe","missing":"rent","full":"different"},{"id":"read9_m2_t1_b2","prefix":"promo","missing":"tes","full":"promotes"},{"id":"read9_m2_t1_b3","prefix":"empa","missing":"thy","full":"empathy"},{"id":"read9_m2_t1_b4","prefix":"mutu","missing":"al","full":"mutual"},{"id":"read9_m2_t1_b5","prefix":"amo","missing":"ng","full":"among"},{"id":"read9_m2_t1_b6","prefix":"memb","missing":"ers","full":"members"},{"id":"read9_m2_t1_b7","prefix":"environ","missing":"ments","full":"environments"},{"id":"read9_m2_t1_b8","prefix":"stimu","missing":"late","full":"stimulate"},{"id":"read9_m2_t1_b9","prefix":"bec","missing":"ause","full":"because"},{"id":"read9_m2_t1_b10","prefix":"exch","missing":"ange","full":"exchange"}]}},{"id":"read9_m2_t2","title":"Task 2: Read a Menu Notice (Campus Café Drink Menu Update)","task_type":"read_daily_life","content":{"document_type":"Café Menu Announcement","passage":"Starting next week, the campus café will expand its drink menu by offering several plant-based milk alternatives. Students ordering beverages will be able to choose oat, almond, or soy milk instead of regular dairy milk. Due to higher supplier costs, selecting one of these options will add 50 cents to the price of the drink. The café clarified that no other menu items will be affected by this change. Management hopes this update will better accommodate students with different dietary preferences and restrictions.","questions":[{"id":"read9_m2_q11","type":"multiple_choice","prompt":"What change is being introduced?","options":{"A":"Alternative milk choices","B":"New dessert options","C":"Lower drink prices","D":"A modification of existing prices"},"correct_answer":"A","explanation":"Thay đổi được áp dụng là bổ sung các lựa chọn sữa nguồn gốc thực vật (''offering several plant-based milk alternatives'')."},{"id":"read9_m2_q12","type":"multiple_choice","prompt":"What can be understood about the rest of the menu?","options":{"A":"Some prices will increase","B":"Only drinks will be discounted","C":"Other items will remain unchanged","D":"One product will be removed"},"correct_answer":"C","explanation":"Thông báo khẳng định rõ các món khác trong menu không bị ảnh hưởng: ''no other menu items will be affected by this change''."}]}},{"id":"read9_m2_t3","title":"Task 3: Read a Store Notice (Winter Apparel Sale)","task_type":"read_daily_life","content":{"document_type":"Store Promotion Notice","passage":"Due to an upcoming seasonal transition, the store will offer a 30% discount on all winter apparel this weekend only. The promotion applies to coats, knitwear, scarves, gloves, and other cold-weather garments. Because this is a limited-time clearance event, customers may not combine this offer with any other coupons, loyalty rewards, or ongoing promotions. The management anticipates a significant increase in customer traffic and advises shoppers to arrive early to ensure a wider selection of available sizes and styles.","questions":[{"id":"read9_m2_q13","type":"multiple_choice","prompt":"What is the primary purpose of this sale?","options":{"A":"To introduce a new clothing collection","B":"To reduce prices for loyal customers","C":"To clear winter inventory before the season changes","D":"To test a new discount system"},"correct_answer":"C","explanation":"Mục đích chính của đợt giảm giá là xả hàng tồn mùa đông trước khi chuyển mùa (''clear winter inventory before the season changes'')."},{"id":"read9_m2_q14","type":"multiple_choice","prompt":"What restriction is placed on customers?","options":{"A":"Only certain items can be purchased","B":"They must arrive early","C":"Purchases must be made online","D":"Other discounts cannot be applied"},"correct_answer":"D","explanation":"Hạn chế quy định rõ khách không được áp dụng đồng thời các phiếu giảm giá hay ưu đãi khác (''customers may not combine this offer with any other coupons...'')."},{"id":"read9_m2_q15","type":"multiple_choice","prompt":"What can be inferred about product availability?","options":{"A":"All sizes will be fully stocked throughout the weekend","B":"Popular items may sell out quickly","C":"Winter clothing is rarely purchased","D":"The store will restock items during the sale"},"correct_answer":"B","explanation":"Cửa hàng khuyên khách đến sớm để có nhiều lựa chọn kích cỡ và mẫu mã, ngụ ý các mặt hàng hot sẽ nhanh chóng hết hàng (''Popular items may sell out quickly'')."}]}},{"id":"read9_m2_t4","title":"Task 4: Academic Passage (The Development of Artificial Intelligence)","task_type":"academic_passage","content":{"document_type":"Computer Science Passage","passage":"[A] Artificial intelligence (Al) refers to the ability of machines to perform tasks that typically require human intelligence, such as learning, reasoning, and problem-solving. [B] Although the concept of intelligent machines has existed for decades, recent advances in computing power and data availability have significantly accelerated the development of Al technologies. [C] Today, Al systems are used in a wide range of applications, from medical diagnosis to language translation. [D]\n\nOne of the key factors behind this progress is the rise of machine learning, a method that allows computers to learn from data without being explicitly programmed for every task. By analyzing large datasets, these systems can identify patterns and make predictions with increasing accuracy. For example, Al models can detect diseases in medical images or recommend products based on user preferences. As these systems improve, they become more capable of performing complex and specialized tasks.\n\nDespite these benefits, the rapid growth of Al has raised important ethical and social concerns. Some experts worry about issues such as job displacement, privacy, and the potential misuse of Al technologies. In response, governments and organizations are working to establish guidelines and regulations to ensure that Al is developed and used responsibly. As Al continues to evolve, its impact on society will likely become even more significant.","questions":[{"id":"read9_m2_q16","type":"multiple_choice","prompt":"What is the main idea of the passage?","options":{"A":"Al has no practical applications","B":"Al is developing rapidly and has both benefits and concerns","C":"Machine learning is no longer relevant","D":"Governogly opposes Al development"},"correct_answer":"B","explanation":"Ý chính của bài: Trí tuệ nhân tạo đang phát triển nhanh chóng, mang lại nhiều lợi ích thực tế nhưng cũng dấy lên không ít quan ngại xã hội."},{"id":"read9_m2_q17","type":"multiple_choice","prompt":"The word \"accelerated\" in the passage is closest in meaning to","options":{"A":"slowed down","B":"stopped","C":"sped up","D":"ignored"},"correct_answer":"C","explanation":"''accelerated'' có nghĩa là thúc đẩy, đẩy nhanh tiến độ (''sped up'')."},{"id":"read9_m2_q18","type":"multiple_choice","prompt":"What is the author''s purpose in the third paragraph?","options":{"A":"To explain how Al systems are built","B":"To highlight concerns and responses related to Al","C":"To describe technical details of machine learning","D":"To argue against technological progress"},"correct_answer":"B","explanation":"Mục đích đoạn 3: Nêu bật các quan ngại về việc mất việc làm, quyền riêng tư và các chính sách ứng phó từ chính phủ (''highlight concerns and responses related to AI'')."},{"id":"read9_m2_q19","type":"multiple_choice","prompt":"Where would the following sentence best fit: \"This progress has allowed Al to move from theoretical research into practical, everyday use.\"?","options":{"A":"Location A","B":"Location B","C":"Location C","D":"Location D"},"correct_answer":"C","explanation":"Câu này nối tiếp hoàn hảo luận điểm ở câu trước về sự tiến bộ gia tốc của công nghệ AI, và dẫn vào câu tiếp theo về các ứng dụng thực tế phong phú ngày nay (tại [C])."},{"id":"read9_m2_q20","type":"multiple_choice","prompt":"Which of the following is NOT mentioned in the passage as a concern related to the growth of AI?","options":{"A":"The loss of jobs due to automation","B":"Risks to personal privacy","C":"The possible misuse of Al technologies","D":"The high cost of developing Al systems"},"correct_answer":"D","explanation":"Đoạn 3 đề cập đến mất việc làm (''job displacement''), quyền riêng tư (''privacy''), và nguy cơ lạm dụng (''misuse''), nhưng KHÔNG nhắc tới chi phí phát triển AI tốn kém."}]}}]}],"description":"Bộ đề TOEFL iBT 2026 Multistage Adaptive (YouTube Practice 8 - HARD Module 2 C1): Module 1 (Critical Reading, Biking to Campus, Library Exam Week, The Economics of Attention) & Module 2 (Cultural Diversity, Plant-Based Milk, Winter Apparel Sale, Development of AI).","created_at_ms":1791231607964}'::jsonb,
  timezone('utc'::text, now())
)
ON CONFLICT (id) DO UPDATE SET
  title = EXCLUDED.title,
  skill = EXCLUDED.skill,
  task_type = EXCLUDED.task_type,
  duration_seconds = EXCLUDED.duration_seconds,
  content = EXCLUDED.content;

INSERT INTO public.tests (id, title, skill, task_type, duration_seconds, content, created_at)
VALUES (
  'reading-practice-10',
  'Reading Practice Test 10 (TOEFL 2026 - Time Management & Sleep Consolidation)',
  'reading',
  'multistage',
  1800,
  '{"stages":[{"id":"read10_stage_1","title":"Reading - Module 1 (Stage 1)","duration_seconds":900,"description":"Module 1 gồm 4 phần (20 câu hỏi). Hãy hoàn thành trước khi hết 15 phút.","tasks":[{"id":"read10_m1_t1","title":"Task 1: Complete the Words (Đoạn 1 - Time Management)","task_type":"complete_words","content":{"instructions":"Điền các chữ cái còn thiếu vào vị trí dấu gạch dưới `_` trong đoạn văn sau:","paragraph":"Time management is essential for productivity, organization, and stress reduction in daily life. Planning tas[ks] in adv[ance] and sett[ing] clear prior[ities] allow indivi[duals] to us[e] their ti[me] more effici[ently]. Without effec[tive] time manag[ement], people may miss deadlines and feel overwhelmed by unfinished responsibilities. Establishing routines, setting realistic goals, and minimizing distractions can significantly improve focus. Good time management habits are valuable in both academic and professional settings. They enable individuals to complete tasks on time while maintaining a healthier balance between work and personal activities.","blanks":[{"id":"read10_m1_t1_b1","prefix":"tas","missing":"ks","full":"tasks"},{"id":"read10_m1_t1_b2","prefix":"adv","missing":"ance","full":"advance"},{"id":"read10_m1_t1_b3","prefix":"sett","missing":"ing","full":"setting"},{"id":"read10_m1_t1_b4","prefix":"prior","missing":"ities","full":"priorities"},{"id":"read10_m1_t1_b5","prefix":"indivi","missing":"duals","full":"individuals"},{"id":"read10_m1_t1_b6","prefix":"us","missing":"e","full":"use"},{"id":"read10_m1_t1_b7","prefix":"ti","missing":"me","full":"time"},{"id":"read10_m1_t1_b8","prefix":"effici","missing":"ently","full":"efficiently"},{"id":"read10_m1_t1_b9","prefix":"effec","missing":"tive","full":"effective"},{"id":"read10_m1_t1_b10","prefix":"manag","missing":"ement","full":"management"}]}},{"id":"read10_m1_t2","title":"Task 2: Read an Email from a Classmate (Presentation Preparation)","task_type":"read_daily_life","content":{"document_type":"Classmate Email","passage":"Hey! I just wanted to remind you that our group presentation is due this Friday. I''ve already finished the slides for the first two sections, but we still need to complete the conclusion and practice the timing. Could we meet tomorrow afternoon, either in the library or online? Just let me know what works for you. I want to make sure we''re fully prepared.","questions":[{"id":"read10_m1_q11","type":"multiple_choice","prompt":"Why is the writer contacting the reader?","options":{"A":"To cancel a meeting","B":"To plan work on a presentation","C":"To ask for lecture notes","D":"To complain about grades"},"correct_answer":"B","explanation":"Người viết gửi email để thảo luận và lên kế hoạch hoàn thành bài thuyết trình nhóm trước hạn thứ Sáu (\"complete the conclusion and practice the timing... meet tomorrow afternoon\")."},{"id":"read10_m1_q12","type":"multiple_choice","prompt":"What is still unfinished?","options":{"A":"The introduction","B":"The conclusion","C":"The examples","D":"The slides'' design"},"correct_answer":"B","explanation":"Người viết đề cập hai phần đầu của slide đã xong, phần còn lại chưa hoàn thành là kết luận (\"still need to complete the conclusion\")."}]}},{"id":"read10_m1_t3","title":"Task 3: Read a Student Council Announcement (Open Forum Meeting)","task_type":"read_daily_life","content":{"document_type":"Campus Announcement","passage":"The student council will host an open meeting next Thursday evening to hear suggestions about improving campus life. Everyone is welcome to share ideas, whether they relate to academics, dorm life, or extracurricular activities. The council especially wants feedback about study spaces on campus, since many students have recently expressed concerns. Snacks will be provided, and students may attend for any portion of the meeting.","questions":[{"id":"read10_m1_q13","type":"multiple_choice","prompt":"What is the main purpose of the meeting?","options":{"A":"To choose new council members","B":"To collect suggestions from students","C":"To raise money for events","D":"To announce rule changes"},"correct_answer":"B","explanation":"Mục đích chính của buổi họp mở là lắng nghe các ý kiến, đề xuất của sinh viên để cải thiện đời sống khuôn viên (\"to hear suggestions about improving campus life\")."},{"id":"read10_m1_q14","type":"multiple_choice","prompt":"What topic is the council particularly interested in?","options":{"A":"Study spaces","B":"Cafeteria food","C":"Sports programs","D":"Library noise"},"correct_answer":"A","explanation":"Hội đồng đặc biệt mong muốn nhận phản hồi về không gian học tập vì nhiều sinh viên vừa qua đã bày tỏ lo ngại (\"especially wants feedback about study spaces on campus\")."},{"id":"read10_m1_q15","type":"multiple_choice","prompt":"Why does the announcement mention that students may attend for any portion of the meeting?","options":{"A":"To limit the number of participants","B":"To encourage students to stay for the entire meeting","C":"To show that attendance is flexible","D":"To require students to register in advance"},"correct_answer":"C","explanation":"Thông báo nêu rõ sinh viên có thể tham dự bất kỳ lúc nào trong cuộc họp (\"students may attend for any portion of the meeting\") nhằm tạo sự linh hoạt, phù hợp lịch trình bận rộn của mọi người."}]}},{"id":"read10_m1_t4","title":"Task 4: Academic Reading (Cognitive Biases in Decision-Making)","task_type":"read_academic","content":{"academic_area":"Psychology / Behavioral Science","passage":"Human decision-making is often influenced by cognitive biases, which are systematic patterns of deviation from rational thinking. These biases can affect judgments in everyday situations, from financial decisions to social interactions. While they can sometimes function as useful mental shortcuts, allowing individuals to make quick decisions, they frequently lead to errors in reasoning and judgment. One well-known example is confirmation bias, in which individuals tend to seek out and interpret information in ways that support their existing beliefs. As a result, they may ignore or dismiss evidence that contradicts their views. This tendency can reinforce misconceptions and make it difficult for people to change their opinions, even when presented with strong evidence. Over time, such patterns can contribute to polarization in social and political contexts. Another important bias is the availability heuristic, which occurs when people estimate the likelihood of events based on how easily examples come to mind. For instance, individuals may overestimate the risk of rare but dramatic events, such as plane crashes, because they receive extensive media coverage. In contrast, more common but less visible risks may be underestimated. This demonstrates how cognitive biases can distort perception and influence decision-making. Understanding these biases is essential for improving critical thinking. By becoming aware of these tendencies, individuals can take steps to evaluate information more objectively and reduce the impact of bias on their decisions. This awareness is particularly important in fields such as science, business, and public policy, where accurate judgment is crucial.","questions":[{"id":"read10_m1_q16","type":"multiple_choice","prompt":"What is the main idea of the passage?","options":{"A":"Cognitive biases have no effect on decisions","B":"Cognitive biases influence thinking and can lead to errors","C":"People always make rational choices","D":"Media coverage is unreliable"},"correct_answer":"B","explanation":"Ý chính của bài đọc: Thiên kiến nhận thức định hình cách con người suy nghĩ và thường dẫn đến những sai lầm trong suy luận và phán đoán (\"influence thinking and can lead to errors\")."},{"id":"read10_m1_q17","type":"multiple_choice","prompt":"The word \"dismiss\" in the passage is closest in meaning to","options":{"A":"accept","B":"consider","C":"reject","D":"analyze"},"correct_answer":"C","explanation":"Từ \"dismiss\" trong ngữ cảnh từ chối, bỏ qua bằng chứng trái chiều đồng nghĩa với \"reject\" (bác bỏ, gạt bỏ)."},{"id":"read10_m1_q18","type":"multiple_choice","prompt":"What can be inferred about the availability heuristic?","options":{"A":"It leads to accurate risk assessment","B":"It depends on how easily examples are recalled","C":"It prevents cognitive errors","D":"It is only relevant in science"},"correct_answer":"B","explanation":"Quy tắc ngón tay cái về tính sẵn có (availability heuristic) ước tính khả năng xảy ra sự kiện dựa trên mức độ dễ dàng liên tưởng, nhớ lại các ví dụ (\"depends on how easily examples are recalled\")."},{"id":"read10_m1_q19","type":"multiple_choice","prompt":"What is the relationship between the second and third paragraphs?","options":{"A":"They describe different examples of cognitive biases","B":"The third paragraph contradicts the second","C":"The third paragraph summarizes the second","D":"They discuss unrelated topics"},"correct_answer":"A","explanation":"Đoạn 2 (thiên kiến khẳng định) và Đoạn 3 (availability heuristic) trình bày các ví dụ cụ thể khác nhau về thiên kiến nhận thức."},{"id":"read10_m1_q20","type":"multiple_choice","prompt":"Why does the author mention plane crashes in the third paragraph?","options":{"A":"To argue that air travel is more dangerous than people think","B":"To describe a common cause of cognitive bias in politics","C":"To show that rare events do not receive much attention","D":"To provide an example of how media coverage influences risk perception"},"correct_answer":"D","explanation":"Tác giả nhắc đến tai nạn máy bay như một ví dụ minh họa cho các sự kiện hiếm gặp nhưng gây ấn tượng mạnh, khiến con người dễ phóng đại rủi ro của chúng."}]}}]},{"id":"read10_stage_2","title":"Reading - Module 2 (Stage 2 - HARD)","duration_seconds":900,"description":"Module 2 gồm 4 phần (20 câu hỏi). Hãy hoàn thành trước khi hết 15 phút.","tasks":[{"id":"read10_m2_t1","title":"Task 1: Complete the Words (Đoạn 2 - Lifelong Learning)","task_type":"complete_words","content":{"instructions":"Điền các chữ cái còn thiếu vào vị trí dấu gạch dưới `_` trong đoạn văn sau:","paragraph":"Lifelong learning refers to the continuous pursuit of knowledge and skills throughout a person''s life. As techno[logy] and indust[ries] change rapi[dly], individuals mu[st] upd[ate] their abili[ties] to rema[in] competitive. Lear[ning] new ski[lls] regularly not on[ly] improves career opportunities but also contributes to personal growth and confidence. Online courses, digital libraries, and educational platforms make learning more accessible than ever before. A commitment to lifelong learning encourages curiosity and adaptability. People who continue learning are better prepared to face new challenges in a constantly evolving world.","blanks":[{"id":"read10_m2_t1_b1","prefix":"techno","missing":"logy","full":"technology"},{"id":"read10_m2_t1_b2","prefix":"indust","missing":"ries","full":"industries"},{"id":"read10_m2_t1_b3","prefix":"rapi","missing":"dly","full":"rapidly"},{"id":"read10_m2_t1_b4","prefix":"mu","missing":"st","full":"must"},{"id":"read10_m2_t1_b5","prefix":"upd","missing":"ate","full":"update"},{"id":"read10_m2_t1_b6","prefix":"abili","missing":"ties","full":"abilities"},{"id":"read10_m2_t1_b7","prefix":"rema","missing":"in","full":"remain"},{"id":"read10_m2_t1_b8","prefix":"Lear","missing":"ning","full":"Learning"},{"id":"read10_m2_t1_b9","prefix":"ski","missing":"lls","full":"skills"},{"id":"read10_m2_t1_b10","prefix":"on","missing":"ly","full":"only"}]}},{"id":"read10_m2_t2","title":"Task 2: Read a SMS Reminder from Doctor''s Office (Dental Appointment)","task_type":"read_daily_life","content":{"document_type":"Medical Office SMS","passage":"This is a reminder that you have a dental appointment scheduled for Monday at 10:30 a.m. Please plan to arrive at least 10 minutes early to complete the check-in process. If you need to reschedule, call our office by tomorrow afternoon. Failure to cancel in advance may result in a small fee. We look forward to seeing you.","questions":[{"id":"read10_m2_q11","type":"multiple_choice","prompt":"What is the purpose of the message?","options":{"A":"To send test results","B":"To confirm an appointment","C":"To suggest a treatment","D":"To announce a new clinic"},"correct_answer":"B","explanation":"Nội dung tin nhắn yêu cầu người nhận liên hệ phòng khám trước chiều mai nếu cần đổi lịch hẹn (\"If you need to reschedule, call our office by tomorrow afternoon\")."},{"id":"read10_m2_q12","type":"multiple_choice","prompt":"What happens if the person doesn''t cancel in advance?","options":{"A":"They will lose dental insurance","B":"They may have to pay a charge","C":"They must book online","D":"They must arrive later"},"correct_answer":"B","explanation":"Bệnh nhân được dặn đến sớm ít nhất 10 phút để hoàn tất thủ tục đăng ký khám (\"arrive at least 10 minutes early to complete the check-in process\")."}]}},{"id":"read10_m2_t3","title":"Task 3: Read a Store Receipt Message (Return Policy)","task_type":"read_daily_life","content":{"document_type":"Store Policy Notice","passage":"Thank you for shopping with us. This receipt confirms your purchase of three items: a hardcover notebook, a pack of gel pens, and a reusable stainless-steel water bottle. If you wish to return any product, please note that returns are accepted only within 14 days of purchase, provided the items remain unused and in their original packaging. Refunds will be processed using the same payment method selected at checkout. Please retain this receipt as proof of purchase. If you have any questions, you may contact customer service for assistance.","questions":[{"id":"read10_m2_q13","type":"multiple_choice","prompt":"What does the message mainly explain?","options":{"A":"How to contact customer service","B":"The store''s return policy","C":"How to use the items","D":"How to get store discounts"},"correct_answer":"B","explanation":"Hóa đơn xác nhận việc mua ba món đồ: một cuốn sổ tay bìa cứng, một gói bút gel và một bình nước thép không gỉ (\"a pack of gel pens\")."},{"id":"read10_m2_q14","type":"multiple_choice","prompt":"What did the customer buy?","options":{"A":"Clothing items","B":"Electronics","C":"Stationery and a bottle","D":"Only one item"},"correct_answer":"C","explanation":"Chính sách hoàn trả quy định rõ ràng rằng sản phẩm chỉ được đổi trả trong vòng 14 ngày kể từ ngày mua kèm hóa đơn gốc và trong tình trạng ban đầu (\"within 14 days of purchase\")."},{"id":"read10_m2_q15","type":"multiple_choice","prompt":"Why is the customer advised to keep the receipt?","options":{"A":"To exchange the items for different colors","B":"To show proof of purchase for returns","C":"To receive a future discount","D":"To register the products online"},"correct_answer":"B","explanation":"Nếu khách hàng làm mất hóa đơn gốc hoặc quá thời hạn 14 ngày thì cửa hàng sẽ không chấp nhận hoàn trả sản phẩm."}]}},{"id":"read10_m2_t4","title":"Task 4: Academic Reading (The Role of Sleep in Memory Consolidation)","task_type":"read_academic","content":{"academic_area":"Neuroscience / Cognitive Psychology","passage":"Sleep plays a fundamental role in memory consolidation, the process through which newly acquired information is stabilized and stored in the brain. During sleep, particularly in specific stages such as deep sleep and rapid eye movement (REM) sleep, the brain reactivates patterns of neural activity that occurred during waking hours. This process strengthens connections between neurons and helps transform short-term memories into long-term ones. Research indicates that both the quantity and quality of sleep are critical for effective learning. Individuals who do not get enough sleep often experience difficulties in recalling information and maintaining attention. In experimental settings, participants who were sleep-deprived performed significantly worse on cognitive tasks compared to those who had adequate rest. These findings suggest that sleep is not merely a passive state, but an active and essential component of cognitive functioning. Moreover, different types of memory appear to be influenced by different stages of sleep. For example, declarative memory, which involves facts and knowledge, is closely associated with deep sleep, while procedural memory, related to skills and actions, is linked to REM sleep. This distinction highlights the complexity of memory processes and the specialized roles that various sleep stages play. Overall, the study of sleep and memory continues to reveal important insights into how the brain processes information. Understanding these mechanisms can have practical applications in education, healthcare, and performance optimization.","questions":[{"id":"read10_m2_q16","type":"multiple_choice","prompt":"What is the main idea of the passage?","options":{"A":"Sleep is unimportant for learning","B":"Memory is only formed during waking hours","C":"Sleep is essential for memory consolidation and cognitive function","D":"REM sleep is the only important stage"},"correct_answer":"C","explanation":"Ý chính của bài đọc: Giấc ngủ đóng vai trò thiết yếu trong việc củng cố, ổn định và lưu giữ các ký ức mới vào não bộ (\"Sleep is essential for stabilizing and organizing memories\")."},{"id":"read10_m2_q17","type":"multiple_choice","prompt":"The word \"adequate\" in the passage is closest in meaning to","options":{"A":"insufficient","B":"excessive","C":"enough","D":"unusual"},"correct_answer":"C","explanation":"Từ \"reactivates\" mang nghĩa kích hoạt lại, tái hiện lại, đồng nghĩa với \"replays\" / \"triggers again\"."},{"id":"read10_m2_q18","type":"multiple_choice","prompt":"What can be inferred about sleep deprivation?","options":{"A":"It enhances memory performance","B":"It undermines cognitive abilities","C":"It has no measurable impact","D":"It makes it difficult to sleep later"},"correct_answer":"B","explanation":"Trong các giai đoạn ngủ sâu và ngủ REM, các mạng lưới thần kinh tái kích hoạt thông tin mới để chuyển dần từ lưu trữ ngắn hạn sang dài hạn."},{"id":"read10_m2_q19","type":"multiple_choice","prompt":"What is the relationship between the third and fourth paragraphs?","options":{"A":"The fourth paragraph summarizes and broadens the implications of the third","B":"The fourth paragraph contradicts the third","C":"The third paragraph introduces a problem that the fourth solves","D":"The paragraphs are unrelated"},"correct_answer":"A","explanation":"Đoạn thứ hai giải thích chi tiết cơ chế thần kinh củng cố ký ức diễn ra như thế nào trong suốt giấc ngủ."},{"id":"read10_m2_q20","type":"multiple_choice","prompt":"Which of the following is NOT mentioned in the passage as a role or effect of sleep?","options":{"A":"Strengthening neural connections involved in memory","B":"Helping transform short-term memories into long-term ones","C":"Improving physical strength and muscle recovery","D":"Supporting attention and information recall"},"correct_answer":"C","explanation":"Thiếu ngủ làm gián đoạn quá trình củng cố ký ức, khiến khả năng ghi nhớ và học tập suy giảm nghiêm trọng."}]}}]}],"description":"Bộ đề TOEFL iBT 2026 Multistage Adaptive (YouTube Practice 9): Module 1 (Time Management, Classmate Email, Student Council, Cognitive Biases) & Module 2 (Lifelong Learning, Doctor SMS, Store Receipt, Sleep & Memory Consolidation).","created_at_ms":1791231607964}'::jsonb,
  timezone('utc'::text, now())
)
ON CONFLICT (id) DO UPDATE SET
  title = EXCLUDED.title,
  skill = EXCLUDED.skill,
  task_type = EXCLUDED.task_type,
  duration_seconds = EXCLUDED.duration_seconds,
  content = EXCLUDED.content;

INSERT INTO public.tests (id, title, skill, task_type, duration_seconds, content, created_at)
VALUES (
  'reading-practice-11',
  'Reading Practice Test 11 (TOEFL 2026 - Healthy Nutrition & Collective Memory)',
  'reading',
  'multistage',
  1800,
  '{"stages":[{"id":"read11_stage_1","title":"Reading - Module 1 (Stage 1)","duration_seconds":900,"description":"Module 1 gồm 4 phần (20 câu hỏi). Hãy hoàn thành trước khi hết 15 phút.","tasks":[{"id":"read11_m1_t1","title":"Task 1: Complete the Words (Đoạn 1 - Healthy Eating Habits)","task_type":"complete_words","content":{"instructions":"Điền các chữ cái còn thiếu vào vị trí dấu gạch dưới `_` trong đoạn văn sau:","paragraph":"Healthy eating habits contribute significantly to long-term physical and mental well-being. Balanced die[ts] provide essen[tial] nutrients th[at] support ene[rgy] levels, immu[ne] function, a[nd] overall he[alth]. Excessive consu[mption] of proce[ssed] foods, su[gar], and unhealthy fats can lead to chronic diseases such as diabetes and heart conditions. Awareness of nutrition helps individuals make informed food choices. Developing consistent healthy eating routines reduces health risks and improves quality of life. Proper nutrition also supports concentration, mood stability, and productivity in daily activities.","blanks":[{"id":"read11_m1_t1_b1","prefix":"die","missing":"ts","full":"diets"},{"id":"read11_m1_t1_b2","prefix":"essen","missing":"tial","full":"essential"},{"id":"read11_m1_t1_b3","prefix":"th","missing":"at","full":"that"},{"id":"read11_m1_t1_b4","prefix":"ene","missing":"rgy","full":"energy"},{"id":"read11_m1_t1_b5","prefix":"immu","missing":"ne","full":"immune"},{"id":"read11_m1_t1_b6","prefix":"a","missing":"nd","full":"and"},{"id":"read11_m1_t1_b7","prefix":"he","missing":"alth","full":"health"},{"id":"read11_m1_t1_b8","prefix":"consu","missing":"mption","full":"consumption"},{"id":"read11_m1_t1_b9","prefix":"proce","missing":"ssed","full":"processed"},{"id":"read11_m1_t1_b10","prefix":"su","missing":"gar","full":"sugar"}]}},{"id":"read11_m1_t2","title":"Task 2: Read a Campus Cafeteria Notice (Menu Update)","task_type":"read_daily_life","content":{"document_type":"Campus Dining Notice","passage":"Due to a temporary shortage of staff, the cafeteria will provide a limited menu this week. Popular items like pasta bowls and custom sandwiches will still be available, but several specialty dishes will not be offered. We apologize for any inconvenience, and we expect to return to the full menu next Monday once additional staff members complete their training.","questions":[{"id":"read11_m1_q11","type":"multiple_choice","prompt":"Why has the cafeteria reduced the number of food options?","options":{"A":"The cafeteria is undergoing renovations","B":"New employees are still in training","C":"The cafeteria has recently changed ownership","D":"Some kitchen equipment needs to be repaired"},"correct_answer":"B","explanation":"Nhà ăn thông báo mở rộng các lựa chọn ăn uống lành mạnh và bổ dưỡng hơn cho sinh viên (\"introduce more nutritious options\")."},{"id":"read11_m1_q12","type":"multiple_choice","prompt":"What is the cafeteria administration expecting to happen next week?","options":{"A":"More specialty meals will be added gradually.","B":"Food prices will increase.","C":"The cafeteria will return to its usual menu.","D":"The cafeteria will close for maintenance."},"correct_answer":"C","explanation":"Sinh viên có nhu cầu hoặc dị ứng thực phẩm có thể yêu cầu nhân viên cung cấp bảng thành phần chi tiết của các món ăn."}]}},{"id":"read11_m1_t3","title":"Task 3: Read an Online Shipping Update (Package Delivery)","task_type":"read_daily_life","content":{"document_type":"Shipping Status Email","passage":"Your package has left the distribution center and is currently making its way to the destination. According to the latest estimate, it should arrive sometime between Tuesday and Thursday. You can monitor its progress using the tracking link below. While most deliveries arrive on schedule, severe weather conditions or transportation disruptions may occasionally cause delays. If you expect to be unavailable during the delivery period, you may choose to have the package delivered to a nearby pickup location instead.","questions":[{"id":"read11_m1_q13","type":"multiple_choice","prompt":"What does the notice suggest about the package?","options":{"A":"It has not yet been processed.","B":"It is currently being transported.","C":"It has already been delivered.","D":"It is being returned to the sender."},"correct_answer":"B","explanation":"Thông báo cập nhật tình trạng đơn hàng đang được vận chuyển và dự kiến giao vào ngày làm việc tiếp theo."},{"id":"read11_m1_q14","type":"multiple_choice","prompt":"According to the notice, what could interfere with the expected arrival date?","options":{"A":"Technical problems with the tracking system.","B":"A shortage of delivery workers.","C":"Weather-related or transportation issues.","D":"Problems with the customer''s payment."},"correct_answer":"C","explanation":"Khách hàng có thể thay đổi địa chỉ giao hàng hoặc thời gian nhận thông qua cổng thông tin theo dõi trực tuyến."},{"id":"read11_m1_q15","type":"multiple_choice","prompt":"What can customers do if they are not available to receive the package?","options":{"A":"Cancel the shipment.","B":"Change the delivery address permanently.","C":"Request delivery to another nearby collection point.","D":"Extend the delivery period by one week."},"correct_answer":"C","explanation":"Nếu không có người nhận tại nhà, bưu kiện sẽ được gửi an toàn tại bưu cục gần nhất để nhận sau."}]}},{"id":"read11_m1_t4","title":"Task 4: Academic Reading (Cultural Diffusion)","task_type":"read_academic","content":{"academic_area":"Anthropology / Sociology","passage":"Cultural diffusion refers to the spread of ideas, beliefs, technologies, customs, and social practices from one society to another. This process has played a significant role throughout human history and has occurred through trade, migration, exploration, conquest, and communication. When people from different cultural backgrounds interact, they often exchange traditions, values, and knowledge that influence many aspects of daily life, including language, food, art, fashion, and social behavior. Although cultural diffusion frequently encourages innovation and broadens perspectives, it can also have negative consequences. In some situations, cultures with greater economic, political, or technological influence spread their practices more widely than others. As a result, smaller cultural groups may gradually lose traditional customs, languages, or beliefs. This trend can contribute to cultural homogenization, a process in which distinct cultural identities become less noticeable as societies adopt similar patterns and lifestyles. In the modern era, globalization has dramatically accelerated cultural diffusion. Improvements in transportation and digital technology allow information to travel across the world within seconds. Social media platforms, streaming services, and online communities enable individuals to share cultural content with international audiences almost instantly. While this increased connectivity creates opportunities for learning and cooperation, it also raises concerns about preserving cultural diversity in an increasingly interconnected world.","questions":[{"id":"read11_m1_q16","type":"multiple_choice","prompt":"Which of the following best states the main idea of the passage?","options":{"A":"Cultural diffusion primarily creates negative consequences for societies","B":"Cultural diffusion spreads cultural elements and has both benefits and challenges","C":"Recently, globalization has been preventing cultural exchange","D":"Traditions usually don''t change in most countries"},"correct_answer":"B","explanation":"Ý chính của bài đọc: Sự khuếch tán văn hóa là quá trình các yếu tố văn hóa lan truyền từ xã hội này sang xã hội khác qua giao thương, di cư và truyền thông."},{"id":"read11_m1_q17","type":"multiple_choice","prompt":"The word \"homogenization\" in the passage is closest in meaning to","options":{"A":"diversification","B":"standardization","C":"isolation","D":"preservation"},"correct_answer":"B","explanation":"Từ \"incorporate\" trong bài mang nghĩa kết hợp, tiếp thu các nét văn hóa mới vào nền văn hóa bản địa (\"integrate\" / \"adopt\")."},{"id":"read11_m1_q18","type":"multiple_choice","prompt":"What can be inferred from the passage about societies with less cultural influence?","options":{"A":"Their traditions may be more vulnerable to being replaced over time.","B":"They are unlikely to participate in cultural exchange.","C":"They benefit more from globalization than larger societies.","D":"They tend to adopt fewer technological innovations."},"correct_answer":"A","explanation":"Thương mại và giao thương là một trong những phương thức chủ yếu thúc đẩy sự trao đổi văn hóa và công nghệ giữa các cộng đồng."},{"id":"read11_m1_q19","type":"multiple_choice","prompt":"According to the passage, all of the following are true EXCEPT","options":{"A":"Cultural diffusion can occur through migration and trade.","B":"Social media has increased the speed at which cultural content can spread.","C":"Smaller cultural groups may lose some traditional practices over time.","D":"Cultural diffusion only became possible after the development of digital technology."},"correct_answer":"D","explanation":"Các xã hội tiếp nhận thường điều chỉnh những yếu tố văn hóa du nhập để phù hợp với các giá trị và tập quán truyền thống của riêng họ."},{"id":"read11_m1_q20","type":"multiple_choice","prompt":"Why does the author mention trade, migration, exploration, conquest, and communication in the first paragraph?","options":{"A":"To provide examples of the ways cultural diffusion occurs.","B":"To compare modern and historical societies.","C":"To identify the most effective method of spreading culture.","D":"To explain why cultural traditions disappear."},"correct_answer":"A","explanation":"Quá trình khuếch tán văn hóa diễn ra hai chiều và làm phong phú thêm đời sống của cả các nền văn hóa tham gia tương tác."}]}}]},{"id":"read11_stage_2","title":"Reading - Module 2 (Stage 2 - HARD)","duration_seconds":900,"description":"Module 2 gồm 4 phần (20 câu hỏi). Hãy hoàn thành trước khi hết 15 phút.","tasks":[{"id":"read11_m2_t1","title":"Task 1: Complete the Words (Đoạn 2 - Public Transportation)","task_type":"complete_words","content":{"instructions":"Điền các chữ cái còn thiếu vào vị trí dấu gạch dưới `_` trong đoạn văn sau:","paragraph":"Public transportation plays a key role in reducing traffic congestion, pollution, and travel costs in urban areas. Efficient sys[tems] allow la[rge] numbers o[f] people to mo[ve] quickly and reli[ably] across cit[ies]. Investments in bu[ses], trains, and subw[ays] contribute to environ[mental] sustainability by lowe[ring] the number of private vehicles on the road. Reliable transportation networks also improve access to employment, education, and healthcare. As cities grow, expanding and modernizing public transport becomes increasingly important. Well-planned systems enhance both economic activity and residents'' quality of life.","blanks":[{"id":"read11_m2_t1_b1","prefix":"sys","missing":"tems","full":"systems"},{"id":"read11_m2_t1_b2","prefix":"la","missing":"rge","full":"large"},{"id":"read11_m2_t1_b3","prefix":"o","missing":"f","full":"of"},{"id":"read11_m2_t1_b4","prefix":"mo","missing":"ve","full":"move"},{"id":"read11_m2_t1_b5","prefix":"reli","missing":"ably","full":"reliably"},{"id":"read11_m2_t1_b6","prefix":"cit","missing":"ies","full":"cities"},{"id":"read11_m2_t1_b7","prefix":"bu","missing":"ses","full":"buses"},{"id":"read11_m2_t1_b8","prefix":"subw","missing":"ays","full":"subways"},{"id":"read11_m2_t1_b9","prefix":"environ","missing":"mental","full":"environmental"},{"id":"read11_m2_t1_b10","prefix":"lowe","missing":"ring","full":"lowering"}]}},{"id":"read11_m2_t2","title":"Task 2: Read a Travel Blog Entry (Mountain Hiking Experience)","task_type":"read_daily_life","content":{"document_type":"Travel Blog Entry","passage":"Last weekend, I took a short trip to a coastal town located a couple of hours outside the city. What impressed me most was how relaxed and unspoiled the area felt compared to more popular tourist destinations. I spent much of my time browsing outdoor markets, where local craftspeople displayed handmade jewelry, ceramics, and artwork inspired by the region''s history. Although the town itself was charming, getting around without a car proved somewhat inconvenient. Public transportation was infrequent, and I ended up waiting nearly an hour for the return bus. Even so, the town''s quiet atmosphere and scenic surroundings more than compensated for the minor inconvenience.","questions":[{"id":"read11_m2_q11","type":"multiple_choice","prompt":"What aspect of the trip did the writer find particularly appealing?","options":{"A":"The variety of entertainment options available after dark.","B":"The opportunity to explore locally produced crafts and artwork.","C":"The efficiency of the town''s transportation network.","D":"The large number of modern shopping centers."},"correct_answer":"B","explanation":"Tác giả bài blog chia sẻ trải nghiệm chinh phục cung đường leo núi và ngắm nhìn cảnh bình minh tuyệt đẹp từ đỉnh núi."},{"id":"read11_m2_q12","type":"multiple_choice","prompt":"Which challenge did the writer encounter during the visit?","options":{"A":"Reaching the town took significantly longer than expected.","B":"Accommodation costs were higher than anticipated.","C":"Popular tourist sites were overcrowded throughout the weekend.","D":"Limited transportation made traveling around the area less convenient."},"correct_answer":"D","explanation":"Khó khăn lớn nhất trong chuyến đi là thời tiết lạnh giá và sương mù dày đặc vào sáng sớm."}]}},{"id":"read11_m2_t3","title":"Task 3: Read a Message from a Tutor (Session Rescheduling)","task_type":"read_daily_life","content":{"document_type":"Tutor Advisory Notice","passage":"Hello, Mark. This is your Science tutor with an update regarding our scheduled meeting. Due to a professional development workshop that I have been asked to attend tomorrow afternoon, I need to reschedule your appointment. Instead of meeting at 2:00 p.m., we''ll meet at 4:00 p.m. in Room 314 as originally planned. If this revised time creates any conflicts with your schedule, please contact me at your earliest convenience so that we can discuss alternative arrangements.","questions":[{"id":"read11_m2_q13","type":"multiple_choice","prompt":"What is the main purpose of the message?","options":{"A":"To explain changes to a classroom location.","B":"To notify a student about a scheduling change.","C":"To provide details about an upcoming workshop.","D":"To introduce a new tutoring program."},"correct_answer":"B","explanation":"Gia sư gửi tin nhắn để thông báo về việc dời buổi học phụ đạo sang một khung giờ khác do có lịch đột xuất."},{"id":"read11_m2_q14","type":"multiple_choice","prompt":"What does the tutor ask the student to do if the new arrangement is unsuitable?","options":{"A":"Contact the department office to request a different room.","B":"Attend the session remotely instead.","C":"Contact the tutor to discuss other possible options.","D":"Arrive earlier and wait until the tutor is available."},"correct_answer":"C","explanation":"Sinh viên được yêu cầu chuẩn bị trước các câu hỏi và bài tập chưa hiểu để buổi học diễn ra hiệu quả hơn."},{"id":"read11_m2_q15","type":"multiple_choice","prompt":"What can be inferred from the message?","options":{"A":"The tutor expects the workshop to end before 4:00 p.m.","B":"The meeting will take place online instead of in person.","C":"The student previously requested a different appointment time.","D":"The tutor will be unavailable for the rest of the week."},"correct_answer":"A","explanation":"Buổi học bù sẽ được tổ chức qua phòng học trực tuyến nếu sinh viên không thể đến gặp trực tiếp."}]}},{"id":"read11_m2_t4","title":"Task 4: Academic Reading (Collective Memory and Social Identity)","task_type":"read_academic","content":{"academic_area":"Sociology / Social Psychology","passage":"Collective memory refers to the shared understanding of the past held by a group, community, or society. Unlike individual memory, which is based on personal experiences, collective memory is shaped through stories, traditions, education, and public commemorations. Historical events that become part of a society''s collective memory often influence how people understand their identity and their relationship to others. The formation of collective memory is not always a straightforward process. Different groups may remember the same event in different ways depending on their experiences and perspectives. Governments, educational institutions, and media organizations can also play a role in determining which events receive greater attention and how they are interpreted. As a result, collective memory is often selective rather than completely objective. Despite these limitations, collective memory serves important social functions. Shared memories can strengthen social bonds and provide communities with a sense of continuity across generations. At the same time, disagreements about historical events may lead to debates about how the past should be represented. Consequently, collective memory is best understood not as a perfect record of history but as an evolving interpretation of it.","questions":[{"id":"read11_m2_q16","type":"multiple_choice","prompt":"Which of the following best states the main idea of the passage?","options":{"A":"Collective memory is an inaccurate form of historical record.","B":"Governments control all public understanding of history.","C":"Collective memory influences societies and is shaped by multiple factors.","D":"Historical events are generally remembered in the same way by all groups."},"correct_answer":"C","explanation":"Ý chính của bài đọc: Ký ức tập thể là sự chia sẻ và ghi nhớ chung về quá khứ của một cộng đồng, định hình nên bản sắc xã hội của họ."},{"id":"read11_m2_q17","type":"multiple_choice","prompt":"The word \"continuity\" in the passage is closest in meaning to","options":{"A":"conflict","B":"stability","C":"uncertainty","D":"separation"},"correct_answer":"B","explanation":"Từ \"transmitted\" nghĩa là truyền đạt, lưu truyền qua nhiều thế hệ (\"passed down\" / \"communicated\")."},{"id":"read11_m2_q18","type":"multiple_choice","prompt":"According to the passage, all of the following influence collective memory EXCEPT","options":{"A":"education","B":"public commemorations","C":"media organizations","D":"genetic inheritance"},"correct_answer":"D","explanation":"Các di tích, lễ kỷ niệm và viện bảo tàng đóng vai trò duy trì và tái hiện ký ức tập thể trong ý thức cộng đồng."},{"id":"read11_m2_q19","type":"multiple_choice","prompt":"What is the relationship between paragraphs 2 and 3?","options":{"A":"Paragraph 3 discusses ways of eliminating the limitations described in paragraph 2 and shows the result it can lead to.","B":"Paragraph 3 contradicts the claim made in paragraph 2.","C":"Paragraph 3 explains the historical origins of the issues discussed in paragraph 2.","D":"Paragraph 3 acknowledges the limitations described in paragraph 2 and discusses the functions of the same concept."},"correct_answer":"D","explanation":"Ký ức tập thể có thể được chọn lọc và diễn giải lại theo thời gian nhằm phục vụ các mục tiêu gắn kết xã hội hiện tại."},{"id":"read11_m2_q20","type":"multiple_choice","prompt":"Which of the following best expresses the essential information in the following sentence? Consequently, collective memory is best understood not as a perfect record of history but as an evolving interpretation of it.","options":{"A":"Collective memory provides a completely accurate account of historical events.","B":"Collective memory changes over time and reflects how people interpret the past.","C":"Collective memory becomes less important as societies develop.","D":"Collective memory is based entirely on personal experiences rather than shared events."},"correct_answer":"B","explanation":"Ký ức tập thể khác với ký ức cá nhân ở chỗ nó phản ánh quan điểm chung được chia sẻ rộng rãi trong một nhóm xã hội."}]}}]}],"description":"Bộ đề TOEFL iBT 2026 Multistage Adaptive (YouTube Practice 10): Module 1 (Healthy Eating, Campus Cafeteria, Shipping Update, Cultural Diffusion) & Module 2 (Public Transit, Travel Blog, Tutor Message, Collective Memory).","created_at_ms":1791231607965}'::jsonb,
  timezone('utc'::text, now())
)
ON CONFLICT (id) DO UPDATE SET
  title = EXCLUDED.title,
  skill = EXCLUDED.skill,
  task_type = EXCLUDED.task_type,
  duration_seconds = EXCLUDED.duration_seconds,
  content = EXCLUDED.content;

INSERT INTO public.tests (id, title, skill, task_type, duration_seconds, content, created_at)
VALUES (
  'reading-practice-12',
  'Reading Practice Test 12 (TOEFL 2026 - Healthy Nutrition & Collective Memory - Set B)',
  'reading',
  'multistage',
  1800,
  '{"stages":[{"id":"read12_stage_1","title":"Reading - Module 1 (Stage 1)","duration_seconds":900,"description":"Module 1 gồm 4 phần (20 câu hỏi). Hãy hoàn thành trước khi hết 15 phút.","tasks":[{"id":"read12_m1_t1","title":"Task 1: Complete the Words (Đoạn 1 - Healthy Eating Habits)","task_type":"complete_words","content":{"instructions":"Điền các chữ cái còn thiếu vào vị trí dấu gạch dưới `_` trong đoạn văn sau:","paragraph":"Healthy eating habits contribute significantly to long-term physical and mental well-being. Balanced die[ts] provide essen[tial] nutrients th[at] support ene[rgy] levels, immu[ne] function, a[nd] overall he[alth]. Excessive consu[mption] of proce[ssed] foods, su[gar], and unhealthy fats can lead to chronic diseases such as diabetes and heart conditions. Awareness of nutrition helps individuals make informed food choices. Developing consistent healthy eating routines reduces health risks and improves quality of life. Proper nutrition also supports concentration, mood stability, and productivity in daily activities.","blanks":[{"id":"read12_m1_t1_b1","prefix":"die","missing":"ts","full":"diets"},{"id":"read12_m1_t1_b2","prefix":"essen","missing":"tial","full":"essential"},{"id":"read12_m1_t1_b3","prefix":"th","missing":"at","full":"that"},{"id":"read12_m1_t1_b4","prefix":"ene","missing":"rgy","full":"energy"},{"id":"read12_m1_t1_b5","prefix":"immu","missing":"ne","full":"immune"},{"id":"read12_m1_t1_b6","prefix":"a","missing":"nd","full":"and"},{"id":"read12_m1_t1_b7","prefix":"he","missing":"alth","full":"health"},{"id":"read12_m1_t1_b8","prefix":"consu","missing":"mption","full":"consumption"},{"id":"read12_m1_t1_b9","prefix":"proce","missing":"ssed","full":"processed"},{"id":"read12_m1_t1_b10","prefix":"su","missing":"gar","full":"sugar"}]}},{"id":"read12_m1_t2","title":"Task 2: Read a Campus Cafeteria Notice (Menu Update)","task_type":"read_daily_life","content":{"document_type":"Campus Dining Notice","passage":"Due to a temporary shortage of staff, the cafeteria will provide a limited menu this week. Popular items like pasta bowls and custom sandwiches will still be available, but several specialty dishes will not be offered. We apologize for any inconvenience, and we expect to return to the full menu next Monday once additional staff members complete their training.","questions":[{"id":"read12_m1_q11","type":"multiple_choice","prompt":"Why has the cafeteria reduced the number of food options?","options":{"A":"The cafeteria is undergoing renovations","B":"New employees are still in training","C":"The cafeteria has recently changed ownership","D":"Some kitchen equipment needs to be repaired"},"correct_answer":"B","explanation":"Nhà ăn thông báo mở rộng các lựa chọn ăn uống lành mạnh và bổ dưỡng hơn cho sinh viên (\"introduce more nutritious options\")."},{"id":"read12_m1_q12","type":"multiple_choice","prompt":"What is the cafeteria administration expecting to happen next week?","options":{"A":"More specialty meals will be added gradually.","B":"Food prices will increase.","C":"The cafeteria will return to its usual menu.","D":"The cafeteria will close for maintenance."},"correct_answer":"C","explanation":"Sinh viên có nhu cầu hoặc dị ứng thực phẩm có thể yêu cầu nhân viên cung cấp bảng thành phần chi tiết của các món ăn."}]}},{"id":"read12_m1_t3","title":"Task 3: Read an Online Shipping Update (Package Delivery)","task_type":"read_daily_life","content":{"document_type":"Shipping Status Email","passage":"Your package has left the distribution center and is currently making its way to the destination. According to the latest estimate, it should arrive sometime between Tuesday and Thursday. You can monitor its progress using the tracking link below. While most deliveries arrive on schedule, severe weather conditions or transportation disruptions may occasionally cause delays. If you expect to be unavailable during the delivery period, you may choose to have the package delivered to a nearby pickup location instead.","questions":[{"id":"read12_m1_q13","type":"multiple_choice","prompt":"What does the notice suggest about the package?","options":{"A":"It has not yet been processed.","B":"It is currently being transported.","C":"It has already been delivered.","D":"It is being returned to the sender."},"correct_answer":"B","explanation":"Thông báo cập nhật tình trạng đơn hàng đang được vận chuyển và dự kiến giao vào ngày làm việc tiếp theo."},{"id":"read12_m1_q14","type":"multiple_choice","prompt":"According to the notice, what could interfere with the expected arrival date?","options":{"A":"Technical problems with the tracking system.","B":"A shortage of delivery workers.","C":"Weather-related or transportation issues.","D":"Problems with the customer''s payment."},"correct_answer":"C","explanation":"Khách hàng có thể thay đổi địa chỉ giao hàng hoặc thời gian nhận thông qua cổng thông tin theo dõi trực tuyến."},{"id":"read12_m1_q15","type":"multiple_choice","prompt":"What can customers do if they are not available to receive the package?","options":{"A":"Cancel the shipment.","B":"Change the delivery address permanently.","C":"Request delivery to another nearby collection point.","D":"Extend the delivery period by one week."},"correct_answer":"C","explanation":"Nếu không có người nhận tại nhà, bưu kiện sẽ được gửi an toàn tại bưu cục gần nhất để nhận sau."}]}},{"id":"read12_m1_t4","title":"Task 4: Academic Reading (Cultural Diffusion)","task_type":"read_academic","content":{"academic_area":"Anthropology / Sociology","passage":"Cultural diffusion refers to the spread of ideas, beliefs, technologies, customs, and social practices from one society to another. This process has played a significant role throughout human history and has occurred through trade, migration, exploration, conquest, and communication. When people from different cultural backgrounds interact, they often exchange traditions, values, and knowledge that influence many aspects of daily life, including language, food, art, fashion, and social behavior. Although cultural diffusion frequently encourages innovation and broadens perspectives, it can also have negative consequences. In some situations, cultures with greater economic, political, or technological influence spread their practices more widely than others. As a result, smaller cultural groups may gradually lose traditional customs, languages, or beliefs. This trend can contribute to cultural homogenization, a process in which distinct cultural identities become less noticeable as societies adopt similar patterns and lifestyles. In the modern era, globalization has dramatically accelerated cultural diffusion. Improvements in transportation and digital technology allow information to travel across the world within seconds. Social media platforms, streaming services, and online communities enable individuals to share cultural content with international audiences almost instantly. While this increased connectivity creates opportunities for learning and cooperation, it also raises concerns about preserving cultural diversity in an increasingly interconnected world.","questions":[{"id":"read12_m1_q16","type":"multiple_choice","prompt":"Which of the following best states the main idea of the passage?","options":{"A":"Cultural diffusion primarily creates negative consequences for societies","B":"Cultural diffusion spreads cultural elements and has both benefits and challenges","C":"Recently, globalization has been preventing cultural exchange","D":"Traditions usually don''t change in most countries"},"correct_answer":"B","explanation":"Ý chính của bài đọc: Sự khuếch tán văn hóa là quá trình các yếu tố văn hóa lan truyền từ xã hội này sang xã hội khác qua giao thương, di cư và truyền thông."},{"id":"read12_m1_q17","type":"multiple_choice","prompt":"The word \"homogenization\" in the passage is closest in meaning to","options":{"A":"diversification","B":"standardization","C":"isolation","D":"preservation"},"correct_answer":"B","explanation":"Từ \"incorporate\" trong bài mang nghĩa kết hợp, tiếp thu các nét văn hóa mới vào nền văn hóa bản địa (\"integrate\" / \"adopt\")."},{"id":"read12_m1_q18","type":"multiple_choice","prompt":"What can be inferred from the passage about societies with less cultural influence?","options":{"A":"Their traditions may be more vulnerable to being replaced over time.","B":"They are unlikely to participate in cultural exchange.","C":"They benefit more from globalization than larger societies.","D":"They tend to adopt fewer technological innovations."},"correct_answer":"A","explanation":"Thương mại và giao thương là một trong những phương thức chủ yếu thúc đẩy sự trao đổi văn hóa và công nghệ giữa các cộng đồng."},{"id":"read12_m1_q19","type":"multiple_choice","prompt":"According to the passage, all of the following are true EXCEPT","options":{"A":"Cultural diffusion can occur through migration and trade.","B":"Social media has increased the speed at which cultural content can spread.","C":"Smaller cultural groups may lose some traditional practices over time.","D":"Cultural diffusion only became possible after the development of digital technology."},"correct_answer":"D","explanation":"Các xã hội tiếp nhận thường điều chỉnh những yếu tố văn hóa du nhập để phù hợp với các giá trị và tập quán truyền thống của riêng họ."},{"id":"read12_m1_q20","type":"multiple_choice","prompt":"Why does the author mention trade, migration, exploration, conquest, and communication in the first paragraph?","options":{"A":"To provide examples of the ways cultural diffusion occurs.","B":"To compare modern and historical societies.","C":"To identify the most effective method of spreading culture.","D":"To explain why cultural traditions disappear."},"correct_answer":"A","explanation":"Quá trình khuếch tán văn hóa diễn ra hai chiều và làm phong phú thêm đời sống của cả các nền văn hóa tham gia tương tác."}]}}]},{"id":"read12_stage_2","title":"Reading - Module 2 (Stage 2 - HARD)","duration_seconds":900,"description":"Module 2 gồm 4 phần (20 câu hỏi). Hãy hoàn thành trước khi hết 15 phút.","tasks":[{"id":"read12_m2_t1","title":"Task 1: Complete the Words (Đoạn 2 - Public Transportation)","task_type":"complete_words","content":{"instructions":"Điền các chữ cái còn thiếu vào vị trí dấu gạch dưới `_` trong đoạn văn sau:","paragraph":"Public transportation plays a key role in reducing traffic congestion, pollution, and travel costs in urban areas. Efficient sys[tems] allow la[rge] numbers o[f] people to mo[ve] quickly and reli[ably] across cit[ies]. Investments in bu[ses], trains, and subw[ays] contribute to environ[mental] sustainability by lowe[ring] the number of private vehicles on the road. Reliable transportation networks also improve access to employment, education, and healthcare. As cities grow, expanding and modernizing public transport becomes increasingly important. Well-planned systems enhance both economic activity and residents'' quality of life.","blanks":[{"id":"read12_m2_t1_b1","prefix":"sys","missing":"tems","full":"systems"},{"id":"read12_m2_t1_b2","prefix":"la","missing":"rge","full":"large"},{"id":"read12_m2_t1_b3","prefix":"o","missing":"f","full":"of"},{"id":"read12_m2_t1_b4","prefix":"mo","missing":"ve","full":"move"},{"id":"read12_m2_t1_b5","prefix":"reli","missing":"ably","full":"reliably"},{"id":"read12_m2_t1_b6","prefix":"cit","missing":"ies","full":"cities"},{"id":"read12_m2_t1_b7","prefix":"bu","missing":"ses","full":"buses"},{"id":"read12_m2_t1_b8","prefix":"subw","missing":"ays","full":"subways"},{"id":"read12_m2_t1_b9","prefix":"environ","missing":"mental","full":"environmental"},{"id":"read12_m2_t1_b10","prefix":"lowe","missing":"ring","full":"lowering"}]}},{"id":"read12_m2_t2","title":"Task 2: Read a Travel Blog Entry (Mountain Hiking Experience)","task_type":"read_daily_life","content":{"document_type":"Travel Blog Entry","passage":"Last weekend, I took a short trip to a coastal town located a couple of hours outside the city. What impressed me most was how relaxed and unspoiled the area felt compared to more popular tourist destinations. I spent much of my time browsing outdoor markets, where local craftspeople displayed handmade jewelry, ceramics, and artwork inspired by the region''s history. Although the town itself was charming, getting around without a car proved somewhat inconvenient. Public transportation was infrequent, and I ended up waiting nearly an hour for the return bus. Even so, the town''s quiet atmosphere and scenic surroundings more than compensated for the minor inconvenience.","questions":[{"id":"read12_m2_q11","type":"multiple_choice","prompt":"What aspect of the trip did the writer find particularly appealing?","options":{"A":"The variety of entertainment options available after dark.","B":"The opportunity to explore locally produced crafts and artwork.","C":"The efficiency of the town''s transportation network.","D":"The large number of modern shopping centers."},"correct_answer":"B","explanation":"Tác giả bài blog chia sẻ trải nghiệm chinh phục cung đường leo núi và ngắm nhìn cảnh bình minh tuyệt đẹp từ đỉnh núi."},{"id":"read12_m2_q12","type":"multiple_choice","prompt":"Which challenge did the writer encounter during the visit?","options":{"A":"Reaching the town took significantly longer than expected.","B":"Accommodation costs were higher than anticipated.","C":"Popular tourist sites were overcrowded throughout the weekend.","D":"Limited transportation made traveling around the area less convenient."},"correct_answer":"D","explanation":"Khó khăn lớn nhất trong chuyến đi là thời tiết lạnh giá và sương mù dày đặc vào sáng sớm."}]}},{"id":"read12_m2_t3","title":"Task 3: Read a Message from a Tutor (Session Rescheduling)","task_type":"read_daily_life","content":{"document_type":"Tutor Advisory Notice","passage":"Hello, Mark. This is your Science tutor with an update regarding our scheduled meeting. Due to a professional development workshop that I have been asked to attend tomorrow afternoon, I need to reschedule your appointment. Instead of meeting at 2:00 p.m., we''ll meet at 4:00 p.m. in Room 314 as originally planned. If this revised time creates any conflicts with your schedule, please contact me at your earliest convenience so that we can discuss alternative arrangements.","questions":[{"id":"read12_m2_q13","type":"multiple_choice","prompt":"What is the main purpose of the message?","options":{"A":"To explain changes to a classroom location.","B":"To notify a student about a scheduling change.","C":"To provide details about an upcoming workshop.","D":"To introduce a new tutoring program."},"correct_answer":"B","explanation":"Gia sư gửi tin nhắn để thông báo về việc dời buổi học phụ đạo sang một khung giờ khác do có lịch đột xuất."},{"id":"read12_m2_q14","type":"multiple_choice","prompt":"What does the tutor ask the student to do if the new arrangement is unsuitable?","options":{"A":"Contact the department office to request a different room.","B":"Attend the session remotely instead.","C":"Contact the tutor to discuss other possible options.","D":"Arrive earlier and wait until the tutor is available."},"correct_answer":"C","explanation":"Sinh viên được yêu cầu chuẩn bị trước các câu hỏi và bài tập chưa hiểu để buổi học diễn ra hiệu quả hơn."},{"id":"read12_m2_q15","type":"multiple_choice","prompt":"What can be inferred from the message?","options":{"A":"The tutor expects the workshop to end before 4:00 p.m.","B":"The meeting will take place online instead of in person.","C":"The student previously requested a different appointment time.","D":"The tutor will be unavailable for the rest of the week."},"correct_answer":"A","explanation":"Buổi học bù sẽ được tổ chức qua phòng học trực tuyến nếu sinh viên không thể đến gặp trực tiếp."}]}},{"id":"read12_m2_t4","title":"Task 4: Academic Reading (Collective Memory and Social Identity)","task_type":"read_academic","content":{"academic_area":"Sociology / Social Psychology","passage":"Collective memory refers to the shared understanding of the past held by a group, community, or society. Unlike individual memory, which is based on personal experiences, collective memory is shaped through stories, traditions, education, and public commemorations. Historical events that become part of a society''s collective memory often influence how people understand their identity and their relationship to others. The formation of collective memory is not always a straightforward process. Different groups may remember the same event in different ways depending on their experiences and perspectives. Governments, educational institutions, and media organizations can also play a role in determining which events receive greater attention and how they are interpreted. As a result, collective memory is often selective rather than completely objective. Despite these limitations, collective memory serves important social functions. Shared memories can strengthen social bonds and provide communities with a sense of continuity across generations. At the same time, disagreements about historical events may lead to debates about how the past should be represented. Consequently, collective memory is best understood not as a perfect record of history but as an evolving interpretation of it.","questions":[{"id":"read12_m2_q16","type":"multiple_choice","prompt":"Which of the following best states the main idea of the passage?","options":{"A":"Collective memory is an inaccurate form of historical record.","B":"Governments control all public understanding of history.","C":"Collective memory influences societies and is shaped by multiple factors.","D":"Historical events are generally remembered in the same way by all groups."},"correct_answer":"C","explanation":"Ý chính của bài đọc: Ký ức tập thể là sự chia sẻ và ghi nhớ chung về quá khứ của một cộng đồng, định hình nên bản sắc xã hội của họ."},{"id":"read12_m2_q17","type":"multiple_choice","prompt":"The word \"continuity\" in the passage is closest in meaning to","options":{"A":"conflict","B":"stability","C":"uncertainty","D":"separation"},"correct_answer":"B","explanation":"Từ \"transmitted\" nghĩa là truyền đạt, lưu truyền qua nhiều thế hệ (\"passed down\" / \"communicated\")."},{"id":"read12_m2_q18","type":"multiple_choice","prompt":"According to the passage, all of the following influence collective memory EXCEPT","options":{"A":"education","B":"public commemorations","C":"media organizations","D":"genetic inheritance"},"correct_answer":"D","explanation":"Các di tích, lễ kỷ niệm và viện bảo tàng đóng vai trò duy trì và tái hiện ký ức tập thể trong ý thức cộng đồng."},{"id":"read12_m2_q19","type":"multiple_choice","prompt":"What is the relationship between paragraphs 2 and 3?","options":{"A":"Paragraph 3 discusses ways of eliminating the limitations described in paragraph 2 and shows the result it can lead to.","B":"Paragraph 3 contradicts the claim made in paragraph 2.","C":"Paragraph 3 explains the historical origins of the issues discussed in paragraph 2.","D":"Paragraph 3 acknowledges the limitations described in paragraph 2 and discusses the functions of the same concept."},"correct_answer":"D","explanation":"Ký ức tập thể có thể được chọn lọc và diễn giải lại theo thời gian nhằm phục vụ các mục tiêu gắn kết xã hội hiện tại."},{"id":"read12_m2_q20","type":"multiple_choice","prompt":"Which of the following best expresses the essential information in the following sentence? Consequently, collective memory is best understood not as a perfect record of history but as an evolving interpretation of it.","options":{"A":"Collective memory provides a completely accurate account of historical events.","B":"Collective memory changes over time and reflects how people interpret the past.","C":"Collective memory becomes less important as societies develop.","D":"Collective memory is based entirely on personal experiences rather than shared events."},"correct_answer":"B","explanation":"Ký ức tập thể khác với ký ức cá nhân ở chỗ nó phản ánh quan điểm chung được chia sẻ rộng rãi trong một nhóm xã hội."}]}}]}],"description":"Bộ đề TOEFL iBT 2026 Multistage Adaptive (YouTube Practice 11 - Trùng đề Practice 10): Module 1 (Healthy Eating, Campus Cafeteria, Shipping Update, Cultural Diffusion) & Module 2 (Public Transit, Travel Blog, Tutor Message, Collective Memory).","created_at_ms":1791231607965}'::jsonb,
  timezone('utc'::text, now())
)
ON CONFLICT (id) DO UPDATE SET
  title = EXCLUDED.title,
  skill = EXCLUDED.skill,
  task_type = EXCLUDED.task_type,
  duration_seconds = EXCLUDED.duration_seconds,
  content = EXCLUDED.content;

INSERT INTO public.tests (id, title, skill, task_type, duration_seconds, content, created_at)
VALUES (
  'reading-practice-13',
  'Reading Practice Test 13 (TOEFL 2026 - Technology Innovation & Citizen Science)',
  'reading',
  'multistage',
  1800,
  '{"stages":[{"id":"read13_stage_1","title":"Reading - Module 1 (Stage 1)","duration_seconds":900,"description":"Module 1 gồm 4 phần (20 câu hỏi). Hãy hoàn thành trước khi hết 15 phút.","tasks":[{"id":"read13_m1_t1","title":"Task 1: Complete the Words (Đoạn 1 - Technological Innovation)","task_type":"complete_words","content":{"instructions":"Điền các chữ cái còn thiếu vào vị trí dấu gạch dưới `_` trong đoạn văn sau:","paragraph":"Technological innovation drives progress across industries by introducing new tools and methods for solving problems. Advan[ces] in techn[ology] improve effic[iency], communication, a[nd] access t[o] information. Ho[wever], rapid inno[vation] can al[so] create ethi[cal], social, and econ[omic] challenges that must be addressed. Societies must balance the benefits of technology with responsible use and regulation. Innovation continues to transform the way people live and work. Adapting to technological change is essential for success in the modern world.","blanks":[{"id":"read13_m1_t1_b1","prefix":"Advan","missing":"ces","full":"Advances"},{"id":"read13_m1_t1_b2","prefix":"techn","missing":"ology","full":"technology"},{"id":"read13_m1_t1_b3","prefix":"effic","missing":"iency","full":"efficiency"},{"id":"read13_m1_t1_b4","prefix":"a","missing":"nd","full":"and"},{"id":"read13_m1_t1_b5","prefix":"t","missing":"o","full":"to"},{"id":"read13_m1_t1_b6","prefix":"Ho","missing":"wever","full":"However"},{"id":"read13_m1_t1_b7","prefix":"inno","missing":"vation","full":"innovation"},{"id":"read13_m1_t1_b8","prefix":"al","missing":"so","full":"also"},{"id":"read13_m1_t1_b9","prefix":"ethi","missing":"cal","full":"ethical"},{"id":"read13_m1_t1_b10","prefix":"econ","missing":"omic","full":"economic"}]}},{"id":"read13_m1_t2","title":"Task 2: Read a Fitness App Notification (Daily Walking Goal)","task_type":"read_daily_life","content":{"document_type":"Fitness App Notice","passage":"You reached your weekly goal by walking 10,000 steps each day. Great job staying active! To help you keep improving, the app recommends trying one of its guided walking routes. These routes include audio tips to help you maintain good posture and stay motivated. You can also join a walking challenge with friends to make exercising more enjoyable and stay on track.","questions":[{"id":"read13_m1_q11","type":"multiple_choice","prompt":"What goal did the user accomplish?","options":{"A":"Completing a meditation program","B":"Improving their sleep habits","C":"Meeting a daily walking target","D":"Finishing a running competition"},"correct_answer":"C","explanation":"Người dùng đã hoàn thành mục tiêu đi bộ hàng ngày (\"Meeting a daily walking target\")."},{"id":"read13_m1_q12","type":"multiple_choice","prompt":"What does the app recommend doing next?","options":{"A":"Following one of its guided walks","B":"Taking a break from exercise","C":"Replacing walking with another activity","D":"Turning off app reminders"},"correct_answer":"A","explanation":"Ứng dụng đề xuất bước tiếp theo là tham gia một trong các lộ trình đi bộ có hướng dẫn (\"Following one of its guided walks\")."}]}},{"id":"read13_m1_t3","title":"Task 3: Read a Weather Advisory (Extreme Heat Alert)","task_type":"read_daily_life","content":{"document_type":"Municipal Weather Bulletin","passage":"The city issued a heat advisory for the next three days because temperatures are expected to rise above 380C. Residents are encouraged to stay hydrated, avoid spending long periods in direct sunlight, and check on elderly neighbors who may be more sensitive to extreme heat. Cooling centers will be open across the city for anyone who needs a cool place to stay during the hottest part of the day.","questions":[{"id":"read13_m1_q13","type":"multiple_choice","prompt":"Why did the city issue the heat advisory?","options":{"A":"A snowstorm is likely to affect the area.","B":"Heavy rain is expected over the next few days.","C":"Strong winds may cause power outages.","D":"Temperatures are expected to become extremely high."},"correct_answer":"D","explanation":"Thành phố phát thông báo vì nhiệt độ dự kiến sẽ tăng cao kỷ lục (\"Temperatures are expected to become extremely high\")."},{"id":"read13_m1_q14","type":"multiple_choice","prompt":"Who should residents pay special attention to?","options":{"A":"Tourists visiting the city for the first time.","B":"Elderly people who may be affected by the heat.","C":"Teachers working in local schools.","D":"Teenagers spending time outdoors."},"correct_answer":"B","explanation":"Cư dân cần đặc biệt chú ý đến người cao tuổi, đối tượng dễ bị ảnh hưởng nghiêm trọng bởi nắng nóng (\"Elderly people who may be affected by the heat\")."},{"id":"read13_m1_q15","type":"multiple_choice","prompt":"What is the purpose of the cooling centers?","options":{"A":"To distribute free drinking water to all residents.","B":"To provide emergency medical assistance for heat-related illnesses.","C":"To provide a cool place for people during the heat.","D":"To give weather updates and emergency supplies."},"correct_answer":"C","explanation":"Các trung tâm làm mát mở cửa để cung cấp nơi nghỉ ngơi tránh nóng an toàn cho người dân (\"To provide a cool place for people during the heat\")."}]}},{"id":"read13_m1_t4","title":"Task 4: Academic Reading (The Development of Writing Systems)","task_type":"read_academic","content":{"academic_area":"Linguistics / World History","passage":"Writing systems are among the most significant innovations in human history. Before the development of writing, information was transmitted primarily through speech and memory. While oral traditions could preserve knowledge across generations, they were limited by the capacity of individuals to remember and accurately reproduce information. The invention of writing allowed societies to record laws, economic transactions, historical events, and religious beliefs in a more permanent form. Early writing systems emerged independently in several regions of the world. Some of the earliest examples developed in connection with administrative and commercial activities. As societies became larger and more complex, the need to keep records increased. Over time, writing systems evolved from relatively simple symbols into more sophisticated forms capable of representing spoken language with greater precision. The spread of writing had profound social and cultural consequences. Written records made it possible to preserve knowledge across long periods and large distances. They also facilitated the development of literature, science, and government institutions. Although literacy remained limited in many societies for centuries, the gradual expansion of education increased access to written communication. Today, writing continues to play a central role in preserving and transmitting information.","questions":[{"id":"read13_m1_q16","type":"multiple_choice","prompt":"The word \"transmitted\" in the passage is closest in meaning to","options":{"A":"created","B":"communicated","C":"discovered","D":"restricted"},"correct_answer":"B","explanation":"Từ \"transmitted\" trong ngữ cảnh truyền đạt thông tin đồng nghĩa với \"communicated\" (được truyền tải)."},{"id":"read13_m1_q17","type":"multiple_choice","prompt":"According to the passage, what was one limitation of oral traditions?","options":{"A":"They could not preserve knowledge at all.","B":"They depended on people''s ability to remember information accurately.","C":"They were used only for religious purposes.","D":"They prevented societies from growing."},"correct_answer":"B","explanation":"Hạn chế của truyền miệng là phụ thuộc hoàn toàn vào trí nhớ chính xác của con người (\"They depended on people''s ability to remember information accurately\")."},{"id":"read13_m1_q18","type":"multiple_choice","prompt":"''As societies became larger and more complex, the need to keep records increased.\"","options":{"A":"Record-keeping became less important as societies developed.","B":"Larger societies often eliminated administrative systems.","C":"Growing social complexity increased the demand for written records.","D":"Complex societies preferred oral communication."},"correct_answer":"C","explanation":"Ý tương đương với câu gốc: Sự phức tạp ngày càng tăng của xã hội làm tăng nhu cầu lưu trữ hồ sơ bằng chữ viết (\"Growing social complexity increased the demand for written records\")."},{"id":"read13_m1_q19","type":"multiple_choice","prompt":"How does the third paragraph relate to the first paragraph?","options":{"A":"It describes the long-term effects of a development introduced in the first paragraph.","B":"It contradicts the argument made in the first paragraph.","C":"It focuses on a different topic unrelated to writing.","D":"It explains why writing systems disappeared."},"correct_answer":"A","explanation":"Đoạn 3 mô tả những tác động lâu dài của chữ viết (được giới thiệu ở đoạn 1) đối với luật pháp, quản trị và văn hóa."},{"id":"read13_m1_q20","type":"multiple_choice","prompt":"According to the passage, all of the following are true EXCEPT","options":{"A":"Writing helped preserve laws and historical information.","B":"Early writing systems were connected to administrative needs.","C":"Literacy became universal immediately after writing was invented.","D":"Writing contributed to the development of science and literature."},"correct_answer":"C","explanation":"Khẳng định sai là \"Tỷ lệ biết chữ trở nên phổ quát ngay sau khi chữ viết được phát minh\" (thực tế ban đầu chỉ có giới tinh hoa và thư lại biết chữ)."}]}}]},{"id":"read13_stage_2","title":"Reading - Module 2 (Stage 2 - HARD)","duration_seconds":900,"description":"Module 2 gồm 4 phần (20 câu hỏi). Hãy hoàn thành trước khi hết 15 phút.","tasks":[{"id":"read13_m2_t1","title":"Task 1: Complete the Words (Đoạn 2 - Volunteering)","task_type":"complete_words","content":{"instructions":"Điền các chữ cái còn thiếu vào vị trí dấu gạch dưới `_` trong đoạn văn sau:","paragraph":"Volunteering provides individuals with meaningful opportunities to support their communities and contribute to social well-being. Volunt[eers] offer the[ir] time, ene[rgy], and ski[lls] to add[ress] social nee[ds] without expec[ting] financial rew[ard]. Through thi[s] involvement, th[ey] develop empathy, cooperation, and a stronger sense of civic responsibility. Communities benefit from additional support, fresh perspectives, and increased social cohesion. Volunteering can also help individuals gain practical experience, strengthen leadership abilities, and expand professional networks. In the long term, active civic participation promotes solidarity and encourages sustainable social progress.","blanks":[{"id":"read13_m2_t1_b1","prefix":"Volunt","missing":"eers","full":"Volunteers"},{"id":"read13_m2_t1_b2","prefix":"the","missing":"ir","full":"their"},{"id":"read13_m2_t1_b3","prefix":"ene","missing":"rgy","full":"energy"},{"id":"read13_m2_t1_b4","prefix":"ski","missing":"lls","full":"skills"},{"id":"read13_m2_t1_b5","prefix":"add","missing":"ress","full":"address"},{"id":"read13_m2_t1_b6","prefix":"nee","missing":"ds","full":"needs"},{"id":"read13_m2_t1_b7","prefix":"expec","missing":"ting","full":"expecting"},{"id":"read13_m2_t1_b8","prefix":"rew","missing":"ard","full":"reward"},{"id":"read13_m2_t1_b9","prefix":"thi","missing":"s","full":"this"},{"id":"read13_m2_t1_b10","prefix":"th","missing":"ey","full":"they"}]}},{"id":"read13_m2_t2","title":"Task 2: Read an Apartment Rental Review (Tenant Experience)","task_type":"read_daily_life","content":{"document_type":"Apartment Rental Review","passage":"I rented this apartment for just over a year, and despite a few drawbacks, I would recommend it. The neighborhood is one of its biggest advantages, with grocery stores, public transportation, and several parks all within walking distance. The building itself is fairly old, and the heating system occasionally made loud noises during winter nights. Fortunately, the landlord was consistently responsive and arranged repairs promptly whenever issues came up, so the inconvenience never became a serious problem.","questions":[{"id":"read13_m2_q11","type":"multiple_choice","prompt":"Which statement best describes the reviewer''s overall opinion?","options":{"A":"The apartment was only suitable for short-term stays.","B":"The apartment was disappointing overall.","C":"The landlord made the apartment difficult to live in.","D":"The positive aspects outweighed the problems."},"correct_answer":"D","explanation":"Ý kiến chung của người đánh giá: Những khía cạnh tích cực vượt trội hơn các vấn đề nhỏ gặp phải (\"The positive aspects outweighed the problems\")."},{"id":"read13_m2_q12","type":"multiple_choice","prompt":"Why did the heating problem not become a major issue?","options":{"A":"The landlord addressed maintenance requests quickly.","B":"Winter temperatures were unusually mild.","C":"The tenant became accustomed to the noise.","D":"The heating system was eventually replaced."},"correct_answer":"A","explanation":"Vấn đề sưởi ấm không trở nên nghiêm trọng vì chủ nhà xử lý các yêu cầu bảo trì rất nhanh chóng (\"The landlord addressed maintenance requests quickly\")."}]}},{"id":"read13_m2_t3","title":"Task 3: Read an Email (Job Interview Invitation)","task_type":"read_daily_life","content":{"document_type":"Job Interview Email","passage":"Dear Sofia, Thank you for applying for the Library Assistant position. We were impressed by your application and would like to invite you to an interview on Friday at 1:00 p.m. in Room 207 of the Student Services Building. Please bring a copy of your class schedule, as we will discuss your weekly availability. The interview is expected to last approximately 30 minutes. If you are unable to attend, please let us know at least 24 hours in advance so we can arrange an alternative time. We look forward to meeting you.","questions":[{"id":"read13_m2_q13","type":"multiple_choice","prompt":"What is the main purpose of the email?","options":{"A":"To request additional application materials.","B":"To announce a change in the job requirements.","C":"To invite the applicant to an interview.","D":"To offer the applicant a job immediately."},"correct_answer":"C","explanation":"Mục đích chính của email là mời ứng viên tham gia buổi phỏng vấn tuyển dụng (\"To invite the applicant to an interview\")."},{"id":"read13_m2_q14","type":"multiple_choice","prompt":"What should the applicant do if they cannot attend?","options":{"A":"Submit a new application.","B":"Visit the office without an appointment.","C":"Find another applicant to take their place.","D":"Contact the employer at least one day beforehand."},"correct_answer":"D","explanation":"Ứng viên nếu không thể tham dự cần thông báo trước ít nhất một ngày (\"Contact the employer at least one day beforehand\")."},{"id":"read13_m2_q15","type":"multiple_choice","prompt":"What can be inferred about the applicant?","options":{"A":"They have already accepted the position.","B":"They successfully passed the first stage of the selection process.","C":"They are required to begin work the following week.","D":"They have previously worked at the library."},"correct_answer":"B","explanation":"Có thể suy ra ứng viên đã vượt qua vòng hồ sơ ban đầu để được lựa chọn vào vòng phỏng vấn (\"They successfully passed the first stage of the selection process\")."}]}},{"id":"read13_m2_t4","title":"Task 4: Academic Reading (Citizen Science)","task_type":"read_academic","content":{"academic_area":"Environmental Science / Research Methodology","passage":"Citizen science refers to scientific research that involves participation by members of the general public. Rather than being conducted exclusively by professional researchers, some projects invite volunteers to collect data, make observations, or assist with analysis. As a result, scientists can gather information on a scale that would otherwise be difficult to achieve. Many citizen science projects focus on environmental monitoring. Volunteers may record bird migrations, track local weather conditions, or document changes in plant populations. Because participants are often distributed across large geographic areas, they can provide valuable information from locations that researchers may not be able to visit regularly. As technology has become more accessible, smartphone applications and online databases have made it easier for volunteers to submit observations quickly and accurately. Despite its advantages, citizen science also presents challenges. Participants may vary in experience, which can affect data quality. To address this issue, many projects provide training materials and standardized procedures. Researchers may also verify submitted information before incorporating it into larger studies. When carefully designed, citizen science projects can benefit both researchers and participants by expanding scientific knowledge while increasing public engagement with science.","questions":[{"id":"read13_m2_q16","type":"multiple_choice","prompt":"What is the main idea of the passage?","options":{"A":"Citizen science allows the public to contribute to research while creating both opportunities and challenges.","B":"Professional scientists rarely conduct research independently.","C":"Environmental monitoring is the only useful form of scientific research.","D":"Technology has replaced the need for scientific training."},"correct_answer":"A","explanation":"Ý chính: Khoa học công dân cho phép cộng đồng đóng góp vào nghiên cứu, vừa tạo ra cơ hội lớn vừa kèm theo thách thức về kiểm soát chất lượng."},{"id":"read13_m2_q17","type":"multiple_choice","prompt":"The word \"incorporating\" in the passage is closest in meaning to","options":{"A":"rejecting","B":"measuring","C":"including","D":"locating"},"correct_answer":"C","explanation":"Từ \"incorporating\" mang nghĩa bao gồm, kết hợp (\"including\")."},{"id":"read13_m2_q18","type":"multiple_choice","prompt":"Why does the author mention smartphone applications and online databases?","options":{"A":"To argue that traditional research methods are ineffective.","B":"To provide examples of technologies that support citizen science.","C":"To compare different forms of environmental monitoring.","D":"To explain why data quality has declined."},"correct_answer":"B","explanation":"Tác giả nhắc đến ứng dụng điện thoại và cơ sở dữ liệu trực tuyến như ví dụ về các công nghệ hỗ trợ khoa học công dân thu thập dữ liệu diện rộng."},{"id":"read13_m2_q19","type":"multiple_choice","prompt":"What can be inferred about citizen science projects?","options":{"A":"They are effective only when participants have scientific degrees.","B":"Information collected by volunteers does not require verification.","C":"Careful organization can help reduce some limitations of citizen science.","D":"Researchers usually prefer not to involve the public in scientific studies."},"correct_answer":"C","explanation":"Tổ chức cẩn thận và hướng dẫn bài bản có thể giảm thiểu những sai sót và hạn chế trong các dự án khoa học công dân."},{"id":"read13_m2_q20","type":"multiple_choice","prompt":"Where would the following sentence best fit: \"This type of collaboration allows researchers to benefit from the efforts of many individuals outside traditional scientific institutions.\"?","options":{"A":"Location A","B":"Location B","C":"Location C","D":"Location D"},"correct_answer":"C","explanation":"Vị trí [C] là vị trí phù hợp nhất để chèn câu mô tả sự hợp tác này mang lại lợi ích cho các nhà nghiên cứu từ nỗ lực của cộng đồng."}]}}]}],"description":"Bộ đề TOEFL iBT 2026 Multistage Adaptive (YouTube Practice 12): Module 1 (Technological Innovation, Fitness App, Weather Advisory, Writing Systems) & Module 2 (Volunteering, Apartment Review, Library Announcement, Citizen Science).","created_at_ms":1791231607965}'::jsonb,
  timezone('utc'::text, now())
)
