  duration_seconds = EXCLUDED.duration_seconds,
  content = EXCLUDED.content;

INSERT INTO public.tests (id, title, skill, task_type, duration_seconds, content, created_at)
VALUES (
  'reading-practice-14',
  'Reading Practice Test 14 (TOEFL 2026 - Digital Literacy & Ecological Succession)',
  'reading',
  'multistage',
  1800,
  '{"stages":[{"id":"read14_stage_1","title":"Reading - Module 1 (Stage 1)","duration_seconds":900,"description":"Module 1 gồm 4 phần (20 câu hỏi). Hãy hoàn thành trước khi hết 15 phút.","tasks":[{"id":"read14_m1_t1","title":"Task 1: Complete the Words (Đoạn 1 - Digital Literacy)","task_type":"complete_words","content":{"instructions":"Điền các chữ cái còn thiếu vào vị trí dấu gạch dưới `_` trong đoạn văn sau:","paragraph":"Digital literacy is the ability to use technology effectively, safely, and responsibly in various contexts. It inclu[des] evaluating t[he] credibility of onl[ine] information, prote[cting] personal da[ta], and communi[cating] appropriately in dig[ital] environments. A[s] technology beco[mes] deeply integr[ated] into education, work, and social interaction, digital literacy is increasingly essential. Schools and universities emphasize these skills to prepare students for modern challenges. Individuals with strong digital literacy can use technological tools productively while minimizing risks such as misinformation, cybercrime, and privacy violations.","blanks":[{"id":"read14_m1_t1_b1","prefix":"inclu","missing":"des","full":"includes"},{"id":"read14_m1_t1_b2","prefix":"t","missing":"he","full":"the"},{"id":"read14_m1_t1_b3","prefix":"onl","missing":"ine","full":"online"},{"id":"read14_m1_t1_b4","prefix":"prote","missing":"cting","full":"protecting"},{"id":"read14_m1_t1_b5","prefix":"da","missing":"ta","full":"data"},{"id":"read14_m1_t1_b6","prefix":"communi","missing":"cating","full":"communicating"},{"id":"read14_m1_t1_b7","prefix":"dig","missing":"ital","full":"digital"},{"id":"read14_m1_t1_b8","prefix":"A","missing":"s","full":"As"},{"id":"read14_m1_t1_b9","prefix":"beco","missing":"mes","full":"becomes"},{"id":"read14_m1_t1_b10","prefix":"integr","missing":"ated","full":"integrated"}]}},{"id":"read14_m1_t2","title":"Task 2: Read a Notice (Campus Conversation Club)","task_type":"read_daily_life","content":{"document_type":"Campus Club Notice","passage":"The Language Center''s conversation club meets every Wednesday from 4:30 to 5:45 p.m. The club is open to all students who are currently enrolled at the university. To attend a particular week''s session, students must register online by noon on Monday. Each meeting focuses on a different topic, which is announced on the center''s website every Friday. This gives students time to check the topic and decide whether they want to attend.","questions":[{"id":"read14_m1_q11","type":"multiple_choice","prompt":"Who can participate in the conversation club?","options":{"A":"Only advanced-level students","B":"All currently enrolled students","C":"Students who register after Wednesday","D":"Only students taking a specific language course"},"correct_answer":"B","explanation":"Tất cả sinh viên đang theo học đều có thể tham gia câu lạc bộ trò chuyện ngoại ngữ (\"All currently enrolled students\")."},{"id":"read14_m1_q12","type":"multiple_choice","prompt":"Why might students check the center''s website before registering?","options":{"A":"To find out what will be discussed at the next session","B":"To see whether they qualify for advanced language courses","C":"To change the time of the weekly conversation club","D":"To find out which instructor will lead the entire program"},"correct_answer":"A","explanation":"Sinh viên nên kiểm tra trang web trước để nắm được chủ đề thảo luận của buổi sinh hoạt tiếp theo (\"To find out what will be discussed at the next session\")."}]}},{"id":"read14_m1_t3","title":"Task 3: Read a Policy Update (Remote Work Policy)","task_type":"read_daily_life","content":{"document_type":"HR Remote Work Policy","passage":"Starting September 1, employees who want to work from home more than two days per week must submit a request through the WorkFlex portal at least ten business days in advance. Requests must include their preferred workdays and confirmation of a suitable workspace. Managers will review requests within five business days. Employees with already approved remote schedules only need to submit a new request if they want to change their current arrangement. Emergency requests may be sent directly to a supervisor.","questions":[{"id":"read14_m1_q13","type":"multiple_choice","prompt":"What is the main purpose of the announcement?","options":{"A":"To ask employees to work from home more often","B":"To explain why the company is ending remote work","C":"To introduce a new procedure for requesting regular remote work","D":"To announce changes to employees'' working hours"},"correct_answer":"C","explanation":"Mục đích của thông báo là giới thiệu quy trình mới để đăng ký làm việc từ xa định kỳ (\"To introduce a new procedure for requesting regular remote work\")."},{"id":"read14_m1_q14","type":"multiple_choice","prompt":"Which employees must submit a request through the WorkFlex portal?","options":{"A":"Employees who want to work remotely at least three days per week","B":"Employees with already approved remote schedules","C":"Employees requesting emergency remote work","D":"Employees who work in the office every day"},"correct_answer":"A","explanation":"Nhân viên muốn làm việc từ xa ít nhất ba ngày mỗi tuần phải nộp đơn qua cổng WorkFlex (\"Employees who want to work remotely at least three days per week\")."},{"id":"read14_m1_q15","type":"multiple_choice","prompt":"What should an employee do if they already have an approved remote schedule?","options":{"A":"Submit a new request before September 1","B":"Change their schedule through the WorkFlex portal","C":"Submit a new request only if they want to make changes","D":"Send their schedule directly to Human Resources"},"correct_answer":"C","explanation":"Nhân viên đã có lịch làm việc từ xa được duyệt chỉ cần nộp đơn mới nếu muốn thay đổi lịch (\"Submit a new request only if they want to make changes\")."}]}},{"id":"read14_m1_t4","title":"Task 4: Academic Reading (The Placebo Effect)","task_type":"read_academic","content":{"academic_area":"Medicine / Health Sciences","passage":"The placebo effect occurs when a person experiences a change in their condition after receiving a treatment that does not contain an active ingredient intended to produce that change. Expectations about a treatment can influence how people perceive symptoms and evaluate their health. For example, someone who believes a pill will reduce discomfort may feel better even when the pill contains no medication that directly treats the problem. The placebo effect is important in medical research because scientists need to determine whether a treatment produces benefits beyond those caused by expectations. In clinical trials, researchers may give one group an active treatment and another group a placebo. If both groups improve by similar amounts, researchers may question whether the treatment itself caused the improvement. Placebo-controlled studies therefore help researchers evaluate the actual effects of medical treatments. The effect does not mean that people''s symptoms are imaginary. Expectations can influence experiences such as the perception of pain. However, the strength of the placebo effect can vary depending on the individual, the condition, and how the treatment is presented. Understanding this phenomenon helps researchers design more reliable studies and explains how expectations can influence people''s experiences of treatment.","questions":[{"id":"read14_m1_q16","type":"multiple_choice","prompt":"What is the main idea of the passage?","options":{"A":"Medical treatments are generally less effective than expected.","B":"The placebo effect shows how expectations can affect treatment experiences.","C":"People should use placebos instead of medical treatments.","D":"Clinical trials are unnecessary when patients report feeling better."},"correct_answer":"B","explanation":"Ý chính của bài đọc: Hiệu ứng giả dược cho thấy kỳ vọng và niềm tin tâm lý có thể tác động trực tiếp đến trải nghiệm điều trị của bệnh nhân."},{"id":"read14_m1_q17","type":"multiple_choice","prompt":"The word \"active\" in the passage is closest in meaning to","options":{"A":"containing an active ingredient","B":"requiring physical movement","C":"involving many participants","D":"producing immediate results"},"correct_answer":"A","explanation":"Từ \"active\" trong ngữ cảnh dược lý có nghĩa là chứa hoạt chất điều trị thực sự (\"containing an active ingredient\")."},{"id":"read14_m1_q18","type":"multiple_choice","prompt":"Why does the author mention clinical trials?","options":{"A":"To explain how researchers separate treatment effects from expectations.","B":"To show that some patients prefer inactive treatments.","C":"To explain why some medical studies are conducted without participants.","D":"To argue that patients should not trust medical researchers."},"correct_answer":"A","explanation":"Tác giả nhắc đến các thử nghiệm lâm sàng đối chứng để giải thích cách nhà khoa học phân tách tác dụng thực của thuốc khỏi tác động tâm lý."},{"id":"read14_m1_q19","type":"multiple_choice","prompt":"What can be inferred about placebo- controlled studies?","options":{"A":"Improvement in both groups does not prove the treatment caused it.","B":"They prevent expectations from affecting participants.","C":"They are used only when treatments have no active ingredients.","D":"They always produce identical results for both groups."},"correct_answer":"A","explanation":"Việc cải thiện ở cả hai nhóm không chứng minh bản thân phương pháp điều trị là nguyên nhân duy nhất dẫn đến sự thuyên giảm."},{"id":"read14_m1_q20","type":"multiple_choice","prompt":"According to the passage, all of the following are true EXCEPT","options":{"A":"Expectations can affect how people experience symptoms.","B":"Placebo-controlled studies can help evaluate medical treatments.","C":"The placebo effect means that reported symptoms are not real.","D":"The strength of the placebo effect can vary among individuals."},"correct_answer":"C","explanation":"Khẳng định sai là \"Hiệu ứng giả dược có nghĩa là các triệu chứng được báo cáo không có thật\" (triệu chứng và sự thuyên giảm tâm sinh lý đều có thật)."}]}}]},{"id":"read14_stage_2","title":"Reading - Module 2 (Stage 2 - HARD)","duration_seconds":900,"description":"Module 2 gồm 4 phần (20 câu hỏi). Hãy hoàn thành trước khi hết 15 phút.","tasks":[{"id":"read14_m2_t1","title":"Task 1: Complete the Words (Đoạn 2 - Work-Life Balance)","task_type":"complete_words","content":{"instructions":"Điền các chữ cái còn thiếu vào vị trí dấu gạch dưới `_` trong đoạn văn sau:","paragraph":"Work-life balance refers to managing professional responsibilities and personal life in a healthy, sustainable manner. When indivi[duals] focus excess[ively] on wo[rk], they m[ay] experience stre[ss], fatigue, and burn[out], which redu[ce] overall well-be[ing]. Establishing cle[ar] boundaries and sched[uling] regular personal time allows people to rest and maintain long-term motivation. Many employers now recognize that balanced employees demonstrate greater productivity, creativity, and job satisfaction. Achieving work-life balance not only protects mental and physical health but also contributes to sustained professional growth and personal fulfillment.","blanks":[{"id":"read14_m2_t1_b1","prefix":"indivi","missing":"duals","full":"individuals"},{"id":"read14_m2_t1_b2","prefix":"excess","missing":"ively","full":"excessively"},{"id":"read14_m2_t1_b3","prefix":"wo","missing":"rk","full":"work"},{"id":"read14_m2_t1_b4","prefix":"m","missing":"ay","full":"may"},{"id":"read14_m2_t1_b5","prefix":"stre","missing":"ss","full":"stress"},{"id":"read14_m2_t1_b6","prefix":"burn","missing":"out","full":"burnout"},{"id":"read14_m2_t1_b7","prefix":"redu","missing":"ce","full":"reduce"},{"id":"read14_m2_t1_b8","prefix":"well-be","missing":"ing","full":"well-being"},{"id":"read14_m2_t1_b9","prefix":"cle","missing":"ar","full":"clear"},{"id":"read14_m2_t1_b10","prefix":"sched","missing":"uling","full":"scheduling"}]}},{"id":"read14_m2_t2","title":"Task 2: Read a Sign (Visitor Parking Guidelines)","task_type":"read_daily_life","content":{"document_type":"Campus Parking Notice","passage":"Visitor parking is available Monday through Friday from 7:00 a.m. to 6:00 p.m. Employees may park in the main lot using their assigned parking permits, which must be displayed on their vehicles at all times. Visitors who need to park on company property must register their vehicles at the front desk before entering the parking area. They will receive a temporary parking pass that must be placed on the dashboard. Visitor parking is limited to a maximum of three hours, and spaces are available on a first-come, first-served basis. Visitor parking is not available on weekends or public holidays.","questions":[{"id":"read14_m2_q11","type":"multiple_choice","prompt":"What must visitors do before parking?","options":{"A":"Request an employee parking permit","B":"Reserve a space one week in advance","C":"Park only after 6:00 p.m.","D":"Register their vehicles at the front desk"},"correct_answer":"D","explanation":"Khách đến thăm phải đăng ký phương tiện tại quầy lễ tân trước khi đỗ xe (\"Register their vehicles at the front desk\")."},{"id":"read14_m2_q12","type":"multiple_choice","prompt":"Why must visitors place the temporary parking pass on the dashboard?","options":{"A":"So parking staff can identify authorized visitor vehicles","B":"So employees can book the parking space in advance","C":"So visitors can extend their parking time","D":"So the front desk can clean the visitor''s vehicle"},"correct_answer":"A","explanation":"Khách phải đặt thẻ đỗ xe tạm thời trên bảng điều khiển để nhân viên bãi xe nhận diện xe hợp lệ (\"So parking staff can identify authorized visitor vehicles\")."}]}},{"id":"read14_m2_t3","title":"Task 3: Read an Update (Assignment Extension Notice)","task_type":"read_daily_life","content":{"document_type":"Course Technical Announcement","passage":"Your assignment due date has been extended from Wednesday to Friday to give students more time to complete the final section. Several students reported technical difficulties when uploading their files, and the university''s technical team is currently working to resolve the problem. If the platform continues to show an error, students may submit their completed assignment by email instead. However, students should make sure their file is attached correctly and use their university email account when sending it.","questions":[{"id":"read14_m2_q13","type":"multiple_choice","prompt":"Why was the due date extended?","options":{"A":"The earlier deadline wasn''t realistic","B":"The instructor will be traveling","C":"Students experienced technical problems","D":"Fewer students than expected completed the assignment"},"correct_answer":"C","explanation":"Hạn nộp bài tập được gia hạn vì hệ thống gặp sự cố kỹ thuật khiến nhiều sinh viên không tải bài lên được (\"Students experienced technical problems\")."},{"id":"read14_m2_q14","type":"multiple_choice","prompt":"What should students do when submitting the assignment by email?","options":{"A":"Send it from a personal email account","B":"Attach the file and use their university email account","C":"Contact the technical team before sending the file","D":"Submit a printed copy to the instructor"},"correct_answer":"B","explanation":"Khi gửi bài qua email dự phòng, sinh viên cần đính kèm tệp và sử dụng tài khoản email của trường (\"Attach the file and use their university email account\")."},{"id":"read14_m2_q15","type":"multiple_choice","prompt":"What can be inferred about students whose assignments were successfully uploaded?","options":{"A":"They must submit their assignments again by email","B":"They do not need to use the alternative email method","C":"They will receive additional time to complete another assignment","D":"They must contact the technical team to confirm their submission"},"correct_answer":"B","explanation":"Sinh viên đã nộp bài thành công trên hệ thống thì không cần phải gửi lại qua email (\"They do not need to use the alternative email method\")."}]}},{"id":"read14_m2_t4","title":"Task 4: Academic Reading (Ecological Succession)","task_type":"read_academic","content":{"academic_area":"Ecology / Environmental Biology","passage":"Ecological succession is the gradual process through which the organisms living in an ecosystem change over time. It can occur when an environment is newly formed or when an existing ecosystem is disturbed. As different species establish themselves, they alter conditions such as the availability of nutrients, sunlight, and shelter. These changes can make the environment more suitable for some species and less suitable for others. One form of succession occurs where little or no soil exists, such as on newly exposed rock. Organisms such as lichens and certain microorganisms may establish themselves first and contribute to soil formation. A different form occurs after a disturbance such as a forest fire when soil remains. Because nutrients and some organisms may survive, recovery can occur more quickly. Succession does not always lead to exactly the same final community. Climate, soil conditions, the type of disturbance, and the species available in the surrounding area can influence the process. Understanding ecological succession helps scientists study how ecosystems recover from disturbances and how communities change as environmental conditions develop. It also provides useful information for managing damaged habitats and supporting their recovery.","questions":[{"id":"read14_m2_q16","type":"multiple_choice","prompt":"The word \"disturbance\" in the passage is closest in meaning to","options":{"A":"disruption","B":"improvement","C":"prediction","D":"measurement"},"correct_answer":"A","explanation":"Từ \"disturbance\" trong ngữ cảnh sinh thái mang nghĩa xáo trộn, gián đoạn cấu trúc (\"disruption\")."},{"id":"read14_m2_q17","type":"multiple_choice","prompt":"What is one factor that can influence the final community in an ecosystem?","options":{"A":"The age of the scientists studying it","B":"The climate of the area","C":"The number of plants initially observed","D":"The length of the recovery period"},"correct_answer":"B","explanation":"Khí hậu của khu vực là một trong những yếu tố then chốt quyết định quần xã sinh vật đỉnh cực cuối cùng (\"The climate of the area\")."},{"id":"read14_m2_q18","type":"multiple_choice","prompt":"Why does the author mention lichens and microorganisms?","options":{"A":"To explain why forest fires are common in certain ecosystems.","B":"To provide examples of organisms that can help begin soil formation.","C":"To show that they are found mainly in newly formed ecosystems.","D":"To compare them with organisms found only in mature forests."},"correct_answer":"B","explanation":"Địa y và vi sinh vật được nhắc đến như ví dụ về các sinh vật tiên phong giúp bắt đầu quá trình hình thành đất trên đá trần."},{"id":"read14_m2_q19","type":"multiple_choice","prompt":"As different species establish themselves, they alter conditions such as the availability of nutrients, sunlight, and shelter.","options":{"A":"Environmental conditions prevent new species from becoming established.","B":"All species require the same amounts of nutrients and sunlight.","C":"New species can change environmental conditions as they become established.","D":"Nutrients and sunlight are the only factors that affect ecosystems."},"correct_answer":"C","explanation":"Ý tương đương: Các loài mới có thể làm biến đổi các điều kiện môi trường xung quanh khi chúng dần định cư và phát triển."},{"id":"read14_m2_q20","type":"multiple_choice","prompt":"Where would the following sentence best fit: \"Plants can then grow, followed by other organisms that depend on them.\"?","options":{"A":"Location A","B":"Location B","C":"Location C","D":"Location D"},"correct_answer":"B","explanation":"Vị trí [B] là vị trí thích hợp nhất để chèn câu nói về thực vật mọc lên và các sinh vật khác phụ thuộc vào chúng theo sau."}]}}]}],"description":"Bộ đề TOEFL iBT 2026 Multistage Adaptive (YouTube Practice 13): Module 1 (Digital Literacy, Office Notice, Policy Update, Placebo Effect) & Module 2 (Work-Life Balance, Sign, Platform Update, Ecological Succession).","created_at_ms":1791231607965}'::jsonb,
  timezone('utc'::text, now())
)
ON CONFLICT (id) DO UPDATE SET
  title = EXCLUDED.title,
  skill = EXCLUDED.skill,
  task_type = EXCLUDED.task_type,
  duration_seconds = EXCLUDED.duration_seconds,
  content = EXCLUDED.content;

INSERT INTO public.tests (id, title, skill, task_type, duration_seconds, content, created_at)
VALUES (
  'reading-practice-15',
  'Reading Practice Test 15 (TOEFL 2026 - Effective Communication & Social Facilitation)',
  'reading',
  'multistage',
  1800,
  '{"stages":[{"id":"read15_stage_1","title":"Reading - Module 1 (Stage 1)","duration_seconds":900,"description":"Module 1 gồm 4 phần (20 câu hỏi). Hãy hoàn thành trước khi hết 15 phút.","tasks":[{"id":"read15_m1_t1","title":"Task 1: Complete the Words (Đoạn 1 - Effective Communication)","task_type":"complete_words","content":{"instructions":"Điền các chữ cái còn thiếu vào vị trí dấu gạch dưới `_` trong đoạn văn sau:","paragraph":"Effective communication involves expressing ideas clearly while also understanding and respecting others'' perspectives. Strong communi[cators] listen activ[ely], ask clarif[ying] questions, a[nd] adapt th[eir] message to su[it] different audie[nces] and conte[xts]. Poor communic[ation] can l[ead] to misunderstandings, conflict, and inefficiency in both professional and personal environments. By developing communication skills, individuals strengthen relationships, improve teamwork, and enhance leadership potential. Clear and thoughtful communication is essential for academic success, workplace collaboration, and meaningful social interaction in diverse settings.","blanks":[{"id":"read15_m1_t1_b1","prefix":"communi","missing":"cators","full":"communicators"},{"id":"read15_m1_t1_b2","prefix":"activ","missing":"ely","full":"actively"},{"id":"read15_m1_t1_b3","prefix":"clarif","missing":"ying","full":"clarifying"},{"id":"read15_m1_t1_b4","prefix":"a","missing":"nd","full":"and"},{"id":"read15_m1_t1_b5","prefix":"th","missing":"eir","full":"their"},{"id":"read15_m1_t1_b6","prefix":"su","missing":"it","full":"suit"},{"id":"read15_m1_t1_b7","prefix":"audie","missing":"nces","full":"audiences"},{"id":"read15_m1_t1_b8","prefix":"conte","missing":"xts","full":"contexts"},{"id":"read15_m1_t1_b9","prefix":"communic","missing":"ation","full":"communication"},{"id":"read15_m1_t1_b10","prefix":"l","missing":"ead","full":"lead"}]}},{"id":"read15_m1_t2","title":"Task 2: Read a Notice (Laundry Room Maintenance)","task_type":"read_daily_life","content":{"document_type":"Residential Notice","passage":"The laundry room in the main apartment building will be closed for maintenance from March 12 to March 14. During this period, residents may use the laundry facilities in Building C instead. To enter Building C, residents must use their apartment access card and follow the laundry schedule posted near the entrance. Residents are encouraged to check the schedule before going to Building C, as the number available machines may be limited.","questions":[{"id":"read15_m1_q11","type":"multiple_choice","prompt":"Why will the main laundry room be closed?","options":{"A":"For a holiday event","B":"Because residents requested fewer services","C":"Because Building C is unavailable","D":"For maintenance work"},"correct_answer":"D","explanation":"Phòng giặt chính tạm thời đóng cửa để tiến hành công tác bảo trì định kỳ (\"For maintenance work\")."},{"id":"read15_m1_q12","type":"multiple_choice","prompt":"What should residents use to enter Building C?","options":{"A":"A temporary key from the manager","B":"Their apartment access card","C":"A visitor registration form","D":"A phone application"},"correct_answer":"B","explanation":"Cư dân cần sử dụng thẻ ra vào căn hộ của mình để vào phòng giặt tại Tòa C (\"Their apartment access card\")."}]}},{"id":"read15_m1_t3","title":"Task 3: Read an Email (Wellness & Fitness Program)","task_type":"read_daily_life","content":{"document_type":"Health & Fitness Announcement","passage":"Subject: Spring Fitness Program Registration Dear Residents, The community center will offer a six-week fitness program starting March 3. It will include yoga on Tuesdays, strength training on Thursdays, and outdoor walking on Saturdays. Participants can join all three activities or choose individual classes. Registration is open from February 10 to February 25. Those who register before February 15 will receive a free fitness guide. After February 25, registrations will only be accepted if spaces remain. Participants should bring a water bottle and exercise mat for yoga. The center will provide equipment for strength training.","questions":[{"id":"read15_m1_q13","type":"multiple_choice","prompt":"How many weeks will participants be able to attend the program?","options":{"A":"Three","B":"Six","C":"Eight","D":"Until February 25"},"correct_answer":"B","explanation":"Chương trình rèn luyện sức khỏe sẽ kéo dài trong tổng cộng sáu tuần (\"Six\")."},{"id":"read15_m1_q14","type":"multiple_choice","prompt":"Which participant will receive a free fitness guide?","options":{"A":"Someone who registers on February 20","B":"Someone who registers on February 15","C":"Someone who registers on February 14","D":"Someone who registers after the program begins"},"correct_answer":"C","explanation":"Người đăng ký vào ngày 14 tháng Hai sẽ được nhận miễn phí cẩm nang hướng dẫn tập luyện (\"Someone who registers on February 14\")."},{"id":"read15_m1_q15","type":"multiple_choice","prompt":"Which is true about the program?","options":{"A":"Participants must attend all three activities.","B":"The center provides equipment for yoga.","C":"Registration is guaranteed after February 25.","D":"Participants can choose which activities to attend."},"correct_answer":"D","explanation":"Người tham gia có quyền tự do lựa chọn các hoạt động phù hợp với sở thích của mình (\"Participants can choose which activities to attend\")."}]}},{"id":"read15_m1_t4","title":"Task 4: Academic Reading (Social Facilitation)","task_type":"read_academic","content":{"academic_area":"Social Psychology","passage":"Social facilitation refers to the tendency for a person''s performance to change when other people are present. In some situations, the presence of an audience can improve performance, particularly when a person is performing a familiar or simple task. For example, an experienced athlete may perform a well-practiced movement more effectively when competing in front of spectators. However, the presence of others does not always produce better results. When a task is difficult or unfamiliar, being observed can sometimes reduce performance. People may become more self-conscious or pay too much attention to actions that would normally occur automatically. A student who has practiced a presentation many times may speak confidently in front of an audience, while another student who is still learning the material may become distracted by the presence of listeners. Thus, the same social situation can have different effects depending on the task and the individual''s level of experience. Researchers have found that other factors can also influence social facilitation, including the size of the audience and how important the task seems to the individual. The phenomenon suggests that the presence of other people does not simply make performance better or worse. Instead, its effects depend partly on the type of activity and how prepared the person is. Recognizing these differences can be useful when designing classrooms, workplaces, and competitive environments.","questions":[{"id":"read15_m1_q16","type":"multiple_choice","prompt":"According to the passage, which factor can influence the effects of social facilitation?","options":{"A":"The person''s age","B":"The length of the task","C":"The location of the activity","D":"The size of the audience"},"correct_answer":"D","explanation":"Kích thước của khán giả và mức độ quan sát xung quanh có thể ảnh hưởng đến mức độ của hiệu ứng thúc đẩy xã hội."},{"id":"read15_m1_q17","type":"multiple_choice","prompt":"People may become more self-conscious or pay too much attention to actions that would normally occur automatically.","options":{"A":"People may focus too much on their behavior when they are being observed.","B":"People usually become more confident when they pay attention to their actions.","C":"People can perform automatic actions only when no one is watching them.","D":"People are less aware of their behavior when they are performing difficult tasks."},"correct_answer":"A","explanation":"Ý tương đương: Mọi người có thể quá chú ý và bận tâm đến hành vi của mình khi nhận biết có người khác đang quan sát."},{"id":"read15_m1_q18","type":"multiple_choice","prompt":"Where would the following sentence best fit: \"This effect is particularly likely when people are still developing the skills needed to perform the task.\"?","options":{"A":"Location A","B":"Location B","C":"Location C","D":"Location D"},"correct_answer":"B","explanation":"Vị trí [B] là vị trí phù hợp nhất để chèn câu nhấn mạnh hiệu ứng này dễ xảy ra khi con người vẫn đang trong giai đoạn rèn luyện kỹ năng mới."},{"id":"read15_m1_q19","type":"multiple_choice","prompt":"The word \"familiar\" in the passage is closest in meaning to","options":{"A":"competitive","B":"unusual","C":"complicated","D":"well-known"},"correct_answer":"D","explanation":"Từ \"familiar\" trong bài mang nghĩa quen thuộc, thân thuộc (\"well-known\")."},{"id":"read15_m1_q20","type":"multiple_choice","prompt":"What is the relationship between paragraphs 1 and 2?","options":{"A":"Paragraph 2 explains a situation in which the effect described in paragraph 1 can be different.","B":"Paragraph 2 provides evidence that contradicts the main theory presented in paragraph 1.","C":"Paragraph 2 describes a new phenomenon that is unrelated to the examples in paragraph 1.","D":"Paragraph 2 explains how researchers solved a problem introduced in paragraph 1."},"correct_answer":"A","explanation":"Đoạn 2 giải thích trường hợp mà hiệu ứng mô tả ở đoạn 1 xảy ra theo chiều hướng ngược lại (khi công việc khó khăn hoặc chưa thuần thục)."}]}}]},{"id":"read15_stage_2","title":"Reading - Module 2 (Stage 2 - HARD)","duration_seconds":900,"description":"Module 2 gồm 4 phần (20 câu hỏi). Hãy hoàn thành trước khi hết 15 phút.","tasks":[{"id":"read15_m2_t1","title":"Task 1: Complete the Words (Đoạn 2 - Historical Knowledge)","task_type":"complete_words","content":{"instructions":"Điền các chữ cái còn thiếu vào vị trí dấu gạch dưới `_` trong đoạn văn sau:","paragraph":"Historical knowledge enables individuals to understand the foundations of current social, political, and cultural systems. By study[ing] past ev[ents], people c[an] identify recu[rring] patterns, signifi[cant] achievements, and crit[ical] mistakes th[at] continue t[o] influence mod[ern] societies. This aware[ness] encourages more thoughtful and informed decision-making regarding contemporary issues. History also shapes cultural identity and strengthens collective memory within communities. Understanding historical context promotes responsible citizenship and helps individuals appreciate the complexity of social change across time.","blanks":[{"id":"read15_m2_t1_b1","prefix":"study","missing":"ing","full":"studying"},{"id":"read15_m2_t1_b2","prefix":"ev","missing":"ents","full":"events"},{"id":"read15_m2_t1_b3","prefix":"c","missing":"an","full":"can"},{"id":"read15_m2_t1_b4","prefix":"recu","missing":"rring","full":"recurring"},{"id":"read15_m2_t1_b5","prefix":"signifi","missing":"cant","full":"significant"},{"id":"read15_m2_t1_b6","prefix":"crit","missing":"ical","full":"critical"},{"id":"read15_m2_t1_b7","prefix":"th","missing":"at","full":"that"},{"id":"read15_m2_t1_b8","prefix":"t","missing":"o","full":"to"},{"id":"read15_m2_t1_b9","prefix":"mod","missing":"ern","full":"modern"},{"id":"read15_m2_t1_b10","prefix":"aware","missing":"ness","full":"awareness"}]}},{"id":"read15_m2_t2","title":"Task 2: Read an announcement (IT System Password Security)","task_type":"read_daily_life","content":{"document_type":"IT Security Bulletin","passage":"Dear Staff Members, Starting January 12, all employees must update their computer passwords as part of a company- wide security improvement. New passwords must contain at least twelve characters, including a number and a special symbol. Employees should complete the update by January 20. Anyone who misses the deadline will temporarily lose access to company systems until the password is changed. Employees who have difficulty creating a new password may contact IT Support. Requests should include the employee''s department and a brief description of the problem.","questions":[{"id":"read15_m2_q11","type":"multiple_choice","prompt":"Why is the company requiring employees to update their passwords?","options":{"A":"To improve the security of company systems","B":"To give employees access to additional software","C":"To identify employees'' departments more easily","D":"To reduce the number of support requests"},"correct_answer":"A","explanation":"Công ty yêu cầu nhân viên đổi mật khẩu nhằm nâng cao mức độ bảo mật cho hệ thống nội bộ (\"To improve the security of company systems\")."},{"id":"read15_m2_q12","type":"multiple_choice","prompt":"What will happen if an employee has not updated their password by January 20?","options":{"A":"Their access to company systems will be permanently removed.","B":"They will have to complete a security training course.","C":"They will temporarily lose access until the password is changed.","D":"They will need their manager''s permission to create a new password."},"correct_answer":"C","explanation":"Nếu nhân viên chưa đổi mật khẩu trước ngày 20 tháng Giêng, quyền truy cập tài khoản sẽ bị tạm khóa cho đến khi cập nhật (\"They will temporarily lose access until the password is changed\")."}]}},{"id":"read15_m2_t3","title":"Task 3: Read an email (Dormitory Heating Inspection)","task_type":"read_daily_life","content":{"document_type":"Housing Office Notice","passage":"Subject: Room Inspection Schedule Dear Residents, Annual room inspections in Maple Hall will be conducted from November 6 to November 10, between 9 a.m. and 4 p.m. Students do not need to be present, but rooms must be accessible to housing staff. Before the inspections, residents should remove personal items from heating units, clear food from shared refrigerators, and report maintenance problems through the housing portal by November 3. Students who cannot provide access during the inspection period must contact the Housing Office by November 1 to arrange an alternative time. Requests made after this date may not be accommodated.","questions":[{"id":"read15_m2_q13","type":"multiple_choice","prompt":"What can be inferred about students who do not contact the Housing Office by November 1?","options":{"A":"They will have to remain in their rooms during the inspection.","B":"They may not be able to arrange another inspection time.","C":"They will automatically receive a housing contract extension.","D":"They will be required to pay an additional inspection fee."},"correct_answer":"B","explanation":"Sinh viên không liên hệ Văn phòng Ký túc xá trước ngày 1 tháng Mười một có thể sẽ không thể sắp xếp lại khung giờ kiểm tra khác."},{"id":"read15_m2_q14","type":"multiple_choice","prompt":"What should residents do before the inspections?","options":{"A":"Remain in their rooms during the inspection","B":"Remove personal items from heating units","C":"Move their food to another residence hall","D":"Submit a new housing application"},"correct_answer":"B","explanation":"Cư dân cần dọn dẹp các đồ đạc cá nhân xung quanh thiết bị sưởi trước ngày kiểm tra (\"Remove personal items from heating units\")."},{"id":"read15_m2_q15","type":"multiple_choice","prompt":"What should a student do if they cannot provide room access?","options":{"A":"Contact the Housing Office by November 1","B":"Report the problem after the inspections","C":"Ask another resident to provide access","D":"Cancel their housing contract"},"correct_answer":"A","explanation":"Nếu không thể có mặt để mở cửa, sinh viên phải liên hệ văn phòng trước ngày 1 tháng Mười một để có phương án hỗ trợ."}]}},{"id":"read15_m2_t4","title":"Task 4: Academic Reading (The Mere Exposure Effect)","task_type":"read_academic","content":{"academic_area":"Psychology / Consumer Behavior","passage":"The mere exposure effect is a psychological phenomenon in which people tend to develop more positive feelings toward something after encountering it repeatedly. Familiarity can make an object, person, idea, or piece of music seem more comfortable or appealing, even when the individual has not consciously decided that it is better. For example, a song that initially seems uninteresting may become more enjoyable after a person hears it several times. The effect has been observed in a variety of everyday situations. Advertisers may repeatedly display a brand name so that consumers become familiar with it. Similarly, people may develop greater liking for a particular place after visiting it several times. Repeated exposure does not necessarily mean that people will consciously remember every previous encounter. Instead, familiarity itself can influence their reactions. However, the mere exposure effect does not mean that repeated contact will always produce positive feelings. If an experience is strongly unpleasant, additional exposure may not increase someone''s liking for it. The effect can also depend on how often something is encountered and whether the person notices the repetition. Understanding the phenomenon helps explain why familiarity can influence preferences and why repeated exposure is sometimes used in advertising and other forms of communication.","questions":[{"id":"read15_m2_q16","type":"multiple_choice","prompt":"What is the main idea of the passage?","options":{"A":"People usually remember every advertisement they see.","B":"Repeated exposure can increase familiarity and positive feelings, although this effect has limits.","C":"Advertising is the main reason people develop personal preferences.","D":"People always prefer familiar things to unfamiliar ones."},"correct_answer":"B","explanation":"Ý chính: Việc tiếp xúc lặp đi lặp lại có xu hướng gia tăng sự quen thuộc và thiện cảm, tuy nhiên hiệu ứng này cũng có những giới hạn nhất định."},{"id":"read15_m2_q17","type":"multiple_choice","prompt":"The word \"appealing\" in the passage is closest in meaning to","options":{"A":"attractive","B":"confusing","C":"expensive","D":"unusual"},"correct_answer":"A","explanation":"Từ \"appealing\" trong ngữ cảnh này mang nghĩa hấp dẫn, cuốn hút (\"attractive\")."},{"id":"read15_m2_q18","type":"multiple_choice","prompt":"Why does the author mention advertising and visiting a particular place?","options":{"A":"To show that repeated exposure can influence preferences in different everyday situations.","B":"To explain why advertising is more effective than personal experience.","C":"To compare commercial products with tourist destinations.","D":"To show that people consciously remember every repeated encounter."},"correct_answer":"A","explanation":"Tác giả nêu ví dụ về quảng cáo và việc ghé thăm một địa điểm quen thuộc để chứng minh hiệu ứng tiếp xúc xuất hiện phổ biến trong đời sống hàng ngày."},{"id":"read15_m2_q19","type":"multiple_choice","prompt":"What can be inferred about how repeated advertising may influence consumers?","options":{"A":"Repeated ads are effective only for brands people already like.","B":"Consumers need to remember every ad to like a brand.","C":"Consumers may like a brand more without remembering every ad.","D":"Consumers usually dislike brands after seeing the same ad repeatedly."},"correct_answer":"C","explanation":"Người tiêu dùng có thể nảy sinh thiện cảm với một thương hiệu nhiều hơn ngay cả khi không nhớ rõ từng mẩu quảng cáo cụ thể."},{"id":"read15_m2_q20","type":"multiple_choice","prompt":"According to the passage, all of the following are true EXCEPT","options":{"A":"Repeated exposure can make something seem more familiar.","B":"The mere exposure effect can influence people''s preferences.","C":"The effect can occur even when people do not consciously remember every encounter.","D":"Repeated exposure always causes people to develop positive feelings."},"correct_answer":"D","explanation":"Khẳng định sai là \"Việc tiếp xúc lặp lại luôn luôn tạo ra cảm xúc tích cực\" (nếu tiếp xúc quá mức hoặc ấn tượng ban đầu tiêu cực thì hiệu ứng có thể đảo ngược)."}]}}]}],"description":"Bộ đề TOEFL iBT 2026 Multistage Adaptive (YouTube Practice 14): Module 1 (Communication Skills, Workshop Notice, Advisor Email, Social Facilitation) & Module 2 (Historical Knowledge, Campus Announcement, Mentor Email, Mere Exposure Effect).","created_at_ms":1791231607965}'::jsonb,
  timezone('utc'::text, now())
)
