INSERT INTO public.tests (id, title, skill, task_type, duration_seconds, content, created_at)
VALUES (
  'listening-practice-01',
  'Listening Practice Test 01 (TOEFL 2026 - Campus Life & The Silk Road)',
  'listening',
  'multistage',
  1740,
  '{"stages":[{"id":"list1_stage_1","title":"Listening - Module 1 (Stage 1)","duration_seconds":870,"description":"Module 1 gồm các dạng bài: Choose a Response, Conversation, Announcement, Academic Talk. Hoàn thành trong 14.5 phút.","tasks":[{"id":"list1_m1_t1","title":"Task 1: Listen & Choose a Response (8 câu)","task_type":"choose_response","content":{"instructions":"Lắng nghe câu nói ngắn và chọn phản xạ trả lời phù hợp nhất theo chuẩn giao tiếp đại học Bắc Mỹ.","questions":[{"id":"list1_m1_q1","type":"choose_response","audio_text":". Do you know if the library is still open?","prompt":"Select the most appropriate response to what you heard:","options":{"C":"The library is very old.","A":"No, it closes at IO p.m.","B":"Yes, it''s very quiet inside.","D":"I read many books."},"correct_answer":"A","explanation":"Đáp án đúng là (A): \"No, it closes at IO p.m.\". Đây là câu phản xạ giao tiếp tự nhiên và chuẩn xác nhất theo ngữ cảnh văn hóa đại học Bắc Mỹ."},{"id":"list1_m1_q2","type":"choose_response","audio_text":"Do you know if the library is still open? Do you know if the library is still open? Do you know if the library is still open? Where should I Where should I Where should I return this book?","prompt":"Select the most appropriate response to what you heard:","options":{"C":"At the circulation desk.","A":"It''s already overdue.","B":"In the science section.","D":"It costs ten dollars."},"correct_answer":"C","explanation":"Đáp án đúng là (C): \"At the circulation desk.\". Đây là câu phản xạ giao tiếp tự nhiên và chuẩn xác nhất theo ngữ cảnh văn hóa đại học Bắc Mỹ."},{"id":"list1_m1_q3","type":"choose_response","audio_text":"return this book? return this book? Can I borrow more than three books at a time? Can I borrow more than three books at a time?","prompt":"Select the most appropriate response to what you heard:","options":{"C":"You need to show your ID.","A":"I walked here yesterday.","B":"No, it isn''t raining.","D":"Books are heavy to carry."},"correct_answer":"C","explanation":"Đáp án đúng là (C): \"You need to show your ID.\". Đây là câu phản xạ giao tiếp tự nhiên và chuẩn xác nhất theo ngữ cảnh văn hóa đại học Bắc Mỹ."},{"id":"list1_m1_q4","type":"choose_response","audio_text":"Can I borrow more than three books at a time? I do I do I do n''t see a reference section. When are the study","prompt":"Select the most appropriate response to what you heard:","options":{"C":"I bought a reference book.","A":"Yes, I enjoy reading.","B":"It''s on the second floor.","D":"Please write your name."},"correct_answer":"B","explanation":"Đáp án đúng là (B): \"It''s on the second floor.\". Đây là câu phản xạ giao tiếp tự nhiên và chuẩn xác nhất theo ngữ cảnh văn hóa đại học Bắc Mỹ."},{"id":"list1_m1_q5","type":"choose_response","audio_text":"n''t see a reference section. When are the study n''t see a reference section. When are the study n''t see a reference section. When are the study rooms available ?","prompt":"Select the most appropriate response to what you heard:","options":{"C":"The chairs are very comfortable.","A":"You can reserve them online.","B":"I studied for three hours.","D":"No, I haven''t eaten yet."},"correct_answer":"A","explanation":"Đáp án đúng là (A): \"You can reserve them online.\". Đây là câu phản xạ giao tiếp tự nhiên và chuẩn xác nhất theo ngữ cảnh văn hóa đại học Bắc Mỹ."},{"id":"list1_m1_q6","type":"choose_response","audio_text":"? Do I need a password to use the computers? Do I need a password to use the computers?","prompt":"Select the most appropriate response to what you heard:","options":{"C":"It''s near the bus stop.","A":"Yes, your student login.","B":"The computers are heavy.","D":"Please read the password."},"correct_answer":"A","explanation":"Đáp án đúng là (A): \"Yes, your student login.\". Đây là câu phản xạ giao tiếp tự nhiên và chuẩn xác nhất theo ngữ cảnh văn hóa đại học Bắc Mỹ."},{"id":"list1_m1_q7","type":"choose_response","audio_text":"Sorry. What''s up? Is What''s up? Is What''s up? Is printing free here? free here?","prompt":"Select the most appropriate response to what you heard:","options":{"C":"Computers are everywhere.","A":"Yes, the printer is very loud.","B":"No, it costs 10 cents per page.","D":"I finished last week."},"correct_answer":"B","explanation":"Đáp án đúng là (B): \"No, it costs 10 cents per page.\". Đây là câu phản xạ giao tiếp tự nhiên và chuẩn xác nhất theo ngữ cảnh văn hóa đại học Bắc Mỹ."},{"id":"list1_m1_q8","type":"choose_response","audio_text":"free here? Where to ask for help with research? Listen to a","prompt":"Select the most appropriate response to what you heard:","options":{"C":"That''s a long book.","A":"At the reference desk.","B":"I help my friend often.","D":"Yes, I''ll call later."},"correct_answer":"A","explanation":"Đáp án đúng là (A): \"At the reference desk.\". Đây là câu phản xạ giao tiếp tự nhiên và chuẩn xác nhất theo ngữ cảnh văn hóa đại học Bắc Mỹ."}]}},{"id":"list1_m1_t2","title":"Task 2: Campus Conversation 1","task_type":"conversation","content":{"context_title":"Hội thoại khuôn viên trường đại học","audio_text":"Where to ask for help with research? Listen to a to ask for help with research? Listen to a to ask for help with research? Listen to a conversation . Hey, do you want to Hey, do you want to Hey, do you want to eat in the cafeteria eat in the cafeteria eat in the cafeteria ? I will, but it will be I will, but it will be very crowded there at this time very crowded there at this time very crowded there at this time . True. If we True. If we True. If we wait 20 minutes wait 20 minutes wait 20 minutes , the crowd will , the crowd will , the crowd will thin out. thin out. thin out. Okay, let Okay, let Okay, let ''s do that. ''s do that. ''s do that. I will finish reading this by then I will finish reading this by then . Good . Good . Good idea. I''ll find a place for us when the crowds clear up I''ll find a place for us when the crowds clear up . Listen to a","questions":[{"id":"list1_m1_q9","prompt":"Why does the man suggest waiting?","options":{"A":"He needs to finish studying.","B":"The cafeteria is full.","C":"He wants to eat somewhere else.","D":"He already ate lunch."},"correct_answer":"B","explanation":"Đáp án (B) chính xác: \"The cafeteria is full.\". Người nói đã giải thích rõ lý do này trong đoạn ghi âm."},{"id":"list1_m1_q10","prompt":"What does the woman plan to do?","options":{"A":"Start eating without him","B":"Save seats when the cafeteria is less busy","C":"Order food for both of them","D":"Find another place to eat"},"correct_answer":"B","explanation":"Đáp án đúng là (B): \"Save seats when the cafeteria is less busy\". Dựa vào chi tiết trực tiếp được người nói đề cập trong bài nghe."}]}},{"id":"list1_m1_t3","title":"Task 3: Campus Conversation 2","task_type":"conversation","content":{"context_title":"Hội thoại dịch vụ sinh viên","audio_text":". Listen to a . Listen to a . Listen to a conversation . Have you . Have you . Have you booked a doctor''s appointment booked a doctor''s appointment booked a doctor''s appointment ? Not ? Not ? Not yet. The yet. The yet. The office closes early today, closes early today, closes early today, so I''ll so I''ll so I''ll call tomorrow call tomorrow call tomorrow . I thought it would be open until 6:00. That''s I thought it would be open until 6:00. That''s I thought it would be open until 6:00. That''s usually the case usually the case usually the case , but on but on but on Fridays they close at 3:00. Oh, they close at 3:00. Oh, they close at 3:00. Oh, I did I did I did n''t know that. n''t know that. Listen.","questions":[{"id":"list1_m1_q11","prompt":"Why didn''t the woman make the appointment today?","options":{"A":"She forgot to call.","B":"She didn''t have the phone number.","C":"She doesn''t know the doctor''s schedule.","D":"The office closed earlier than usual."},"correct_answer":"D","explanation":"Đáp án (D) chính xác: \"The office closed earlier than usual.\". Người nói đã giải thích rõ lý do này trong đoạn ghi âm."},{"id":"list1_m1_q12","prompt":"What does the man''s response suggest?","options":{"A":"He already knew the Friday schedule.","B":"He also needs an appointment.","C":"He was mistaken about the office hours.","D":"He is upset the woman didn''t call sooner."},"correct_answer":"C","explanation":"Đáp án đúng là (C): \"He was mistaken about the office hours.\". Đây là suy luận hợp lý nhất từ các chi tiết ngầm định của người nói."}]}},{"id":"list1_m1_t4","title":"Task 4: Campus Announcement","task_type":"announcement","content":{"context_title":"Thông báo nội bộ trường đại học","audio_text":"Listen. Listen to an announcement in the classroom. Dear Listen to an announcement in the classroom. Dear Listen to an announcement in the classroom. Dear students , the Sociology 2011 , the Sociology 2011 , the Sociology 2011 midterm exam will be held next exam will be held next exam will be held next Thursday at Thursday at Thursday at 9:00 AM 9:00 AM 9:00 AM in Room 214 of the Humanities Building in Room 214 of the Humanities Building in Room 214 of the Humanities Building . Please bring photo Please bring photo Please bring photo ID and ID and ID and two pencils . Calculators are Calculators are Calculators are not allowed. If not allowed. If not allowed. If you have any difficulty with this new you have any difficulty with this new you have any difficulty with this new date , please , please , please contact the department office immediately. contact the department office immediately. contact the department office immediately. Hey, listen to","questions":[{"id":"list1_m1_q13","prompt":"What is the main topic of the announcement?","options":{"A":"A change in the exam date","B":"The location of a guest lecture","C":"A review session for the exam","D":"Registration for a new class"},"correct_answer":"A","explanation":"Đáp án chính xác là (A): \"A change in the exam date\". Thông tin trọng tâm xuyên suốt bài nghe nhấn mạnh vào ý chính này."},{"id":"list1_m1_q14","prompt":"Why does the speaker mention calculators?","options":{"A":"To remind students to bring one","B":"To state they are not allowed","C":"To recommend a specific type","D":"To explain how they will be provided"},"correct_answer":"B","explanation":"Đáp án (B) chính xác: \"To state they are not allowed\". Người nói đã giải thích rõ lý do này trong đoạn ghi âm."}]}},{"id":"list1_m1_t5","title":"Task 5: Academic Lecture","task_type":"academic_talk","content":{"context_title":"Bài giảng học thuật","audio_text":"contact the department office immediately. Hey, listen to Hey, listen to Hey, listen to a speech in history class a speech in history class a speech in history class . The Silk . The Silk . The Silk Road was actually Road was actually not a single road, but a not a single road, but a not a single road, but a system of trade routes connecting China with the Mediterranean region. Goods such as silk, system of trade routes connecting China with the Mediterranean region. Goods such as silk, system of trade routes connecting China with the Mediterranean region. Goods such as silk, spices, and precious and precious and precious stones traveled through these routes, traveled through these routes, traveled through these routes, but ideas but ideas but ideas also spread. For example, For example, For example, Buddhism spread from India to China through these Buddhism spread from India to China through these Buddhism spread from India to China through these routes . The importance of the Silk Road was not just . The importance of the Silk Road was not just . The importance of the Silk Road was not just trade . This is a This is a This is a cultural exchange. Now, one of the results of these Now, one of the results of these Now, one of the results of these interactions is the interactions is the interactions is the fusion of artistic traditions. fusion of artistic traditions. fusion of artistic traditions. For example, For example, Buddha statues found in western China Buddha statues found in western China Buddha statues found in western China often have Greek- often have Greek- often have Greek- style clothing . Another was the Another was the Another was the sharing of technology like paper, which sharing of technology like paper, which sharing of technology like paper, which traveled west and traveled west and traveled west and eventually transformed European education. transformed European education. transformed European education. So when we So when we So when we talk about globalization today talk about globalization today , the Silk Road , the Silk Road , the Silk Road reminds us that reminds us that this connection is this connection is this connection is not new. not new. not new. It has been It has been It has been shaping societies for centuries shaping societies for centuries . When does breakfast","questions":[{"id":"list1_m1_q15","prompt":"What is the main topic of the talk?","options":{"A":"The rise of Mediterranean civilizations","B":"The spread of papermaking in Europe","C":"The cultural and economic role of the Silk Road","D":"The invention of trade routes in China"},"correct_answer":"C","explanation":"Đáp án chính xác là (C): \"The cultural and economic role of the Silk Road\". Thông tin trọng tâm xuyên suốt bài nghe nhấn mạnh vào ý chính này."},{"id":"list1_m1_q16","prompt":"Why does the speaker mention Buddhism?","options":{"A":"To illustrate how religion spread along trade routes","B":"To explain the origins of silk production","C":"To highlight conflicts between India and China","D":"To describe the decline of the Silk Road"},"correct_answer":"A","explanation":"Đáp án (A) chính xác: \"To illustrate how religion spread along trade routes\". Người nói đã giải thích rõ lý do này trong đoạn ghi âm."},{"id":"list1_m1_q17","prompt":"What point does the speaker make about Buddha statues?","options":{"A":"They were made mostly in India.","B":"They combined artistic traditions.","C":"They were transported to Greece.","D":"They influenced Chinese writing systems."},"correct_answer":"B","explanation":"Đáp án đúng là (B): \"They combined artistic traditions.\". Dựa vào chi tiết trực tiếp được người nói đề cập trong bài nghe."},{"id":"list1_m1_q18","prompt":"What does the speaker imply about globalization?","options":{"A":"It is a relatively new development.","B":"It has caused more harm than good.","C":"It has roots in ancient history.","D":"It began only in Europe."},"correct_answer":"C","explanation":"Đáp án đúng là (C): \"It has roots in ancient history.\". Đây là suy luận hợp lý nhất từ các chi tiết ngầm định của người nói."}]}}]},{"id":"list1_stage_2","title":"Listening - Module 2 (Stage 2)","duration_seconds":870,"description":"Module 2 tiêu chuẩn: kiểm tra khả năng suy luận, nắm bắt ý chính và chi tiết học thuật.","tasks":[{"id":"list1_m2_t1","title":"Task 1: Listen & Choose a Response (8 câu)","task_type":"choose_response","content":{"instructions":"Lắng nghe câu nói ngắn và chọn phản xạ trả lời phù hợp nhất theo chuẩn giao tiếp đại học Bắc Mỹ.","questions":[{"id":"list1_m2_q1","type":"choose_response","audio_text":"shaping societies for centuries . When does breakfast . When does breakfast . When does breakfast end?","prompt":"Select the most appropriate response to what you heard:","options":{"C":"At ten thirty.","A":"It''s very crowded.","B":"Yes, I like eggs.","D":"I ate yesterday."},"correct_answer":"C","explanation":"Đáp án đúng là (C): \"At ten thirty.\". Đây là câu phản xạ giao tiếp tự nhiên và chuẩn xác nhất theo ngữ cảnh văn hóa đại học Bắc Mỹ."},{"id":"list1_m2_q2","type":"choose_response","audio_text":"end? Are vegetarian options available? Can I","prompt":"Select the most appropriate response to what you heard:","options":{"C":"I walk to class.","A":"Maybe next week.","B":"No, I''m not hungry.","D":"Yes, they''re clearly labeled."},"correct_answer":"D","explanation":"Đáp án đúng là (D): \"Yes, they''re clearly labeled.\". Đây là câu phản xạ giao tiếp t