VALUES (
  'listening-practice-13',
  'Listening Practice Test 13 (TOEFL 2026 - Volcanic Hazards & Modern Economic Geography)',
  'listening',
  'multistage',
  1740,
  '{"stages":[{"id":"list13_stage_1","title":"Listening - Module 1 (Stage 1)","duration_seconds":870,"description":"Module 1 gồm các dạng bài: Choose a Response, Conversation, Announcement, Academic Talk. Hoàn thành trong 14.5 phút.","tasks":[{"id":"list13_m1_t1","title":"Task 1: Listen & Choose a Response (8 câu)","task_type":"choose_response","content":{"instructions":"Lắng nghe câu nói ngắn và chọn phản xạ trả lời phù hợp nhất theo chuẩn giao tiếp đại học Bắc Mỹ.","questions":[{"id":"list13_m1_q1","type":"choose_response","audio_text":"should we include references on the slides","prompt":"Select the most appropriate response to what you heard:","options":{"C":"I personally did.","A":"Slides are too crowded.","B":"I wouldn''t say so.","D":"Yes, at the end."},"correct_answer":"D","explanation":"Đáp án đúng là (D): \"Yes, at the end.\". Đây là câu phản xạ giao tiếp tự nhiên và chuẩn xác nhất theo ngữ cảnh văn hóa đại học Bắc Mỹ."},{"id":"list13_m1_q2","type":"choose_response","audio_text":"the course description doesn''t match the syllabus","prompt":"Select the most appropriate response to what you heard:","options":{"C":"That''s strange — maybe ask the instructor.","A":"This is the way it should be.","B":"I read it carefully.","D":"The syllabus isn''t long."},"correct_answer":"C","explanation":"Đáp án đúng là (C): \"That''s strange — maybe ask the instructor.\". Đây là câu phản xạ giao tiếp tự nhiên và chuẩn xác nhất theo ngữ cảnh văn hóa đại học Bắc Mỹ."},{"id":"list13_m1_q3","type":"choose_response","audio_text":"could we reschedule our study session","prompt":"Select the most appropriate response to what you heard:","options":{"C":"Our biology exam is next week.","A":"The library stays open until midnight.","B":"Sure. Would tomorrow afternoon work instead?","D":"The study room has a large whiteboard."},"correct_answer":"B","explanation":"Đáp án đúng là (B): \"Sure. Would tomorrow afternoon work instead?\". Đây là câu phản xạ giao tiếp tự nhiên và chuẩn xác nhất theo ngữ cảnh văn hóa đại học Bắc Mỹ."},{"id":"list13_m1_q4","type":"choose_response","audio_text":"would you mind watering my plants this weekend","prompt":"Select the most appropriate response to what you heard:","options":{"C":"Your apartment gets plenty of sunlight.","A":"Yes, I do mind.","B":"Sure, I''ll stop by on Saturday morning.","D":"The flowerpots were a birthday present."},"correct_answer":"B","explanation":"Đáp án đúng là (B): \"Sure, I''ll stop by on Saturday morning.\". Đây là câu phản xạ giao tiếp tự nhiên và chuẩn xác nhất theo ngữ cảnh văn hóa đại học Bắc Mỹ."},{"id":"list13_m1_q5","type":"choose_response","audio_text":"the seminar overlaps with my lab","prompt":"Select the most appropriate response to what you heard:","options":{"C":"Never mind!","A":"You should inform both instructors.","B":"That''s because they''re too long.","D":"They are both equally important."},"correct_answer":"A","explanation":"Đáp án đúng là (A): \"You should inform both instructors.\". Đây là câu phản xạ giao tiếp tự nhiên và chuẩn xác nhất theo ngữ cảnh văn hóa đại học Bắc Mỹ."},{"id":"list13_m1_q6","type":"choose_response","audio_text":"I can''t get this vending machine to work","prompt":"Select the most appropriate response to what you heard:","options":{"C":"Try using a different payment method.","A":"It was restocked this morning.","B":"The snacks on the top shelf are healthier.","D":"A maintenance worker checked it yesterday."},"correct_answer":"C","explanation":"Đáp án đúng là (C): \"Try using a different payment method.\". Đây là câu phản xạ giao tiếp tự nhiên và chuẩn xác nhất theo ngữ cảnh văn hóa đại học Bắc Mỹ."},{"id":"list13_m1_q7","type":"choose_response","audio_text":"I feel behind in this class","prompt":"Select the most appropriate response to what you heard:","options":{"C":"I feel fine.","A":"You didn''t study hard enough.","B":"You could attend review sessions.","D":"It is definitely difficult."},"correct_answer":"B","explanation":"Đáp án đúng là (B): \"You could attend review sessions.\". Đây là câu phản xạ giao tiếp tự nhiên và chuẩn xác nhất theo ngữ cảnh văn hóa đại học Bắc Mỹ."},{"id":"list13_m1_q8","type":"choose_response","audio_text":"can you recommend a place for lunch nearby","prompt":"Select the most appropriate response to what you heard:","options":{"C":"Several restaurants offer student discounts.","A":"I usually bring my own lunch.","B":"The lunch break lasts only one hour.","D":"The café across the street has good sandwiches."},"correct_answer":"D","explanation":"Đáp án đúng là (D): \"The café across the street has good sandwiches.\". Đây là câu phản xạ giao tiếp tự nhiên và chuẩn xác nhất theo ngữ cảnh văn hóa đại học Bắc Mỹ."}]}},{"id":"list13_m1_t2","title":"Task 2: Campus Conversation 1","task_type":"conversation","content":{"context_title":"Hội thoại sinh viên 1","audio_text":"I reserved a study room but someone else is using it let me check the reservation schedule what time did you reserve the room for from 3 to 6:00 could there be two bookings for the same time so the room so the room I reserved is actually available yes it''s available until 6:00 great I''ll move to the correct room","questions":[{"id":"list13_m1_q9","prompt":"Why does the student speak with the staff member?","options":{"A":"To report a reservation problem.","B":"To extend a study room reservation.","C":"To request a quieter room.","D":"To cancel today''s reservation."},"correct_answer":"A","explanation":"Đáp án (A) chính xác: \"To report a reservation problem.\". Người nói đã giải thích rõ lý do này trong đoạn ghi âm."},{"id":"list13_m1_q10","prompt":"What will the student most likely do next?","options":{"A":"Wait until six o''clock.","B":"Share the room with another group.","C":"Move to the correct study room.","D":"Make a new reservation for tomorrow."},"correct_answer":"C","explanation":"Đáp án đúng là (C): \"Move to the correct study room.\". Dựa vào chi tiết trực tiếp được người nói đề cập trong bài nghe."}]}},{"id":"list13_m1_t3","title":"Task 3: Campus Conversation 2","task_type":"conversation","content":{"context_title":"Hội thoại sinh viên 2","audio_text":"my research interview was canceled at the last minute I see should I change my project schedule then okay I''ll prepare a new okay I''ll prepare a new consent form tonight great please print two copies before the interview","questions":[{"id":"list13_m1_q11","prompt":"Why was the interview canceled?","options":{"A":"The student forgot the consent forms.","B":"The participant was feeling unwell.","C":"The research schedule changed next week.","D":"The interviewer arrived late."},"correct_answer":"B","explanation":"Đáp án (B) chính xác: \"The participant was feeling unwell.\". Người nói đã giải thích rõ lý do này trong đoạn ghi âm."},{"id":"list13_m1_q12","prompt":"What will the student most likely do next?","options":{"A":"Rewrite the entire research project.","B":"Print two consent forms.","C":"Cancel tomorrow''s interview.","D":"Look for another research topic."},"correct_answer":"B","explanation":"Đáp án đúng là (B): \"Print two consent forms.\". Dựa vào chi tiết trực tiếp được người nói đề cập trong bài nghe."}]}},{"id":"list13_m1_t4","title":"Task 4: Campus Announcement 1","task_type":"announcement","content":{"context_title":"Thông báo khuôn viên trường 1","audio_text":"listen to an announcement at a water park for safety reasons The Wave Rider attraction is temporarily closed due to approaching storm conditions guests who are planning to use the attraction should avoid the area until further notice you are welcome to enjoy the parks indoor facilities while weather conditions are mon abilities while weather conditions are monitored The Wave Rider May reopen once conditions improve further updates will be provided every 20 minutes","questions":[{"id":"list13_m1_q13","prompt":"What is the announcement mainly about?","options":{"A":"A new attraction","B":"A temporary ride closure","C":"A lost child","D":"Reduced ticket prices"},"correct_answer":"B","explanation":"Đáp án chính xác là (B): \"A temporary ride closure\". Thông tin trọng tâm xuyên suốt bài nghe nhấn mạnh vào ý chính này."},{"id":"list13_m1_q14","prompt":"Why was the attraction closed?","options":{"A":"Because Of a mechanical failure","B":"Because of a staff shortage","C":"Because Of storm conditions","D":"Because Of cleaning procedures"},"correct_answer":"C","explanation":"Đáp án (C) chính xác: \"Because Of storm conditions\". Người nói đã giải thích rõ lý do này trong đoạn ghi âm."}]}},{"id":"list13_m1_t5","title":"Task 5: Campus Announcement 2","task_type":"announcement","content":{"context_title":"Thông báo khuôn viên trường 2","audio_text":"listen to an announcement before a concert welcome everyone before tonight''s performance begins please silence all mobile devices and refrain from recording audio or video during the show we also ask that you remain in your seats whenever possible once the performance has started late arrivals will be seated during late arrivals will be seated during an appropriate pause to avoid disturbing other guests thank you for your cooperation and we hope you enjoy tonight''s performance","questions":[{"id":"list13_m1_q15","prompt":"What is the main purpose of the announcement?","options":{"A":"TO introduce the musicians","B":"To advertise future concerts","C":"TO announce a cancellation","D":"To explain audience rules"},"correct_answer":"D","explanation":"Đáp án chính xác là (D): \"To explain audience rules\". Thông tin trọng tâm xuyên suốt bài nghe nhấn mạnh vào ý chính này."},{"id":"list13_m1_q16","prompt":"Why are late arrivals seated later?","options":{"A":"Tickets must be checked twice","B":"Security screening takes time","C":"To avoid disturbing others","D":"The doors remain locked"},"correct_answer":"C","explanation":"Đáp án (C) chính xác: \"To avoid disturbing others\". Người nói đã giải thích rõ lý do này trong đoạn ghi âm."}]}},{"id":"list13_m1_t6","title":"Task 6: Academic Lecture","task_type":"academic_talk","content":{"context_title":"Bài giảng học thuật đại học","audio_text":"listen to part of a social history class public libraries have played an important role in expanding access to information but the idea of making books widely available developed gradually in earlier periods books were expensive to produce and were often kept in private collections or institutions or institutions as printing became more efficient and literacy increased more communities began looking for ways to provide books and educational materials to a broader population early public libraries did not always resemble modern libraries some were supported by membership fees or donations While others financial support from local governments their collections were also more limited and visitors sometimes had to follow strict rules about which materials they could borrow or consult the development of public libraries gave people who could not afford books greater access to educational resources access to educational resources libraries also became places where people could study attend lectures and participate in community activities today libraries provide many services Beyond lending printed books including digital resources internet access educational programs and public SPAC no programs and public spaces although the services have changed the Central purpose remains similar providing communities with access to information and opportunities for learning as communities continue to change however libraries face new questions about how they can best serve the people who depend on them list of the people who depend on them these questions have become particularly important as the ways people find and use information have changed module 2","questions":[{"id":"list13_m1_q17","prompt":"What is the talk mainly about?","options":{"A":"The history Of public libraries and how their role in communities has developed","B":"The reasons modern libraries are replacing printed with digital materials","C":"The differences between private collections and university libraries","D":"The methods used to produce books before the invention of modern"},"correct_answer":"A","explanation":"Đáp án chính xác là (A): \"The history Of public libraries and how their role in communities has developed\". Thông tin trọng tâm xuyên suốt bài nghe nhấn mạnh vào ý chính này."},{"id":"list13_m1_q18","prompt":"According to the speaker, why did access to books gradually expand?","options":{"A":"Governments required people to donate their private collections.","B":"Books became easier to produce, and literacy increased.","C":"Libraries stopped charging membership fees in all communities.","D":"People became less interested in formal education."},"correct_answer":"B","explanation":"Đáp án (B) chính xác: \"Books became easier to produce, and literacy increased.\". Người nói đã giải thích rõ lý do này trong đoạn ghi âm."},{"id":"list13_m1_q19","prompt":"Why does the speaker mention lectures and community activities?","options":{"A":"To explain why early libraries had fewer books than modern libraries","B":"To give examples of how libraries served purposes beyond providing","C":"To describe the main reasons people were required to pay","D":"To show why libraries eventually stopped lending printed materials"},"correct_answer":"B","explanation":"Đáp án (B) chính xác: \"To give examples of how libraries served purposes beyond providing\". Người nói đã giải thích rõ lý do này trong đoạn ghi âm."},{"id":"list13_m1_q20","prompt":"What will the speaker most likely discuss next?","options":{"A":"How modem libraries may adapt to changing information needs","B":"Why early libraries charged membership fees","C":"How books were produced before the development of printing","D":"Why people have become less interested in using libraries"},"correct_answer":"A","explanation":"Đáp án đúng là (A): \"How modem libraries may adapt to changing information needs\". Dựa vào chi tiết trực tiếp được người nói đề cập trong bài nghe."}]}}]},{"id":"list13_stage_2","title":"Listening - Module 2 (Stage 2 - HARD)","duration_seconds":870,"description":"Module 2 cấp độ nâng cao (Hard): kiểm tra khả năng suy luận, nắm bắt ý chính và chi tiết học thuật.","tasks":[{"id":"list13_m2_t1","title":"Task 1: Listen & Choose a Response (8 câu)","task_type":"choose_response","content":{"instructions":"Lắng nghe câu nói ngắn và chọn phản xạ trả lời phù hợp nhất theo chuẩn giao tiếp đại học Bắc Mỹ.","questions":[{"id":"list13_m2_q1","type":"choose_response","audio_text":"I think I left my umbrella on the bus","prompt":"Select the most appropriate response to what you heard:","options":{"C":"That umbrella was a birthday gift.","A":"The weather forecast predicts sunshine tomorrow.","B":"You should contact the transit company.","D":"The bus was crowded during the morning commute."},"correct_answer":"B","explanation":"Đáp án đúng là (B): \"You should contact the transit company.\". Đây là câu phản xạ giao tiếp tự nhiên và chuẩn xác nhất theo ngữ cảnh văn hóa đại học Bắc Mỹ."},{"id":"list13_m2_q2","type":"choose_response","audio_text":"I''m looking for the nearest bus stop","prompt":"Select the most appropriate response to what you heard:","options":{"C":"Walk two blocks and turn left at the traffic light.","A":"The buses are usually on time here.","B":"The route changed earlier this year.","D":"Many people commute by bus."},"correct_answer":"C","explanation":"Đáp án đúng là (C): \"Walk two blocks and turn left at the traffic light.\". Đây là câu phản xạ giao tiếp tự nhiên và chuẩn xác nhất theo ngữ cảnh văn hóa đại học Bắc Mỹ."},{"id":"list13_m2_q3","type":"choose_response","audio_text":"my phone battery is almost dead","prompt":"Select the most appropriate response to what you heard:","options":{"C":"Your phone case looks brand new.","A":"The battery lasts longer in power-saving mode.","B":"There''s a charging station by the information desk.","D":"Most people carry portable chargers."},"correct_answer":"B","explanation":"Đáp án đúng là (B): \"There''s a charging station by the information desk.\". Đây là câu phản xạ giao tiếp tự nhiên và chuẩn xác nhất theo ngữ cảnh văn hóa đại học Bắc Mỹ."},{"id":"list13_m2_q4","type":"choose_response","audio_text":"is there a penalty for late arrival","prompt":"Select the most appropriate response to what you heard:","options":{"C":"We always arrive early.","A":"Arriving late is disrespectful.","B":"Yes, it affects participation points.","D":"This professor''s penalties are strict."},"correct_answer":"B","explanation":"Đáp án đúng là (B): \"Yes, it affects participation points.\". Đây là câu phản xạ giao tiếp tự nhiên và chuẩn xác nhất theo ngữ cảnh văn hóa đại học Bắc Mỹ."},{"id":"list13_m2_q5","type":"choose_response","audio_text":"could you watch my suitcase for a minute","prompt":"Select the most appropriate response to what you heard:","options":{"C":"The suitcase has a blue luggage tag.","A":"Of course. I''ll stay right here.","B":"Your flight leaves in less than an hour.","D":"The departure board was just updated."},"correct_answer":"A","explanation":"Đáp án đúng là (A): \"Of course. I''ll stay right here.\". Đây là câu phản xạ giao tiếp tự nhiên và chuẩn xác nhất theo ngữ cảnh văn hóa đại học Bắc Mỹ."},{"id":"list13_m2_q6","type":"choose_response","audio_text":"I don''t think my microphone is working","prompt":"Select the most appropriate response to what you heard:","options":{"C":"Why do you think this is happening?","A":"Try reconnecting it.","B":"Microphones are useful.","D":"It worked before."},"correct_answer":"A","explanation":"Đáp án đúng là (A): \"Try reconnecting it.\". Đây là câu phản xạ giao tiếp tự nhiên và chuẩn xác nhất theo ngữ cảnh văn hóa đại học Bắc Mỹ."},{"id":"list13_m2_q7","type":"choose_response","audio_text":"the classroom is locked","prompt":"Select the most appropriate response to what you heard:","options":{"C":"The lesson usually ends at noon.","A":"Classrooms close early.","B":"It is usually open.","D":"Maybe the room was changed."},"correct_answer":"D","explanation":"Đáp án đúng là (D): \"Maybe the room was changed.\". Đây là câu phản xạ giao tiếp tự nhiên và chuẩn xác nhất theo ngữ cảnh văn hóa đại học Bắc Mỹ."},{"id":"list13_m2_q8","type":"choose_response","audio_text":"I forgot to bring my swimming goggles","prompt":"Select the most appropriate response to what you heard:","options":{"C":"Swimming is excellent exercise.","A":"The pool is closed on Mondays.","B":"You can rent a pair at the front desk.","D":"The water feels warmer today."},"correct_answer":"B","explanation":"Đáp án đúng là (B): \"You can rent a pair at the front desk.\". Đây là câu phản xạ giao tiếp tự nhiên và chuẩn xác nhất theo ngữ cảnh văn hóa đại học Bắc Mỹ."}]}},{"id":"list13_m2_t2","title":"Task 2: Campus Conversation","task_type":"conversation","content":{"context_title":"Hội thoại sinh viên (Phần nâng cao)","audio_text":"my poster tube arrived damage after shipping and the poster inside is creased I''m sorry about that we can have the printing center that would be great will it be ready before the conference so there''s do I need to submit the file again no we still have your original proof before printing perfect I''ll review it immediately and let you know if everything looks correct great will notify you as soon as it''s printed notify you as soon as it''s printed and you can pick it up at the printing center","questions":[{"id":"list13_m2_q9","prompt":"Why does the student speak with the staff member?","options":{"A":"TO replace a damaged conference poster.","B":"TO reserve a shipping service.","C":"To request a conference registration form.","D":"To change the conference location."},"correct_answer":"A","explanation":"Đáp án (A) chính xác: \"TO replace a damaged conference poster.\". Người nói đã giải thích rõ lý do này trong đoạn ghi âm."},{"id":"list13_m2_q10","prompt":"What will the student most likely do next?","options":{"A":"Attend the conference without a poster.","B":"Approve the proof.","C":"Mail the damaged poster.","D":"Cancel the printing order."},"correct_answer":"B","explanation":"Đáp án đúng là (B): \"Approve the proof.\". Dựa vào chi tiết trực tiếp được người nói đề cập trong bài nghe."}]}},{"id":"list13_m2_t3","title":"Task 3: Campus Announcement","task_type":"announcement","content":{"context_title":"Thông báo khuôn viên trường (Phần nâng cao)","audio_text":"listen to an airport announcement passengers travelling on flight 247 to Madrid should proceed to gate 18 immediately final boarding is now in progress and the gate will close in 10 minutes if you have not yet reached the gate please make your way there without delay as the aircraft cannot wait for late passengers I cannot wait for late passengers Please be aware that any checked baggage belonging to passengers who have not boarded may be removed from the aircraft before departure thank you for your cooperation","questions":[{"id":"list13_m2_q11","prompt":"What is the announcement mainly about?","options":{"A":"A gate change","B":"A canceled flight","C":"Final boarding","D":"Delayed baggage"},"correct_answer":"C","explanation":"Đáp án chính xác là (C): \"Final boarding\". Thông tin trọng tâm xuyên suốt bài nghe nhấn mạnh vào ý chính này."},{"id":"list13_m2_q12","prompt":"Why might baggage be removed from the aircraft?","options":{"A":"It belongs to absent passengers","B":"It exceeds weight limits","C":"It was labeled incorrectly","D":"It contains prohibited items"},"correct_answer":"A","explanation":"Đáp án (A) chính xác: \"It belongs to absent passengers\". Người nói đã giải thích rõ lý do này trong đoạn ghi âm."}]}},{"id":"list13_m2_t4","title":"Task 4: Academic Lecture 1","task_type":"academic_talk","content":{"context_title":"Bài giảng học thuật 1 (HARD Module)","audio_text":"listen to part of an archeology class archaeologists to determine the age of objects and structures discovered at excavation sites establishing accurate dates helps researchers understand when people lived in an area and how their activities changed over time some methods estimate age some methods estimate age by examining an object''s position within layers of soil While others analyze the physical or chemical properties of the material itself one widely used technique is radiocarbon dating which can be applied to organic materials such as wood bone and plant remains while an organism is alive while an organism is alive it contains a particular form of carbon after it dies the amount of this carbon gradually decreases at a predictable rate by measuring how much remains scientists can estimate when the organism died however radiocarbon dating has limitations it cannot be used to directly date materials such materials such as most Stone objects and it becomes less reliable when extremely old materials are examined therefore archaeologists often combined several dating methods to obtain more reliable results","questions":[{"id":"list13_m2_q13","prompt":"What is the talk mainly about?","options":{"A":"The reasons archaeological excavation sites are difficult to","B":"Methods archaeologists use to determine the age Of","C":"The chemical differences between organic and inorganic","D":"Changes in the methods used to study ancient civilizations"},"correct_answer":"B","explanation":"Đáp án chính xác là (B): \"Methods archaeologists use to determine the age Of\". Thông tin trọng tâm xuyên suốt bài nghe nhấn mạnh vào ý chính này."},{"id":"list13_m2_q14","prompt":"According to the speaker, what happens to carbon after an organism dies?","options":{"A":"It increases at a predictable rate.","B":"It disappears immediately from the organism''s remains.","C":"It gradually decreases at a predictable rate.","D":"It becomes concentrated in the surrounding soil."},"correct_answer":"C","explanation":"Đáp án đúng là (C): \"It gradually decreases at a predictable rate.\". Dựa vào chi tiết trực tiếp được người nói đề cập trong bài nghe."},{"id":"list13_m2_q15","prompt":"Why does the speaker mention stone objects?","options":{"A":"TO explain why some archaeological materials cannot be dated","B":"TO describe the materials most frequently found at excavation sites","C":"TO show how ancient people transported heavy objects","D":"TO compare stone objects with wooden structures"},"correct_answer":"A","explanation":"Đáp án (A) chính xác: \"TO explain why some archaeological materials cannot be dated\". Người nói đã giải thích rõ lý do này trong đoạn ghi âm."},{"id":"list13_m2_q16","prompt":"What does the speaker imply about archaeological dating?","options":{"A":"A single dating technique is usually sufficient to establish an exact age.","B":"Radiocarbon dating is more accurate when used on very Old materials.","C":"Researchers can often improve the reliability of their conclusions by","D":"The position of an object in the soil is more useful than its chemical"},"correct_answer":"C","explanation":"Đáp án đúng là (C): \"Researchers can often improve the reliability of their conclusions by\". Đây là suy luận hợp lý nhất từ các chi tiết ngầm định của người nói."}]}},{"id":"list13_m2_t5","title":"Task 5: Academic Lecture 2","task_type":"academic_talk","content":{"context_title":"Bài giảng học thuật 2 (HARD Module)","audio_text":"listen to part of an earth science class volcanic eruptions can be difficult to predict precisely but scientists monitor several warning signs that may indicate changes within a volcano one important sign is increased seismic activity as magma moves beneath the surface check my moods beneath the surface it can produce more earthquakes or vibrations that monitoring instruments can detect scientists also monitor changes in volcanic gases magma contains gases that can escape through openings in the Earth''s crust changes in the amount or composition of these gases May provide mission of these gases May provide information about what is happening underground researchers may also observe changes in the shape of a volcano as accumulating magma can cause parts of it to expand slightly modern monitoring systems combine information from several sources instruments can measure ground movement movement seismic activity and gas emissions while satellite images can detect changes in the shape or temperature of volcanic areas by comparing measurements over time researchers can identify unusual patterns however monitoring cannot determine exactly will it rain cannot determine exactly when an eruption will occur some warning signs appear without an eruption While others may occur with little warning therefore monitoring mainly helps authorities assess volcanic activity and prepare for possible emergencies","questions":[{"id":"list13_m2_q17","prompt":"What is the talk mainly about?","options":{"A":"The long-term effects of volcanic eruptions on nearby communities","B":"How scientists monitor volcanoes for signs of increased activity","C":"Why volcanic gases are more dangerous than other natural gases","D":"The differences between active and inactive volcanoes"},"correct_answer":"B","explanation":"Đáp án chính xác là (B): \"How scientists monitor volcanoes for signs of increased activity\". Thông tin trọng tâm xuyên suốt bài nghe nhấn mạnh vào ý chính này."},{"id":"list13_m2_q18","prompt":"According to the speaker, what may happen when magma moves beneath a volcano?","options":{"A":"Small earthquakes or vibrations may occur.","B":"The surrounding temperature may decrease significantly.","C":"Volcanic gases may disappear completely.","D":"The volcano may immediately begin to erupt."},"correct_answer":"A","explanation":"Đáp án đúng là (A): \"Small earthquakes or vibrations may occur.\". Dựa vào chi tiết trực tiếp được người nói đề cập trong bài nghe."},{"id":"list13_m2_q19","prompt":"Why does the speaker mention satellite images?","options":{"A":"To explain how scientists locate underground magma directly","B":"To provide an example of technology used to detect changes","C":"TO compare volcanic activity in different countries","D":"To show why ground-based instruments are no longer"},"correct_answer":"B","explanation":"Đáp án (B) chính xác: \"To provide an example of technology used to detect changes\". Người nói đã giải thích rõ lý do này trong đoạn ghi âm."},{"id":"list13_m2_q20","prompt":"What does the speaker imply about the purpose of volcanic monitoring?","options":{"A":"It allows scientists to prevent eruptions from occurring.","B":"It is useful only when an eruption is already underway.","C":"It helps authorities make informed decisions about possible emergencies.","D":"It can reliably predict eruptions several days in advance."},"correct_answer":"C","explanation":"Đáp án chính xác là (C): \"It helps authorities make informed decisions about possible emergencies.\". Thông tin trọng tâm xuyên suốt bài nghe nhấn mạnh vào ý chính này."}]}}]}],"description":"Bộ đề TOEFL iBT Listening 2026 chuẩn ETS. Chủ đề trọng tâm: Group study, Internship applications, Volcanic hazard monitoring, Global economic shifts. Gồm Module 1 (14.5 phút) và Module 2 (14.5 phút - Adaptive) với đầy đủ phản xạ hội thoại, thông báo và bài giảng học thuật.","youtube_url":"https://www.youtube.com/watch?v=YldsVHEM0O0","source":"YouTube TOEFL 2026 Listening Practice 13","created_at_ms":1791231607971}'::jsonb,
  timezone('utc'::text, now())
)
