tion_seconds":480,"tasks":[{"id":"gabble_ctw_12_task_1","title":"GabbleAI - Terrace Farming in Mountainous Regions","task_type":"complete_words","content":{"instructions":"Complete the words by filling in the missing letters.","blanks":[{"index":1,"prefix":"plat","missing":"forms","fullWord":"platforms","missingLength":5,"pos":"Noun","hint":"Danh từ số nhiều ''những bậc thềm/bình đài này''"},{"index":2,"prefix":"infil","missing":"trate","fullWord":"infiltrate","missingLength":5,"pos":"Verb","hint":"Động từ nguyên mẫu ''cho phép nước ngấm/thấm vào đất''"},{"index":3,"prefix":"grad","missing":"ually","fullWord":"gradually","missingLength":5,"pos":"Adverb","hint":"Trạng từ ''thấm vào đất một cách từ từ/dần dần''"},{"index":4,"prefix":"comb","missing":"ined","fullWord":"combined","missingLength":4,"pos":"Verb","hint":"Động từ quá khứ ''người Inca đã kết hợp ruộng bậc thang''"},{"index":5,"prefix":"chan","missing":"nels","fullWord":"channels","missingLength":4,"pos":"Noun","hint":"Danh từ số nhiều ''với các mương/kênh dẫn lót đá''"},{"index":6,"prefix":"impr","missing":"oved","fullWord":"improved","missingLength":4,"pos":"Verb","hint":"Động từ quá khứ ''cải thiện khả năng thoát nước''"},{"index":7,"prefix":"agron","missing":"omists","fullWord":"agronomists","missingLength":6,"pos":"Noun","hint":"Danh từ số nhiều ''các nhà nông học ngày nay''"},{"index":8,"prefix":"agric","missing":"ulture","fullWord":"agriculture","missingLength":6,"pos":"Noun","hint":"Danh từ ''mô hình cho nền nông nghiệp kiên cường''"},{"index":9,"prefix":"commu","missing":"nities","fullWord":"communities","missingLength":6,"pos":"Noun","hint":"Danh từ số nhiều ''một số cộng đồng vẫn duy trì chúng''"},{"index":10,"prefix":"techn","missing":"iques","fullWord":"techniques","missingLength":5,"pos":"Noun","hint":"Danh từ số nhiều ''bằng các kỹ thuật gia truyền''"}]}}]}]}'::jsonb,
  timezone('utc'::text, now())
)
