INSERT INTO public.tests (id, title, skill, task_type, duration_seconds, content, created_at)
VALUES (
  'writing-practice-01',
  'Writing Practice Test 01 (TOEFL 2026 - Speaker Unable to Attend & Expanding Bike Lane Networks)',
  'writing',
  'build_sentence',
  1380,
  '{"id": "writing-practice-01", "title": "Writing Practice Test 01 (TOEFL 2026 - Speaker Unable to Attend & Expanding Bike Lane Networks)", "skill": "writing", "is_default": true, "duration_seconds": 1380, "description": "Bộ đề luyện thi TOEFL Writing 2026 chuẩn ETS: Task 1 (10 câu Build a Sentence có ngữ cảnh giao tiếp), Task 2 (Write an Email: Speaker Unable to Attend), Task 3 (Academic Discussion: Expanding Bike Lane Networks).", "stages": [{"id": "wp1_stage_1", "title": "Writing Section (Linear - 23 Mins)", "duration_seconds": 1380, "tasks": [{"id": "wp1_t1_build_sentence", "title": "Task 1: Build a Sentence (10 câu)", "task_type": "build_sentence", "content": {"instructions": "Mỗi câu có 1 câu ngữ cảnh ban đầu (Conversational Context). Kéo thả hoặc bấm chọn các khối từ bên dưới để ghép thành câu phản hồi hoàn chỉnh, đúng ngữ pháp chuẩn ETS. Chú ý có thể có từ bẫy không được dùng.", "items": [{"id": "wp1_t1_item1", "context": "I can''t believe how hot it is today.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["outside", "today", "it", "is", "many", "degrees", "How"], "correct_order": ["How", "many", "degrees", "is", "it", "outside", "today"], "correct_sentence": "How many degrees is it outside today?", "decoys": []}, {"id": "wp1_t1_item2", "context": "You are going to the bookstore this afternoon, right?", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["get", "you", "want", "Do", "you", "me", "to", "anything"], "correct_order": ["Do", "you", "want", "me", "to", "get", "you", "anything"], "correct_sentence": "Do you want me to get you anything?", "decoys": []}, {"id": "wp1_t1_item3", "context": "Did you hear any news about Tom?", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["got", "a", "He", "city", "new", "the", "job", "in"], "correct_order": ["He", "got", "a", "new", "job", "in", "the", "city"], "correct_sentence": "He got a new job in the city.", "decoys": []}, {"id": "wp1_t1_item4", "context": "I''m thinking of redecorating my room.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["colors", "are", "going", "you", "to", "What", "choose"], "correct_order": ["What", "colors", "are", "you", "going", "to", "choose"], "correct_sentence": "What colors are you going to choose?", "decoys": []}, {"id": "wp1_t1_item5", "context": "I can''t find my phone anywhere.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["I", "table", "last", "kitchen", "saw", "on", "the", "it"], "correct_order": ["I", "saw", "it", "on", "the", "kitchen", "table", "last"], "correct_sentence": "I saw it on the kitchen table last.", "decoys": []}, {"id": "wp1_t1_item6", "context": "I''m so tired after work.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["little", "should", "nap", "Maybe", "take", "you", "a"], "correct_order": ["Maybe", "you", "should", "take", "a", "little", "nap"], "correct_sentence": "Maybe you should take a little nap.", "decoys": []}, {"id": "wp1_t1_item7", "context": "I really liked the lecture this morning.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["the", "in", "professor", "Who", "was"], "correct_order": ["Who", "was", "the", "professor"], "correct_sentence": "Who was the professor?", "decoys": ["in"]}, {"id": "wp1_t1_item8", "context": "I might join the gym near campus.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["any", "your", "already", "members", "friends", "Are", "of"], "correct_order": ["Are", "any", "of", "your", "friends", "members", "already"], "correct_sentence": "Are any of your friends members already?", "decoys": []}, {"id": "wp1_t1_item9", "context": "My parents are visiting next week.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["for", "long", "are", "they", "staying", "How"], "correct_order": ["How", "long", "are", "they", "staying"], "correct_sentence": "How long are they staying?", "decoys": ["for"]}, {"id": "wp1_t1_item10", "context": "The bakery downtown just reopened.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["they", "offering", "What", "types", "bread", "are", "of"], "correct_order": ["What", "types", "of", "bread", "are", "they", "offering"], "correct_sentence": "What types of bread are they offering?", "decoys": []}]}}, {"id": "wp1_t2_write_email", "title": "Task 2: Write an Email", "task_type": "write_email", "content": {"recipient": "Club members", "subject_hint": "Speaker Unable to Attend", "scenario": "You are the president of your university''s photography club. The club booked a guest speaker, but the speaker just canceled. Write an email to the club members.", "requirements": ["Explain the situation.", "Apologize for the inconvenience.", "Suggest an alternative activity for the meeting."], "min_words": 80, "recommended_words": "100 - 130 words"}}, {"id": "wp1_t3_academic_discussion", "title": "Task 3: Academic Discussion", "task_type": "academic_discussion", "content": {"course": "Sustainability & Urban Planning", "topic": "Expanding Bike Lane Networks", "professor_prompt": {"name": "Dr. Miller", "title": "Professor of Urban Planning", "question": "Many cities are investing in bike lanes to encourage cycling as a healthier and more environmentally friendly alternative to driving. Supporters argue that bike lanes reduce traffic, improve air quality, and promote exercise. Critics say they take up valuable road space and can cause accidents when cars and bikes mix. Do you think cities should continue to expand bike lane networks, or should they focus on other forms of transportation?"}, "peer_posts": [{"student": "Rachel", "avatar_bg": "bg-emerald-600", "stance": "I think cities should continue to expand bike lanes because cycling is one of the cleanest forms of transport. It reduces pollution and helps people improve their health at the same time."}, {"student": "Marcus", "avatar_bg": "bg-blue-600", "stance": "I don''t think expanding bike lanes should be the priority for most cities. Not everyone is able or willing to cycle, especially in places with bad weather or long commuting distances. Cities should invest more in public transport, which can benefit a larger number of people."}], "min_words": 100, "recommended_words": "100 - 150 words"}}]}]}'::jsonb,
  timezone('utc'::text, now())
)
ON CONFLICT (id) DO UPDATE SET
  title = EXCLUDED.title,
  skill = EXCLUDED.skill,
  task_type = EXCLUDED.task_type,
  duration_seconds = EXCLUDED.duration_seconds,
  content = EXCLUDED.content;

INSERT INTO public.tests (id, title, skill, task_type, duration_seconds, content, created_at)
VALUES (
  'writing-practice-02',
  'Writing Practice Test 02 (TOEFL 2026 - Study Room Reservation & The Four-Day Workweek)',
  'writing',
  'build_sentence',
  1380,
  '{"id": "writing-practice-02", "title": "Writing Practice Test 02 (TOEFL 2026 - Study Room Reservation & The Four-Day Workweek)", "skill": "writing", "is_default": true, "duration_seconds": 1380, "description": "Bộ đề luyện thi TOEFL Writing 2026 chuẩn ETS: Task 1 (10 câu Build a Sentence có ngữ cảnh giao tiếp), Task 2 (Write an Email: Study Room Reservation), Task 3 (Academic Discussion: The Four-Day Workweek).", "stages": [{"id": "wp2_stage_1", "title": "Writing Section (Linear - 23 Mins)", "duration_seconds": 1380, "tasks": [{"id": "wp2_t1_build_sentence", "title": "Task 1: Build a Sentence (10 câu)", "task_type": "build_sentence", "content": {"instructions": "Mỗi câu có 1 câu ngữ cảnh ban đầu (Conversational Context). Kéo thả hoặc bấm chọn các khối từ bên dưới để ghép thành câu phản hồi hoàn chỉnh, đúng ngữ pháp chuẩn ETS. Chú ý có thể có từ bẫy không được dùng.", "items": [{"id": "wp2_t1_item1", "context": "We need to prepare for tomorrow''s biology presentation.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["have", "could", "tonight", "We", "session", "study", "a"], "correct_order": ["We", "could", "have", "a", "study", "session", "tonight"], "correct_sentence": "We could have a study session tonight.", "decoys": []}, {"id": "wp2_t1_item2", "context": "I''m thinking of trying that new Italian restaurant downtown.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["there", "been", "Have", "ever", "you"], "correct_order": ["Have", "you", "ever", "been", "there"], "correct_sentence": "Have you ever been there?", "decoys": []}, {"id": "wp2_t1_item3", "context": "My sister is getting married next month.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["is", "the", "wedding", "held", "Where"], "correct_order": ["Where", "is", "the", "wedding", "held"], "correct_sentence": "Where is the wedding held?", "decoys": []}, {"id": "wp2_t1_item4", "context": "I accidentally dropped my favorite coffee mug this morning.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["You", "could", "get", "store", "another", "the", "at", "one"], "correct_order": ["You", "could", "get", "another", "one", "at", "the", "store"], "correct_sentence": "You could get another one at the store.", "decoys": []}, {"id": "wp2_t1_item5", "context": "I don''t think everyone can make it to the office today.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["online", "meeting", "have", "instead", "We''ll", "an"], "correct_order": ["We''ll", "have", "an", "online", "meeting", "instead"], "correct_sentence": "We''ll have an online meeting instead.", "decoys": []}, {"id": "wp2_t1_item6", "context": "I decided to look for a summer internship.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["are", "going", "you", "apply", "to", "Where"], "correct_order": ["Where", "are", "you", "going", "to", "apply"], "correct_sentence": "Where are you going to apply?", "decoys": []}, {"id": "wp2_t1_item7", "context": "My brother just moved into his new apartment.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["does", "much", "he", "How", "pay", "rent"], "correct_order": ["How", "much", "rent", "does", "he", "pay"], "correct_sentence": "How much rent does he pay?", "decoys": []}, {"id": "wp2_t1_item8", "context": "The concert last night was amazing.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["do", "you", "another", "they", "have", "concert", "think", "will", "When"], "correct_order": ["When", "do", "you", "think", "they", "will", "have", "another", "concert"], "correct_sentence": "When do you think they will have another concert?", "decoys": []}, {"id": "wp2_t1_item9", "context": "I need to print out my research paper before class.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["second", "the", "on", "The", "floor", "are", "printers"], "correct_order": ["The", "printers", "are", "on", "the", "second", "floor"], "correct_sentence": "The printers are on the second floor.", "decoys": []}, {"id": "wp2_t1_item10", "context": "We went to that new seafood restaurant yesterday.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["dish", "favorite", "was", "your", "What", "there"], "correct_order": ["What", "was", "your", "favorite", "dish", "there"], "correct_sentence": "What was your favorite dish there?", "decoys": []}]}}, {"id": "wp2_t2_write_email", "title": "Task 2: Write an Email", "task_type": "write_email", "content": {"recipient": "Library staff", "subject_hint": "Study Room Reservation", "scenario": "You reserved a study room in the library, but when you arrived, it was already occupied. Write an email to the library staff.", "requirements": ["Describe the problem.", "Explain why you need the room.", "Ask for a solution."], "min_words": 80, "recommended_words": "100 - 130 words"}}, {"id": "wp2_t3_academic_discussion", "title": "Task 3: Academic Discussion", "task_type": "academic_discussion", "content": {"course": "Social Studies & Labor Economics", "topic": "The Four-Day Workweek", "professor_prompt": {"name": "Dr. Evans", "title": "Professor of Economics", "question": "Some countries have recently shortened the standard workweek to four days instead of five. Supporters say this leads to better work-life balance, higher productivity, and happier employees. Critics worry that it could harm businesses and reduce overall output. Do you think a four-day workweek is a good idea? Why or why not?"}, "peer_posts": [{"student": "Alex", "avatar_bg": "bg-emerald-600", "stance": "I think a four-day workweek is a great idea because people are more productive when they rest more. Working fewer but more focused days can improve results and give employees more time for family and relaxation."}, {"student": "David", "avatar_bg": "bg-amber-600", "stance": "I don''t support a shorter workweek because some industries need constant attention. Paying the same salary for fewer hours could hurt businesses, and some employees might still work long, stressful days."}], "min_words": 100, "recommended_words": "100 - 150 words"}}]}]}'::jsonb,
  timezone('utc'::text, now())
)
ON CONFLICT (id) DO UPDATE SET
  title = EXCLUDED.title,
  skill = EXCLUDED.skill,
  task_type = EXCLUDED.task_type,
  duration_seconds = EXCLUDED.duration_seconds,
  content = EXCLUDED.content;

INSERT INTO public.tests (id, title, skill, task_type, duration_seconds, content, created_at)
VALUES (
  'writing-practice-03',
  'Writing Practice Test 03 (TOEFL 2026 - Extra Credit Opportunity Inquiry & Government Incentives for Larger Families)',
  'writing',
  'build_sentence',
  1380,
  '{"id": "writing-practice-03", "title": "Writing Practice Test 03 (TOEFL 2026 - Extra Credit Opportunity Inquiry & Government Incentives for Larger Families)", "skill": "writing", "is_default": true, "duration_seconds": 1380, "description": "Bộ đề luyện thi TOEFL Writing 2026 chuẩn ETS: Task 1 (10 câu Build a Sentence có ngữ cảnh giao tiếp), Task 2 (Write an Email: Extra Credit Opportunity Inquiry), Task 3 (Academic Discussion: Government Incentives for Larger Families).", "stages": [{"id": "wp3_stage_1", "title": "Writing Section (Linear - 23 Mins)", "duration_seconds": 1380, "tasks": [{"id": "wp3_t1_build_sentence", "title": "Task 1: Build a Sentence (10 câu)", "task_type": "build_sentence", "content": {"instructions": "Mỗi câu có 1 câu ngữ cảnh ban đầu (Conversational Context). Kéo thả hoặc bấm chọn các khối từ bên dưới để ghép thành câu phản hồi hoàn chỉnh, đúng ngữ pháp chuẩn ETS. Chú ý có thể có từ bẫy không được dùng.", "items": [{"id": "wp3_t1_item1", "context": "The campus library has new opening hours.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["hours", "about", "What", "Saturdays", "on", "opening", "its"], "correct_order": ["What", "about", "its", "opening", "hours", "on", "Saturdays"], "correct_sentence": "What about its opening hours on Saturdays?", "decoys": []}, {"id": "wp3_t1_item2", "context": "I need to buy a few things for this weekend.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["something", "you", "planning", "Have", "been"], "correct_order": ["Have", "you", "been", "planning", "something"], "correct_sentence": "Have you been planning something?", "decoys": []}, {"id": "wp3_t1_item3", "context": "I want to visit the career center tomorrow.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["make", "to", "you", "an", "need", "appointment", "Do"], "correct_order": ["Do", "you", "need", "to", "make", "an", "appointment"], "correct_sentence": "Do you need to make an appointment?", "decoys": []}, {"id": "wp3_t1_item4", "context": "The photography club is accepting new members.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["Do", "it", "idea", "good", "join", "be", "a", "would", "think", "you", "to"], "correct_order": ["Do", "you", "think", "it", "would", "be", "a", "good", "idea", "to", "join"], "correct_sentence": "Do you think it would be a good idea to join?", "decoys": []}, {"id": "wp3_t1_item5", "context": "I found a great article for our history presentation.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["with", "me", "share", "you", "the", "link", "Could"], "correct_order": ["Could", "you", "share", "the", "link", "with", "me"], "correct_sentence": "Could you share the link with me?", "decoys": []}, {"id": "wp3_t1_item6", "context": "You look really exhausted this morning.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["yesterday", "up", "late", "stay", "you", "Did"], "correct_order": ["Did", "you", "stay", "up", "late", "yesterday"], "correct_sentence": "Did you stay up late yesterday?", "decoys": []}, {"id": "wp3_t1_item7", "context": "I saw Lisa at the administration office earlier.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["there", "doing", "was", "What", "she"], "correct_order": ["What", "was", "she", "doing", "there"], "correct_sentence": "What was she doing there?", "decoys": []}, {"id": "wp3_t1_item8", "context": "We need to discuss our group project schedule.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["it", "pm", "for", "work", "you", "went", "after", "we", "6:00", "if", "Would"], "correct_order": ["Would", "it", "work", "for", "you", "if", "we", "went", "after", "6:00", "pm"], "correct_sentence": "Would it work for you if we went after 6:00 pm?", "decoys": []}, {"id": "wp3_t1_item9", "context": "We need to tidy up the living room before the guests arrive.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["least", "need", "everything", "to", "think", "I", "hour", "you", "clean", "will", "at", "an"], "correct_order": ["I", "think", "you", "will", "need", "at", "least", "an", "hour", "to", "clean", "everything"], "correct_sentence": "I think you will need at least an hour to clean everything.", "decoys": []}, {"id": "wp3_t1_item10", "context": "I want to have a quick lunch before my next lecture.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["know", "around", "Do", "here", "place", "a", "you", "good"], "correct_order": ["Do", "you", "know", "a", "good", "place", "around", "here"], "correct_sentence": "Do you know a good place around here?", "decoys": []}]}}, {"id": "wp3_t2_write_email", "title": "Task 2: Write an Email", "task_type": "write_email", "content": {"recipient": "professor.green@university.edu", "subject_hint": "Extra Credit Opportunity Inquiry", "scenario": "Your professor has offered extra credit opportunities for your course. Write an email to your professor.", "requirements": ["Ask for details about the extra credit.", "Explain why you are interested.", "Confirm how to submit the work."], "min_words": 80, "recommended_words": "100 - 130 words"}}, {"id": "wp3_t3_academic_discussion", "title": "Task 3: Academic Discussion", "task_type": "academic_discussion", "content": {"course": "Public Policy & Demographics", "topic": "Government Incentives for Larger Families", "professor_prompt": {"name": "Dr. Watson", "title": "Professor of Public Policy", "question": "Some governments offer financial incentives for families to have more children because of aging populations. Supporters argue this helps balance society and ensures enough workers in the future. Critics say it puts pressure on families and doesn''t address deeper social issues. Should governments encourage larger families?"}, "peer_posts": [{"student": "Maya", "avatar_bg": "bg-violet-600", "stance": "I think governments should encourage larger families because declining birth rates threaten economies. Incentives like childcare support and housing benefits can make family life easier and ensure long-term stability."}, {"student": "Lucas", "avatar_bg": "bg-rose-600", "stance": "I don''t think encouraging larger families is the best solution. High costs, lack of support, and career pressures stop people from having children. Governments should improve working conditions and gender equality instead."}], "min_words": 100, "recommended_words": "100 - 150 words"}}]}]}'::jsonb,
  timezone('utc'::text, now())
)
ON CONFLICT (id) DO UPDATE SET
  title = EXCLUDED.title,
  skill = EXCLUDED.skill,
  task_type = EXCLUDED.task_type,
  duration_seconds = EXCLUDED.duration_seconds,
  content = EXCLUDED.content;

INSERT INTO public.tests (id, title, skill, task_type, duration_seconds, content, created_at)
VALUES (
  'writing-practice-04',
  'Writing Practice Test 04 (TOEFL 2026 - Apology about the textbook & Personal Identity: Fixed or Flexible?)',
  'writing',
  'build_sentence',
  1380,
  '{"id": "writing-practice-04", "title": "Writing Practice Test 04 (TOEFL 2026 - Apology about the textbook & Personal Identity: Fixed or Flexible?)", "skill": "writing", "is_default": true, "duration_seconds": 1380, "description": "Bộ đề luyện thi TOEFL Writing 2026 chuẩn ETS: Task 1 (10 câu Build a Sentence có ngữ cảnh giao tiếp), Task 2 (Write an Email: Apology about the textbook), Task 3 (Academic Discussion: Personal Identity: Fixed or Flexible?).", "stages": [{"id": "wp4_stage_1", "title": "Writing Section (Linear - 23 Mins)", "duration_seconds": 1380, "tasks": [{"id": "wp4_t1_build_sentence", "title": "Task 1: Build a Sentence (10 câu)", "task_type": "build_sentence", "content": {"instructions": "Mỗi câu có 1 câu ngữ cảnh ban đầu (Conversational Context). Kéo thả hoặc bấm chọn các khối từ bên dưới để ghép thành câu phản hồi hoàn chỉnh, đúng ngữ pháp chuẩn ETS. Chú ý có thể có từ bẫy không được dùng.", "items": [{"id": "wp4_t1_item1", "context": "Has the survey report been completed yet?", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["data", "is", "missing", "still", "Some"], "correct_order": ["Some", "data", "is", "still", "missing"], "correct_sentence": "Some data is still missing.", "decoys": []}, {"id": "wp4_t1_item2", "context": "The project launch was postponed again.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["for", "Who", "responsible", "is", "this", "delay"], "correct_order": ["Who", "is", "responsible", "for", "this", "delay"], "correct_sentence": "Who is responsible for this delay?", "decoys": []}, {"id": "wp4_t1_item3", "context": "Did the guest speaker confirm her arrival time?", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["did", "she", "say", "would", "she", "come", "When"], "correct_order": ["When", "did", "she", "say", "she", "would", "come"], "correct_sentence": "When did she say she would come?", "decoys": []}, {"id": "wp4_t1_item4", "context": "I sent an inquiry to the vendor three days ago.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["a", "no", "is", "been", "good", "That", "response", "if", "received", "idea", "has"], "correct_order": ["That", "is", "a", "good", "idea", "if", "no", "response", "has", "been", "received"], "correct_sentence": "That is a good idea if no response has been received.", "decoys": []}, {"id": "wp4_t1_item5", "context": "How does the new tablet model compare to the previous version?", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["It", "the", "than", "one", "fewer", "was", "features", "released", "last", "has", "year", "that"], "correct_order": ["It", "has", "fewer", "features", "than", "the", "one", "that", "was", "released", "last", "year"], "correct_sentence": "It has fewer features than the one that was released last year.", "decoys": []}, {"id": "wp4_t1_item6", "context": "I''m thinking of registering for the advanced programming seminar.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["what", "you", "the", "course", "requires", "skills", "Could", "explain"], "correct_order": ["Could", "you", "explain", "what", "skills", "the", "course", "requires"], "correct_sentence": "Could you explain what skills the course requires?", "decoys": []}, {"id": "wp4_t1_item7", "context": "Has professor Davis reviewed Maria''s research paper?", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["feedback", "submitted", "Yes", "she", "assignment", "that", "the", "received", "excellent"], "correct_order": ["Yes", "the", "assignment", "that", "she", "submitted", "received", "excellent", "feedback"], "correct_sentence": "Yes, the assignment that she submitted received excellent feedback.", "decoys": []}, {"id": "wp4_t1_item8", "context": "My grandfather went to see his physician yesterday.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["doctor", "he", "intake", "sugar", "his", "suggested", "The", "reduce", "that"], "correct_order": ["The", "doctor", "suggested", "that", "he", "reduce", "his", "sugar", "intake"], "correct_sentence": "The doctor suggested that he reduce his sugar intake.", "decoys": []}, {"id": "wp4_t1_item9", "context": "Why did you bring your laptop to the technical support center?", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["is", "I", "year", "The", "laptop", "bought", "malfunctioning", "that", "already", "last"], "correct_order": ["The", "laptop", "that", "I", "bought", "last", "year", "is", "already", "malfunctioning"], "correct_sentence": "The laptop that I bought last year is already malfunctioning.", "decoys": []}, {"id": "wp4_t1_item10", "context": "What was the scientist''s reaction to the unexpected experiment outcome?", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["trusted", "whether", "the", "be", "He", "results", "wondered", "could"], "correct_order": ["He", "wondered", "whether", "the", "results", "could", "be", "trusted"], "correct_sentence": "He wondered whether the results could be trusted.", "decoys": []}]}}, {"id": "wp4_t2_write_email", "title": "Task 2: Write an Email", "task_type": "write_email", "content": {"recipient": "Mia", "subject_hint": "Apology about the textbook", "scenario": "You borrowed a textbook from your classmate, Mia, but accidentally spilled coffee on it while you were having lunch at the cafeteria. Write an email to Mia.", "requirements": ["Explain what happened.", "Offer to replace or repair the book.", "Apologize for the inconvenience."], "min_words": 80, "recommended_words": "100 - 130 words"}}, {"id": "wp4_t3_academic_discussion", "title": "Task 3: Academic Discussion", "task_type": "academic_discussion", "content": {"course": "Psychology & Philosophy of Mind", "topic": "Personal Identity: Fixed or Flexible?", "professor_prompt": {"name": "Dr. Campbell", "title": "Professor of Psychology", "question": "Our topic today is personal identity. Some philosophers argue that identity is stable and continuous over time, meaning that a person remains essentially the same despite changes in circumstances. Others claim that identity constantly evolves due to experiences, relationships, culture, and social influences. Considering these perspectives, would you say identity is fixed or flexible?"}, "peer_posts": [{"student": "Taylor", "avatar_bg": "bg-indigo-600", "stance": "I believe identity is flexible because people gradually change their beliefs, values, and behaviors as they gain new experiences and interact with different environments. Over time, relationships, education, and challenges reshape how individuals see themselves."}, {"student": "Jean", "avatar_bg": "bg-teal-600", "stance": "I think there is a stable core personality that remains consistent despite external changes and new experiences. Although people may adapt their behavior to different situations, their fundamental traits and basic character tend to stay the same."}], "min_words": 100, "recommended_words": "100 - 150 words"}}]}]}'::jsonb,
  timezone('utc'::text, now())
)
ON CONFLICT (id) DO UPDATE SET
  title = EXCLUDED.title,
  skill = EXCLUDED.skill,
  task_type = EXCLUDED.task_type,
  duration_seconds = EXCLUDED.duration_seconds,
  content = EXCLUDED.content;

INSERT INTO public.tests (id, title, skill, task_type, duration_seconds, content, created_at)
VALUES (
  'writing-practice-05',
  'Writing Practice Test 05 (TOEFL 2026 - Request for course information & Nature vs. Nurture in Intelligence)',
  'writing',
  'build_sentence',
  1380,
  '{"id": "writing-practice-05", "title": "Writing Practice Test 05 (TOEFL 2026 - Request for course information & Nature vs. Nurture in Intelligence)", "skill": "writing", "is_default": true, "duration_seconds": 1380, "description": "Bộ đề luyện thi TOEFL Writing 2026 chuẩn ETS: Task 1 (10 câu Build a Sentence có ngữ cảnh giao tiếp), Task 2 (Write an Email: Request for course information), Task 3 (Academic Discussion: Nature vs. Nurture in Intelligence).", "stages": [{"id": "wp5_stage_1", "title": "Writing Section (Linear - 23 Mins)", "duration_seconds": 1380, "tasks": [{"id": "wp5_t1_build_sentence", "title": "Task 1: Build a Sentence (10 câu)", "task_type": "build_sentence", "content": {"instructions": "Mỗi câu có 1 câu ngữ cảnh ban đầu (Conversational Context). Kéo thả hoặc bấm chọn các khối từ bên dưới để ghép thành câu phản hồi hoàn chỉnh, đúng ngữ pháp chuẩn ETS. Chú ý có thể có từ bẫy không được dùng.", "items": [{"id": "wp5_t1_item1", "context": "I''m interested in applying for the international exchange program.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["requirements", "you", "are", "the", "what", "Do", "know"], "correct_order": ["Do", "you", "know", "what", "the", "requirements", "are"], "correct_sentence": "Do you know what the requirements are?", "decoys": []}, {"id": "wp5_t1_item2", "context": "I''m preparing for the upcoming biology comprehensive exam.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["like", "any", "you", "Would", "recommend", "me", "resources", "to"], "correct_order": ["Would", "you", "like", "me", "to", "recommend", "any", "resources"], "correct_sentence": "Would you like me to recommend any resources?", "decoys": []}, {"id": "wp5_t1_item3", "context": "I couldn''t attend the guest lecture yesterday afternoon.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["the", "recording", "available", "is", "if", "check", "Let", "me"], "correct_order": ["Let", "me", "check", "if", "the", "recording", "is", "available"], "correct_sentence": "Let me check if the recording is available.", "decoys": []}, {"id": "wp5_t1_item4", "context": "The university housing office said the dorms are fully booked.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["there", "other", "still", "check", "Did", "you", "options", "are", "available", "if"], "correct_order": ["Did", "you", "check", "if", "there", "are", "still", "other", "options", "available"], "correct_sentence": "Did you check if there are still other options available?", "decoys": []}, {"id": "wp5_t1_item5", "context": "I want to read more about the climate research mentioned in class.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["find", "Where", "we", "report", "can", "published", "the", "full"], "correct_order": ["Where", "can", "we", "find", "the", "full", "published", "report"], "correct_sentence": "Where can we find the full published report?", "decoys": []}, {"id": "wp5_t1_item6", "context": "The finance committee is reviewing the renovation budget.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["now", "invest", "We", "wait", "should", "decide", "whether", "or", "need", "we", "to"], "correct_order": ["We", "need", "to", "decide", "whether", "we", "should", "invest", "now", "or", "wait"], "correct_sentence": "We need to decide whether we should invest now or wait.", "decoys": []}, {"id": "wp5_t1_item7", "context": "I just finished reading the sociology book assigned last week.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["you", "part", "book", "of", "most", "Which", "helpful", "find", "the", "did"], "correct_order": ["Which", "part", "of", "the", "book", "did", "you", "find", "most", "helpful"], "correct_sentence": "Which part of the book did you find most helpful?", "decoys": []}, {"id": "wp5_t1_item8", "context": "I missed the department meeting because of my chemistry lab.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["discussed", "the", "summarize", "meeting", "Please", "were", "the", "that", "points", "during", "main"], "correct_order": ["Please", "summarize", "the", "main", "points", "that", "were", "discussed", "during", "the", "meeting"], "correct_sentence": "Please summarize the main points that were discussed during the meeting.", "decoys": []}, {"id": "wp5_t1_item9", "context": "Our team has completed the preliminary market analysis.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["are", "highlight", "the", "most", "you", "Could", "significant", "which", "findings"], "correct_order": ["Could", "you", "highlight", "which", "findings", "are", "the", "most", "significant"], "correct_sentence": "Could you highlight which findings are the most significant?", "decoys": []}, {"id": "wp5_t1_item10", "context": "The results of the laboratory test were inconclusive.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["the", "different", "for", "strategy", "recommended", "They", "a", "trying", "experiment"], "correct_order": ["They", "recommended", "trying", "a", "different", "strategy", "for", "the", "experiment"], "correct_sentence": "They recommended trying a different strategy for the experiment.", "decoys": []}]}}, {"id": "wp5_t2_write_email", "title": "Task 2: Write an Email", "task_type": "write_email", "content": {"recipient": "Academic Advisor", "subject_hint": "Request for course information", "scenario": "You are interested in enrolling in a course next semester, but the course description on the university website is unclear and does not provide enough details about requirements and workload. Write an email to the academic advisor.", "requirements": ["Explain why you are interested in the course.", "Ask specific questions about requirements and expectations.", "Request additional information to help you decide."], "min_words": 80, "recommended_words": "100 - 130 words"}}, {"id": "wp5_t3_academic_discussion", "title": "Task 3: Academic Discussion", "task_type": "academic_discussion", "content": {"course": "Cognitive Psychology & Education", "topic": "Nature vs. Nurture in Intelligence", "professor_prompt": {"name": "Dr. Anderson", "title": "Professor of Cognitive Science", "question": "Psychologists continue to debate whether intelligence is largely determined by genetic factors or whether it can significantly improve through sustained effort, effective education, and enriched environments. This issue has important implications not only for educational policy but also for personal motivation and self-belief. In your view, is intelligence mostly fixed at birth, or can it meaningfully develop over time?"}, "peer_posts": [{"student": "Mina", "avatar_bg": "bg-purple-600", "stance": "I think intelligence can improve with consistent effort because practice, challenging tasks, and quality education gradually strengthen cognitive skills. When individuals actively engage in learning and problem-solving, they can expand their abilities beyond what they initially believed possible."}, {"student": "Carlos", "avatar_bg": "bg-amber-600", "stance": "I believe genetics set relatively clear limits on intelligence, even if effort and education can help to some extent. While practice may refine certain skills, a person''s overall intellectual capacity is largely influenced by inherited biological factors."}], "min_words": 100, "recommended_words": "100 - 150 words"}}]}]}'::jsonb,
  timezone('utc'::text, now())
)
ON CONFLICT (id) DO UPDATE SET
  title = EXCLUDED.title,
  skill = EXCLUDED.skill,
  task_type = EXCLUDED.task_type,
  duration_seconds = EXCLUDED.duration_seconds,
  content = EXCLUDED.content;

INSERT INTO public.tests (id, title, skill, task_type, duration_seconds, content, created_at)
VALUES (
  'writing-practice-06',
  'Writing Practice Test 06 (TOEFL 2026 - Concern about price increase & The Primary Purpose of Education)',
  'writing',
  'build_sentence',
  1380,
  '{"id": "writing-practice-06", "title": "Writing Practice Test 06 (TOEFL 2026 - Concern about price increase & The Primary Purpose of Education)", "skill": "writing", "is_default": true, "duration_seconds": 1380, "description": "Bộ đề luyện thi TOEFL Writing 2026 chuẩn ETS: Task 1 (10 câu Build a Sentence có ngữ cảnh giao tiếp), Task 2 (Write an Email: Concern about price increase), Task 3 (Academic Discussion: The Primary Purpose of Education).", "stages": [{"id": "wp6_stage_1", "title": "Writing Section (Linear - 23 Mins)", "duration_seconds": 1380, "tasks": [{"id": "wp6_t1_build_sentence", "title": "Task 1: Build a Sentence (10 câu)", "task_type": "build_sentence", "content": {"instructions": "Mỗi câu có 1 câu ngữ cảnh ban đầu (Conversational Context). Kéo thả hoặc bấm chọn các khối từ bên dưới để ghép thành câu phản hồi hoàn chỉnh, đúng ngữ pháp chuẩn ETS. Chú ý có thể có từ bẫy không được dùng.", "items": [{"id": "wp6_t1_item1", "context": "Her presentation on environmental policy went exceptionally well.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["very", "she", "Clearly", "was", "prepared"], "correct_order": ["Clearly", "she", "was", "very", "prepared"], "correct_sentence": "Clearly, she was very prepared.", "decoys": []}, {"id": "wp6_t1_item2", "context": "The meeting ended much later than scheduled.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["so", "I", "expect", "to", "didn''t", "long", "last", "it"], "correct_order": ["I", "didn''t", "expect", "it", "to", "last", "so", "long"], "correct_sentence": "I didn''t expect it to last so long.", "decoys": []}, {"id": "wp6_t1_item3", "context": "The company plans to introduce a new policy next quarter.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["affected", "employees", "How", "will", "be"], "correct_order": ["How", "will", "employees", "be", "affected"], "correct_sentence": "How will employees be affected?", "decoys": []}, {"id": "wp6_t1_item4", "context": "I''m not sure if I understood the requirements for this assignment correctly.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["you", "with", "your", "suggest", "instructor", "this", "issue", "I", "speak", "about"], "correct_order": ["I", "suggest", "you", "speak", "with", "your", "instructor", "about", "this", "issue"], "correct_sentence": "I suggest you speak with your instructor about this issue.", "decoys": []}, {"id": "wp6_t1_item5", "context": "The software update includes several new security features.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["users", "explain", "these", "protect", "protecting", "features", "help", "Please", "how"], "correct_order": ["Please", "explain", "how", "these", "features", "help", "protect", "users"], "correct_sentence": "Please explain how these features help protect users.", "decoys": ["protecting"]}, {"id": "wp6_t1_item6", "context": "We need to finish the group project before the deadline.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["divide", "We", "how", "to", "decide", "tasks", "the", "should"], "correct_order": ["We", "should", "decide", "how", "to", "divide", "the", "tasks"], "correct_sentence": "We should decide how to divide the tasks.", "decoys": []}, {"id": "wp6_t1_item7", "context": "Where will we meet to work on our group project?", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["closes", "today", "The", "caf", "we", "study", "early", "where", "usually"], "correct_order": ["The", "caf", "where", "we", "usually", "study", "closes", "early", "today"], "correct_sentence": "The café where we usually study closes early today.", "decoys": []}, {"id": "wp6_t1_item8", "context": "Why is it taking so long?", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["new", "are", "whether", "be", "policy", "will", "discussing", "They", "the", "effective"], "correct_order": ["They", "are", "discussing", "whether", "the", "new", "policy", "will", "be", "effective"], "correct_sentence": "They are discussing whether the new policy will be effective.", "decoys": []}, {"id": "wp6_t1_item9", "context": "A new documentary about global education systems was released last month.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["is", "Do", "streaming", "available", "it", "any", "on", "know", "if", "platforms", "you"], "correct_order": ["Do", "you", "know", "if", "it", "is", "available", "on", "any", "streaming", "platforms"], "correct_sentence": "Do you know if it is available on any streaming platforms?", "decoys": []}, {"id": "wp6_t1_item10", "context": "Do you know anyone here?", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["famous", "a", "woman", "a", "blue", "engineer", "wearing", "very", "is", "dress", "The"], "correct_order": ["The", "woman", "wearing", "a", "blue", "dress", "is", "a", "very", "famous", "engineer"], "correct_sentence": "The woman wearing a blue dress is a very famous engineer.", "decoys": []}]}}, {"id": "wp6_t2_write_email", "title": "Task 2: Write an Email", "task_type": "write_email", "content": {"recipient": "Student Council", "subject_hint": "Concern about price increase", "scenario": "Your campus café increased its prices. Because the café is a popular and convenient place for students to buy meals between classes, many students are now discussing the higher prices and expressing concerns about affordability. Write an email to the student council.", "requirements": ["Describe the problem.", "Share student opinions.", "Suggest possible solutions."], "min_words": 80, "recommended_words": "100 - 130 words"}}, {"id": "wp6_t3_academic_discussion", "title": "Task 3: Academic Discussion", "task_type": "academic_discussion", "content": {"course": "Philosophy of Education", "topic": "The Primary Purpose of Education", "professor_prompt": {"name": "Dr. Reynolds", "title": "Professor of Education", "question": "Philosophers have long debated the primary purpose of education. Some argue that education should mainly prepare individuals for the workforce and economic productivity, while others believe its central goal is to cultivate critical thinking, ethical awareness, and personal development. Given these differing perspectives, which purpose of education do you consider more important?"}, "peer_posts": [{"student": "Hannah", "avatar_bg": "bg-emerald-600", "stance": "Education should prioritize critical thinking because this skill is valuable in every aspect of life. Individuals who think critically can solve problems, evaluate information carefully, and adapt successfully to changing circumstances."}, {"student": "Samuel", "avatar_bg": "bg-blue-600", "stance": "I believe preparing students for employment is more important since financial stability strongly influences quality of life. Education that develops practical skills helps individuals secure jobs, achieve independence, and contribute productively to society."}], "min_words": 100, "recommended_words": "100 - 150 words"}}]}]}'::jsonb,
  timezone('utc'::text, now())
)
ON CONFLICT (id) DO UPDATE SET
  title = EXCLUDED.title,
  skill = EXCLUDED.skill,
  task_type = EXCLUDED.task_type,
  duration_seconds = EXCLUDED.duration_seconds,
  content = EXCLUDED.content;

INSERT INTO public.tests (id, title, skill, task_type, duration_seconds, content, created_at)
VALUES (
  'writing-practice-07',
  'Writing Practice Test 07 (TOEFL 2026 - Request for schedule adjustment & Music as a Universal Language)',
  'writing',
  'build_sentence',
  1380,
  '{"id": "writing-practice-07", "title": "Writing Practice Test 07 (TOEFL 2026 - Request for schedule adjustment & Music as a Universal Language)", "skill": "writing", "is_default": true, "duration_seconds": 1380, "description": "Bộ đề luyện thi TOEFL Writing 2026 chuẩn ETS: Task 1 (10 câu Build a Sentence có ngữ cảnh giao tiếp), Task 2 (Write an Email: Request for schedule adjustment), Task 3 (Academic Discussion: Music as a Universal Language).", "stages": [{"id": "wp7_stage_1", "title": "Writing Section (Linear - 23 Mins)", "duration_seconds": 1380, "tasks": [{"id": "wp7_t1_build_sentence", "title": "Task 1: Build a Sentence (10 câu)", "task_type": "build_sentence", "content": {"instructions": "Mỗi câu có 1 câu ngữ cảnh ban đầu (Conversational Context). Kéo thả hoặc bấm chọn các khối từ bên dưới để ghép thành câu phản hồi hoàn chỉnh, đúng ngữ pháp chuẩn ETS. Chú ý có thể có từ bẫy không được dùng.", "items": [{"id": "wp7_t1_item1", "context": "I don''t know what brushes to buy for our art project.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["will", "work", "you", "buy", "Whichever"], "correct_order": ["Whichever", "you", "buy", "will", "work"], "correct_sentence": "Whichever you buy will work.", "decoys": []}, {"id": "wp7_t1_item2", "context": "What are we waiting for?", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["can''t", "the", "start", "We", "joins", "meeting", "everyone", "unless"], "correct_order": ["We", "can''t", "start", "the", "meeting", "unless", "everyone", "joins"], "correct_sentence": "We can''t start the meeting unless everyone joins.", "decoys": []}, {"id": "wp7_t1_item3", "context": "Is going to sleep on time that important?", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["concentration", "Getting", "improves", "enough", "sleep"], "correct_order": ["Getting", "enough", "sleep", "improves", "concentration"], "correct_sentence": "Getting enough sleep improves concentration.", "decoys": []}, {"id": "wp7_t1_item4", "context": "The deadlines are too short.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["Working", "pressure", "time", "under", "anxiety", "can", "increase"], "correct_order": ["Working", "under", "time", "pressure", "can", "increase", "anxiety"], "correct_sentence": "Working under time pressure can increase anxiety.", "decoys": []}, {"id": "wp7_t1_item5", "context": "What were you talking about with Lucy?", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["asked", "additional", "materials", "She", "we", "whether", "needed"], "correct_order": ["She", "asked", "whether", "we", "needed", "additional", "materials"], "correct_sentence": "She asked whether we needed additional materials.", "decoys": []}, {"id": "wp7_t1_item6", "context": "The professor explained the concept again during the lecture today.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["clarification", "That''s", "fully", "didn''t", "and", "I", "asked", "understand", "for", "it", "because"], "correct_order": ["That''s", "because", "I", "didn''t", "fully", "understand", "it", "and", "asked", "for", "clarification"], "correct_sentence": "That''s because I didn''t fully understand it and asked for clarification.", "decoys": []}, {"id": "wp7_t1_item7", "context": "Is the meeting already over?", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["continuing", "speaker", "before", "suggested", "a", "The", "short", "taking", "break"], "correct_order": ["The", "speaker", "suggested", "taking", "a", "short", "break", "before", "continuing"], "correct_sentence": "The speaker suggested taking a short break before continuing.", "decoys": []}, {"id": "wp7_t1_item8", "context": "It looks like it is going to rain.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["Unless", "the", "outdoor", "be", "the", "event", "canceled", "improves", "will", "weather"], "correct_order": ["Unless", "the", "weather", "improves", "the", "outdoor", "event", "will", "be", "canceled"], "correct_sentence": "Unless the weather improves, the outdoor event will be canceled.", "decoys": []}, {"id": "wp7_t1_item9", "context": "What materials did you use to prepare for the test?", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["resources", "by", "helpful", "The", "the", "professor", "recommended", "were", "very"], "correct_order": ["The", "resources", "recommended", "by", "the", "professor", "were", "very", "helpful"], "correct_sentence": "The resources recommended by the professor were very helpful.", "decoys": []}, {"id": "wp7_t1_item10", "context": "I have to take the exam tomorrow.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["the", "before", "your", "review", "test", "that", "notes", "recommend", "you", "I"], "correct_order": ["I", "recommend", "that", "you", "review", "your", "notes", "before", "the", "test"], "correct_sentence": "I recommend that you review your notes before the test.", "decoys": []}]}}, {"id": "wp7_t2_write_email", "title": "Task 2: Write an Email", "task_type": "write_email", "content": {"recipient": "Internship Supervisor", "subject_hint": "Request for schedule adjustment", "scenario": "You recently started an internship, but you discovered that the assigned working hours conflict with one of your required university classes. Write an email to your internship supervisor.", "requirements": ["Explain the scheduling conflict.", "Describe why both the internship and the class are important to you.", "Request a possible adjustment to your schedule."], "min_words": 80, "recommended_words": "100 - 130 words"}}, {"id": "wp7_t3_academic_discussion", "title": "Task 3: Academic Discussion", "task_type": "academic_discussion", "content": {"course": "Cultural Studies & Musicology", "topic": "Music as a Universal Language", "professor_prompt": {"name": "Dr. Gomez", "title": "Professor of Cultural Studies", "question": "Music is often described as a universal language. It can bring people together across cultures and generations. However, some argue that music styles are so different that they don''t always connect people. Do you think music truly unites people, or are cultural differences too strong?"}, "peer_posts": [{"student": "Carolina", "avatar_bg": "bg-rose-600", "stance": "I think music unites people because emotions are universal. Even without understanding the words, people can feel the rhythm, and events like concerts show how music brings different backgrounds together."}, {"student": "Leo", "avatar_bg": "bg-indigo-600", "stance": "I believe music does not always unite people because cultural and generational differences affect how it is perceived. Some styles may feel unfamiliar, so music can also highlight differences."}], "min_words": 100, "recommended_words": "100 - 150 words"}}]}]}'::jsonb,
  timezone('utc'::text, now())
)
ON CONFLICT (id) DO UPDATE SET
  title = EXCLUDED.title,
  skill = EXCLUDED.skill,
  task_type = EXCLUDED.task_type,
  duration_seconds = EXCLUDED.duration_seconds,
  content = EXCLUDED.content;

INSERT INTO public.tests (id, title, skill, task_type, duration_seconds, content, created_at)
VALUES (
  'writing-practice-08',
  'Writing Practice Test 08 (TOEFL 2026 - Question about start time & Competition in Education: Harmful or Beneficial?)',
  'writing',
  'build_sentence',
  1380,
  '{"id": "writing-practice-08", "title": "Writing Practice Test 08 (TOEFL 2026 - Question about start time & Competition in Education: Harmful or Beneficial?)", "skill": "writing", "is_default": true, "duration_seconds": 1380, "description": "Bộ đề luyện thi TOEFL Writing 2026 chuẩn ETS: Task 1 (10 câu Build a Sentence có ngữ cảnh giao tiếp), Task 2 (Write an Email: Question about start time), Task 3 (Academic Discussion: Competition in Education: Harmful or Beneficial?).", "stages": [{"id": "wp8_stage_1", "title": "Writing Section (Linear - 23 Mins)", "duration_seconds": 1380, "tasks": [{"id": "wp8_t1_build_sentence", "title": "Task 1: Build a Sentence (10 câu)", "task_type": "build_sentence", "content": {"instructions": "Mỗi câu có 1 câu ngữ cảnh ban đầu (Conversational Context). Kéo thả hoặc bấm chọn các khối từ bên dưới để ghép thành câu phản hồi hoàn chỉnh, đúng ngữ pháp chuẩn ETS. Chú ý có thể có từ bẫy không được dùng.", "items": [{"id": "wp8_t1_item1", "context": "I''m thinking about joining a gym.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["are", "Do", "offered", "which", "you", "plans", "know", "membership", "being"], "correct_order": ["Do", "you", "know", "which", "membership", "plans", "are", "being", "offered"], "correct_sentence": "Do you know which membership plans are being offered?", "decoys": []}, {"id": "wp8_t1_item2", "context": "My phone battery keeps dying quickly.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["device", "the", "that", "the", "Have", "tried", "came", "you", "using", "charger", "with"], "correct_order": ["Have", "you", "tried", "using", "the", "charger", "that", "came", "with", "the", "device"], "correct_sentence": "Have you tried using the charger that came with the device?", "decoys": []}, {"id": "wp8_t1_item3", "context": "I''m considering taking online yoga classes.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["are", "practicing", "from", "What", "regularly", "get", "hoping", "to", "benefits", "you"], "correct_order": ["What", "benefits", "are", "you", "hoping", "to", "get", "from", "practicing", "regularly"], "correct_sentence": "What benefits are you hoping to get from practicing regularly?", "decoys": []}, {"id": "wp8_t1_item4", "context": "I spilled coffee on my keyboard this morning.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["having", "yet", "by", "checked", "a", "been", "it", "Has", "technician"], "correct_order": ["Has", "it", "been", "checked", "by", "a", "technician", "yet"], "correct_sentence": "Has it been checked by a technician yet?", "decoys": ["having"]}, {"id": "wp8_t1_item5", "context": "I''m planning to redecorate my apartment.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["room", "colors", "Which", "look", "the", "would", "bigger", "make"], "correct_order": ["Which", "colors", "would", "make", "the", "room", "look", "bigger"], "correct_sentence": "Which colors would make the room look bigger?", "decoys": []}, {"id": "wp8_t1_item6", "context": "My neighbor just adopted a puppy.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["you", "it", "know", "stay", "Do", "is", "breed", "what"], "correct_order": ["Do", "you", "know", "what", "breed", "it", "is"], "correct_sentence": "Do you know what breed it is?", "decoys": ["stay"]}, {"id": "wp8_t1_item7", "context": "I''ve been having trouble sleeping lately.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["helps", "What", "usually", "you", "fall", "asleep", "faster"], "correct_order": ["What", "usually", "helps", "you", "fall", "asleep", "faster"], "correct_sentence": "What usually helps you fall asleep faster?", "decoys": []}, {"id": "wp8_t1_item8", "context": "I need to renew my passport soon.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["are", "whether", "booked", "you", "advance", "know", "Do", "appointments", "in", "far"], "correct_order": ["Do", "you", "know", "whether", "appointments", "are", "booked", "far", "in", "advance"], "correct_sentence": "Do you know whether appointments are booked far in advance?", "decoys": []}, {"id": "wp8_t1_item9", "context": "I''m trying to reduce my screen time.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["your", "you", "phone", "are", "to", "avoid", "managing", "checking", "How"], "correct_order": ["How", "are", "you", "managing", "to", "avoid", "checking", "your", "phone"], "correct_sentence": "How are you managing to avoid checking your phone?", "decoys": []}, {"id": "wp8_t1_item10", "context": "My package still hasn''t arrived.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["company", "that", "Have", "shipped", "you", "the", "it", "contacted"], "correct_order": ["Have", "you", "contacted", "the", "company", "that", "shipped", "it"], "correct_sentence": "Have you contacted the company that shipped it?", "decoys": []}]}}, {"id": "wp8_t2_write_email", "title": "Task 2: Write an Email", "task_type": "write_email", "content": {"recipient": "Workshop Coordinator", "subject_hint": "Question about start time", "scenario": "You signed up for a weekend photography workshop offered by a community center. However, you received two emails with different starting times for the class, and you are unsure which one is correct. Write an email to the workshop coordinator.", "requirements": ["Explain the conflicting information you received.", "Mention why confirming the schedule is important for you.", "Ask which starting time is correct and whether updated details will be sent."], "min_words": 80, "recommended_words": "100 - 130 words"}}, {"id": "wp8_t3_academic_discussion", "title": "Task 3: Academic Discussion", "task_type": "academic_discussion", "content": {"course": "Educational Psychology", "topic": "Competition in Education: Harmful or Beneficial?", "professor_prompt": {"name": "Dr. Hayes", "title": "Professor of Education", "question": "Competition is common in education through grades, rankings, and awards. Some educators argue that competition motivates students to work harder and improve performance. Others believe excessive competition increases stress and discourages collaboration. What is your opinion: Does competition in education help students more than it harms them? Why?"}, "peer_posts": [{"student": "Robin", "avatar_bg": "bg-teal-600", "stance": "I think competition helps students because it creates motivation and encourages effort. Many students perform better when they have clear goals and want to achieve strong results. Competition can also prepare people for real-world environments where performance matters. I believe moderate competition can be healthy."}, {"student": "Jordan", "avatar_bg": "bg-amber-600", "stance": "In my opinion, competition can harm students more than it helps. Too much pressure may increase anxiety and make students focus only on outperforming others. This can reduce collaboration and enjoyment of learning. I believe that education should emphasize growth rather than constant comparison."}], "min_words": 100, "recommended_words": "100 - 150 words"}}]}]}'::jsonb,
  timezone('utc'::text, now())
)
ON CONFLICT (id) DO UPDATE SET
  title = EXCLUDED.title,
  skill = EXCLUDED.skill,
  task_type = EXCLUDED.task_type,
  duration_seconds = EXCLUDED.duration_seconds,
  content = EXCLUDED.content;

INSERT INTO public.tests (id, title, skill, task_type, duration_seconds, content, created_at)
VALUES (
  'writing-practice-09',
  'Writing Practice Test 09 (TOEFL 2026 - Late Fee Question & Government Restrictions on Tourism)',
  'writing',
  'build_sentence',
  1380,
  '{"id": "writing-practice-09", "title": "Writing Practice Test 09 (TOEFL 2026 - Late Fee Question & Government Restrictions on Tourism)", "skill": "writing", "is_default": true, "duration_seconds": 1380, "description": "Bộ đề luyện thi TOEFL Writing 2026 chuẩn ETS: Task 1 (10 câu Build a Sentence có ngữ cảnh giao tiếp), Task 2 (Write an Email: Late Fee Question), Task 3 (Academic Discussion: Government Restrictions on Tourism).", "stages": [{"id": "wp9_stage_1", "title": "Writing Section (Linear - 23 Mins)", "duration_seconds": 1380, "tasks": [{"id": "wp9_t1_build_sentence", "title": "Task 1: Build a Sentence (10 câu)", "task_type": "build_sentence", "content": {"instructions": "Mỗi câu có 1 câu ngữ cảnh ban đầu (Conversational Context). Kéo thả hoặc bấm chọn các khối từ bên dưới để ghép thành câu phản hồi hoàn chỉnh, đúng ngữ pháp chuẩn ETS. Chú ý có thể có từ bẫy không được dùng.", "items": [{"id": "wp9_t1_item1", "context": "I''m learning how to cook Thai food.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["first", "are", "Which", "dishes", "in", "interested", "making", "you"], "correct_order": ["Which", "dishes", "are", "you", "interested", "in", "making", "first"], "correct_sentence": "Which dishes are you interested in making first?", "decoys": []}, {"id": "wp9_t1_item2", "context": "The washing machine stopped working again.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["Do", "you", "know", "can", "repaired", "if", "be", "it"], "correct_order": ["Do", "you", "know", "if", "it", "can", "be", "repaired"], "correct_sentence": "Do you know if it can be repaired?", "decoys": []}, {"id": "wp9_t1_item3", "context": "I''m thinking of switching banks.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["a", "features", "new", "looking", "What", "you", "are", "in", "for", "account"], "correct_order": ["What", "features", "are", "you", "looking", "for", "in", "a", "new", "account"], "correct_sentence": "What features are you looking for in a new account?", "decoys": []}, {"id": "wp9_t1_item4", "context": "My friend invited me to a wedding next month.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["he", "you''ll", "wearing", "decided", "you", "be", "what", "Have"], "correct_order": ["Have", "you", "decided", "what", "you''ll", "be", "wearing"], "correct_sentence": "Have you decided what you''ll be wearing?", "decoys": ["he"]}, {"id": "wp9_t1_item5", "context": "I''ve started listening to podcasts during walks.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["do", "you", "enjoy", "What", "topics", "about", "people", "talk", "hearing"], "correct_order": ["What", "topics", "do", "you", "enjoy", "hearing", "people", "talk", "about"], "correct_sentence": "What topics do you enjoy hearing people talk about?", "decoys": []}, {"id": "wp9_t1_item6", "context": "My friend moved to another country last month.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["often", "abroad", "teaches", "to", "people", "become", "independent", "Living", "more"], "correct_order": ["Living", "abroad", "often", "teaches", "people", "to", "become", "more", "independent"], "correct_sentence": "Living abroad often teaches people to become more independent.", "decoys": []}, {"id": "wp9_t1_item7", "context": "I can see you are still worried about missing the train tomorrow.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["the", "been", "schedule", "changed", "check", "you", "whether", "has", "Can"], "correct_order": ["Can", "you", "check", "whether", "the", "schedule", "has", "been", "changed"], "correct_sentence": "Can you check whether the schedule has been changed?", "decoys": []}, {"id": "wp9_t1_item8", "context": "The café near my office closed suddenly.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["you", "office", "know", "shut", "it", "Do", "why", "down", "was"], "correct_order": ["Do", "you", "know", "why", "it", "was", "shut", "down"], "correct_sentence": "Do you know why it was shut down?", "decoys": ["office"]}, {"id": "wp9_t1_item9", "context": "I''m planning to sell some old furniture.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["think", "do", "you", "find", "buyers", "would", "it", "easiest", "Where", "to", "be"], "correct_order": ["Where", "do", "you", "think", "it", "would", "be", "easiest", "to", "find", "buyers"], "correct_sentence": "Where do you think it would be easiest to find buyers?", "decoys": []}, {"id": "wp9_t1_item10", "context": "I haven''t received a reply to my email yet.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["not", "have", "message", "may", "The", "been", "seen", "yet"], "correct_order": ["The", "message", "may", "not", "have", "been", "seen", "yet"], "correct_sentence": "The message may not have been seen yet.", "decoys": []}]}}, {"id": "wp9_t2_write_email", "title": "Task 2: Write an Email", "task_type": "write_email", "content": {"recipient": "mediacenter@greenhilluniversity.edu", "subject_hint": "Late Fee Question", "scenario": "You borrowed equipment from your university''s media center for a class project and returned the equipment on time. However, this morning, you received a notification that a late-return fee has been added to your account. Write an email to the media center staff.", "requirements": ["Describe the fee notification you received.", "Explain when and how you returned the equipment.", "Request a review of the charge and clarification of the records."], "min_words": 80, "recommended_words": "100 - 130 words"}}, {"id": "wp9_t3_academic_discussion", "title": "Task 3: Academic Discussion", "task_type": "academic_discussion", "content": {"course": "Economics & Environmental Tourism", "topic": "Government Restrictions on Tourism", "professor_prompt": {"name": "Dr. Sterling", "title": "Professor of Economics", "question": "Many famous tourist destinations are experiencing problems caused by large numbers of visitors. Overcrowding can damage historical sites, increase pollution, and make life more difficult for local residents. Some people believe governments should limit tourism in certain areas to protect communities and the environment. Others argue that tourism provides significant economic benefits. Should governments place restrictions on tourism in popular destinations?"}, "peer_posts": [{"student": "Deseree", "avatar_bg": "bg-purple-600", "stance": "I support limiting tourism because excessive numbers of visitors can seriously damage local environments and historical sites. Residents may also face higher living costs and overcrowded public spaces. Protecting these places is important so future generations can continue enjoying them."}, {"student": "Mark", "avatar_bg": "bg-cyan-600", "stance": "I disagree because tourism is an important source of income for many communities. Hotels, restaurants, and local businesses depend heavily on visitors. Restricting tourism could reduce employment opportunities and negatively affect the local economy."}], "min_words": 100, "recommended_words": "100 - 150 words"}}]}]}'::jsonb,
  timezone('utc'::text, now())
)
ON CONFLICT (id) DO UPDATE SET
  title = EXCLUDED.title,
  skill = EXCLUDED.skill,
  task_type = EXCLUDED.task_type,
  duration_seconds = EXCLUDED.duration_seconds,
  content = EXCLUDED.content;

INSERT INTO public.tests (id, title, skill, task_type, duration_seconds, content, created_at)
VALUES (
  'writing-practice-10',
  'Writing Practice Test 10 (TOEFL 2026 - Your New Cat & Cashless Society: Pros and Cons)',
  'writing',
  'build_sentence',
  1380,
  '{"id": "writing-practice-10", "title": "Writing Practice Test 10 (TOEFL 2026 - Your New Cat & Cashless Society: Pros and Cons)", "skill": "writing", "is_default": true, "duration_seconds": 1380, "description": "Bộ đề luyện thi TOEFL Writing 2026 chuẩn ETS: Task 1 (10 câu Build a Sentence có ngữ cảnh giao tiếp), Task 2 (Write an Email: Your New Cat), Task 3 (Academic Discussion: Cashless Society: Pros and Cons).", "stages": [{"id": "wp10_stage_1", "title": "Writing Section (Linear - 23 Mins)", "duration_seconds": 1380, "tasks": [{"id": "wp10_t1_build_sentence", "title": "Task 1: Build a Sentence (10 câu)", "task_type": "build_sentence", "content": {"instructions": "Mỗi câu có 1 câu ngữ cảnh ban đầu (Conversational Context). Kéo thả hoặc bấm chọn các khối từ bên dưới để ghép thành câu phản hồi hoàn chỉnh, đúng ngữ pháp chuẩn ETS. Chú ý có thể có từ bẫy không được dùng.", "items": [{"id": "wp10_t1_item1", "context": "My internet connection has been unstable all week.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["your", "issue", "the", "been", "provider", "to", "Has", "reported"], "correct_order": ["Has", "the", "issue", "been", "reported", "to", "your", "provider"], "correct_sentence": "Has the issue been reported to your provider?", "decoys": []}, {"id": "wp10_t1_item2", "context": "I''m thinking about volunteering on weekends.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["doing", "of", "would", "you", "work", "enjoy", "kind", "What"], "correct_order": ["What", "kind", "of", "work", "would", "you", "enjoy", "doing"], "correct_sentence": "What kind of work would you enjoy doing?", "decoys": []}, {"id": "wp10_t1_item3", "context": "I accidentally deleted an important file.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["be", "might", "the", "stored", "document", "recycle", "still", "in", "bin", "The"], "correct_order": ["The", "document", "might", "still", "be", "stored", "in", "the", "recycle", "bin"], "correct_sentence": "The document might still be stored in the recycle bin.", "decoys": []}, {"id": "wp10_t1_item4", "context": "I''m planning a trip to Japan next year.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["want", "Have", "you", "cities", "visit", "decided", "you", "which", "to"], "correct_order": ["Have", "you", "decided", "which", "cities", "you", "want", "to", "visit"], "correct_sentence": "Have you decided which cities you want to visit?", "decoys": []}, {"id": "wp10_t1_item5", "context": "I heard that Emma quit her job.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["to", "you", "know", "decided", "leave", "why", "she", "Do"], "correct_order": ["Do", "you", "know", "why", "she", "decided", "to", "leave"], "correct_sentence": "Do you know why she decided to leave?", "decoys": []}, {"id": "wp10_t1_item6", "context": "The meeting was canceled this morning.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["decision", "Do", "know", "who", "that", "you", "made"], "correct_order": ["Do", "you", "know", "who", "made", "that", "decision"], "correct_sentence": "Do you know who made that decision?", "decoys": []}, {"id": "wp10_t1_item7", "context": "I''m trying to choose a topic for my research paper.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["writing", "about", "in", "you", "subjects", "are", "What", "interested"], "correct_order": ["What", "subjects", "are", "you", "interested", "in", "writing", "about"], "correct_sentence": "What subjects are you interested in writing about?", "decoys": []}, {"id": "wp10_t1_item8", "context": "My package still hasn''t arrived.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["contacted", "that", "company", "the", "shipped", "it", "you", "Have"], "correct_order": ["Have", "you", "contacted", "the", "company", "that", "shipped", "it"], "correct_sentence": "Have you contacted the company that shipped it?", "decoys": []}, {"id": "wp10_t1_item9", "context": "I''m thinking about taking a gap year after university.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["some", "That", "a", "to", "good", "opportunity", "gain", "life", "experience", "sounds", "like"], "correct_order": ["That", "sounds", "like", "a", "good", "opportunity", "to", "gain", "some", "life", "experience"], "correct_sentence": "That sounds like a good opportunity to gain some life experience.", "decoys": []}, {"id": "wp10_t1_item10", "context": "I''m considering applying for a scholarship.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["increases", "usually", "being", "chances", "early", "your", "Applying", "of", "accepted"], "correct_order": ["Applying", "early", "usually", "increases", "your", "chances", "of", "being", "accepted"], "correct_sentence": "Applying early usually increases your chances of being accepted.", "decoys": []}]}}, {"id": "wp10_t2_write_email", "title": "Task 2: Write an Email", "task_type": "write_email", "content": {"recipient": "Sophie Miller (sophie.miller.99@gmail.com)", "subject_hint": "Your New Cat", "scenario": "Your friend Sophie recently adopted a cat from a local animal shelter. You have not spoken to her for several weeks, and you are curious about the cat''s personality and whether having a pet has changed her daily routine. Write an email to your friend.", "requirements": ["Ask about the cat''s personality and behavior.", "Ask how your friend is adjusting to pet ownership.", "Suggest meeting soon so you can see the cat."], "min_words": 80, "recommended_words": "100 - 130 words"}}, {"id": "wp10_t3_academic_discussion", "title": "Task 3: Academic Discussion", "task_type": "academic_discussion", "content": {"course": "Economics & Financial Technology", "topic": "Cashless Society: Pros and Cons", "professor_prompt": {"name": "Dr. Mitchell", "title": "Professor of Economics", "question": "In many countries, people are using digital payment methods more frequently than cash. Supporters of a cashless society argue that electronic payments are faster, safer, and more convenient. However, others believe cash should remain important because not everyone has equal access to technology, and digital systems can fail. In your opinion, should societies move toward becoming mostly cashless?"}, "peer_posts": [{"student": "Andrea", "avatar_bg": "bg-emerald-600", "stance": "I support digital payments because they make everyday transactions much more convenient. People no longer need to carry large amounts of money, and payments can be completed almost instantly. Digital systems also make it easier to track spending and reduce certain types of crime."}, {"student": "Joshua", "avatar_bg": "bg-rose-600", "stance": "I think cash should continue to play an important role. Some people, especially older adults, may struggle with digital technology. In addition, technical problems or power outages could prevent people from accessing their money when they need it."}], "min_words": 100, "recommended_words": "100 - 150 words"}}]}]}'::jsonb,
  timezone('utc'::text, now())
)
ON CONFLICT (id) DO UPDATE SET
  title = EXCLUDED.title,
  skill = EXCLUDED.skill,
  task_type = EXCLUDED.task_type,
  duration_seconds = EXCLUDED.duration_seconds,
  content = EXCLUDED.content;

INSERT INTO public.tests (id, title, skill, task_type, duration_seconds, content, created_at)
VALUES (
  'writing-practice-11',
  'Writing Practice Test 11 (TOEFL 2026 - Missed Appointment & Animal Testing in Scientific Research)',
  'writing',
  'build_sentence',
  1380,
  '{"id": "writing-practice-11", "title": "Writing Practice Test 11 (TOEFL 2026 - Missed Appointment & Animal Testing in Scientific Research)", "skill": "writing", "is_default": true, "duration_seconds": 1380, "description": "Bộ đề luyện thi TOEFL Writing 2026 chuẩn ETS: Task 1 (10 câu Build a Sentence có ngữ cảnh giao tiếp), Task 2 (Write an Email: Missed Appointment), Task 3 (Academic Discussion: Animal Testing in Scientific Research).", "stages": [{"id": "wp11_stage_1", "title": "Writing Section (Linear - 23 Mins)", "duration_seconds": 1380, "tasks": [{"id": "wp11_t1_build_sentence", "title": "Task 1: Build a Sentence (10 câu)", "task_type": "build_sentence", "content": {"instructions": "Mỗi câu có 1 câu ngữ cảnh ban đầu (Conversational Context). Kéo thả hoặc bấm chọn các khối từ bên dưới để ghép thành câu phản hồi hoàn chỉnh, đúng ngữ pháp chuẩn ETS. Chú ý có thể có từ bẫy không được dùng.", "items": [{"id": "wp11_t1_item1", "context": "My laptop was repaired yesterday.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["Who", "I", "it", "for", "fixed", "you"], "correct_order": ["Who", "fixed", "it", "for", "you"], "correct_sentence": "Who fixed it for you?", "decoys": ["I"]}, {"id": "wp11_t1_item2", "context": "I''m thinking of changing my major.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["are", "What", "instead", "hoping", "you", "to", "study"], "correct_order": ["What", "are", "you", "hoping", "to", "study", "instead"], "correct_sentence": "What are you hoping to study instead?", "decoys": []}, {"id": "wp11_t1_item3", "context": "Why are you learning French?", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["to", "France", "travel", "to", "want", "I", "someday"], "correct_order": ["I", "want", "to", "travel", "to", "France", "someday"], "correct_sentence": "I want to travel to France someday.", "decoys": []}, {"id": "wp11_t1_item4", "context": "What are you doing this weekend?", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["countryside", "grandparents", "in", "visiting", "I''m", "the", "my"], "correct_order": ["I''m", "visiting", "my", "grandparents", "in", "the", "countryside"], "correct_sentence": "I''m visiting my grandparents in the countryside.", "decoys": []}, {"id": "wp11_t1_item5", "context": "Why are you looking so tired today?", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["last", "up", "I", "late", "night", "too", "stayed"], "correct_order": ["I", "stayed", "up", "too", "late", "last", "night"], "correct_sentence": "I stayed up too late last night.", "decoys": []}, {"id": "wp11_t1_item6", "context": "I heard that the exam format has changed.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["test", "know", "you", "Do", "how", "is", "the", "structured", "new"], "correct_order": ["Do", "you", "know", "how", "the", "new", "test", "is", "structured"], "correct_sentence": "Do you know how the new test is structured?", "decoys": []}, {"id": "wp11_t1_item7", "context": "I finally understood this math problem.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["teacher", "explain", "meant", "what", "the", "Can", "you"], "correct_order": ["Can", "you", "explain", "what", "the", "teacher", "meant"], "correct_sentence": "Can you explain what the teacher meant?", "decoys": []}, {"id": "wp11_t1_item8", "context": "I was offered a promotion at work.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["accept", "to", "you", "you", "going", "are", "it", "Have", "decided", "whether"], "correct_order": ["Have", "you", "decided", "whether", "you", "are", "going", "to", "accept", "it"], "correct_sentence": "Have you decided whether you are going to accept it?", "decoys": []}, {"id": "wp11_t1_item9", "context": "I''m looking for a new apartment.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["is", "a", "now", "who", "anyone", "place", "renting", "right", "Do", "you", "know"], "correct_order": ["Do", "you", "know", "anyone", "who", "is", "renting", "a", "place", "right", "now"], "correct_sentence": "Do you know anyone who is renting a place right now?", "decoys": []}, {"id": "wp11_t1_item10", "context": "I need to submit my assignment by Friday.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["yet", "finished", "report", "an", "writing", "Have", "you", "the"], "correct_order": ["Have", "you", "finished", "writing", "the", "report", "yet"], "correct_sentence": "Have you finished writing the report yet?", "decoys": ["an"]}]}}, {"id": "wp11_t2_write_email", "title": "Task 2: Write an Email", "task_type": "write_email", "content": {"recipient": "support@fastconnectinternet.com", "subject_hint": "Missed Appointment", "scenario": "You recently moved into a new apartment and scheduled an internet installation appointment because you need internet access for work. However, no technician arrived, and you did not receive any explanation. Write an email to customer service.", "requirements": ["Describe the missed appointment.", "Explain how the delay is affecting your daily activities.", "Request a new appointment and ask for an explanation."], "min_words": 80, "recommended_words": "100 - 130 words"}}, {"id": "wp11_t3_academic_discussion", "title": "Task 3: Academic Discussion", "task_type": "academic_discussion", "content": {"course": "Scientific Research & Bioethics", "topic": "Animal Testing in Scientific Research", "professor_prompt": {"name": "Dr. Vance", "title": "Professor of Bioethics", "question": "Animal testing has contributed to many important medical discoveries throughout history. Nevertheless, growing concerns about animal welfare have led people to question whether these practices should continue. Supporters argue that animal testing remains necessary for scientific progress, while opponents believe alternative technologies should replace it whenever possible. Do you think animal testing should continue to be used in scientific research?"}, "peer_posts": [{"student": "Trisha", "avatar_bg": "bg-indigo-600", "stance": "I think some animal testing is still necessary because many medicines and treatments cannot be safely tested on humans immediately. Medical research has saved millions of lives, and completely banning animal testing could slow scientific progress considerably."}, {"student": "Kevin", "avatar_bg": "bg-amber-600", "stance": "I disagree because animals should not suffer for human benefit if alternatives exist. Scientists are developing advanced computer simulations and laboratory techniques that may eventually replace many forms of animal testing while avoiding ethical concerns."}], "min_words": 100, "recommended_words": "100 - 150 words"}}]}]}'::jsonb,
  timezone('utc'::text, now())
)
ON CONFLICT (id) DO UPDATE SET
  title = EXCLUDED.title,
  skill = EXCLUDED.skill,
  task_type = EXCLUDED.task_type,
  duration_seconds = EXCLUDED.duration_seconds,
  content = EXCLUDED.content;

INSERT INTO public.tests (id, title, skill, task_type, duration_seconds, content, created_at)
VALUES (
  'writing-practice-12',
  'Writing Practice Test 12 (TOEFL 2026 - Quiz Issue & Multitasking vs. Single-Tasking)',
  'writing',
  'build_sentence',
  1380,
  '{"id": "writing-practice-12", "title": "Writing Practice Test 12 (TOEFL 2026 - Quiz Issue & Multitasking vs. Single-Tasking)", "skill": "writing", "is_default": true, "duration_seconds": 1380, "description": "Bộ đề luyện thi TOEFL Writing 2026 chuẩn ETS: Task 1 (10 câu Build a Sentence có ngữ cảnh giao tiếp), Task 2 (Write an Email: Quiz Issue), Task 3 (Academic Discussion: Multitasking vs. Single-Tasking).", "stages": [{"id": "wp12_stage_1", "title": "Writing Section (Linear - 23 Mins)", "duration_seconds": 1380, "tasks": [{"id": "wp12_t1_build_sentence", "title": "Task 1: Build a Sentence (10 câu)", "task_type": "build_sentence", "content": {"instructions": "Mỗi câu có 1 câu ngữ cảnh ban đầu (Conversational Context). Kéo thả hoặc bấm chọn các khối từ bên dưới để ghép thành câu phản hồi hoàn chỉnh, đúng ngữ pháp chuẩn ETS. Chú ý có thể có từ bẫy không được dùng.", "items": [{"id": "wp12_t1_item1", "context": "Why didn''t you come to class yesterday?", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["I", "well", "feeling", "very", "wasn''t"], "correct_order": ["I", "wasn''t", "feeling", "very", "well"], "correct_sentence": "I wasn''t feeling very well.", "decoys": []}, {"id": "wp12_t1_item2", "context": "Why are you comparing these two laptops?", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["I''m", "to", "which", "one", "trying", "to", "decide", "buy"], "correct_order": ["I''m", "trying", "to", "decide", "which", "one", "to", "buy"], "correct_sentence": "I''m trying to decide which one to buy.", "decoys": []}, {"id": "wp12_t1_item3", "context": "What did your parents say about your plan?", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["sounded", "promising", "that", "planned", "They", "said", "very", "it"], "correct_order": ["They", "said", "that", "it", "sounded", "very", "promising"], "correct_sentence": "They said that it sounded very promising.", "decoys": ["planned"]}, {"id": "wp12_t1_item4", "context": "What did you think of the movie?", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["I", "was", "better", "much", "expected", "It", "than"], "correct_order": ["It", "was", "much", "better", "than", "I", "expected"], "correct_sentence": "It was much better than I expected.", "decoys": []}, {"id": "wp12_t1_item5", "context": "Why did you buy a new laptop?", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["properly", "buying", "My", "old", "working", "one", "stopped"], "correct_order": ["My", "old", "one", "stopped", "working", "properly"], "correct_sentence": "My old one stopped working properly.", "decoys": ["buying"]}, {"id": "wp12_t1_item6", "context": "I''m thinking about starting my own business.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["interested", "up", "kind", "of", "setting", "you", "company", "What", "in", "are"], "correct_order": ["What", "kind", "of", "company", "are", "you", "interested", "in", "setting", "up"], "correct_sentence": "What kind of company are you interested in setting up?", "decoys": []}, {"id": "wp12_t1_item7", "context": "I haven''t seen Mark in months.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["know", "is", "working", "he", "now", "you", "where", "happen", "Do", "to"], "correct_order": ["Do", "you", "happen", "to", "know", "where", "he", "is", "working", "now"], "correct_sentence": "Do you happen to know where he is working now?", "decoys": []}, {"id": "wp12_t1_item8", "context": "I''m trying to learn how to cook better.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["make", "would", "What", "to", "you", "dishes", "like", "learn", "to"], "correct_order": ["What", "dishes", "would", "you", "like", "to", "learn", "to", "make"], "correct_sentence": "What dishes would you like to learn to make?", "decoys": []}, {"id": "wp12_t1_item9", "context": "What did your friend ask about your course?", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["She", "it", "difficult", "know", "to", "wanted", "how", "was"], "correct_order": ["She", "wanted", "to", "know", "how", "difficult", "it", "was"], "correct_sentence": "She wanted to know how difficult it was.", "decoys": []}, {"id": "wp12_t1_item10", "context": "I''m considering moving abroad after graduation.", "target_prompt": "Hoàn thiện câu phản hồi của bạn:", "scrambled": ["which", "you", "suit", "thought", "you", "about", "best", "Have", "country", "would"], "correct_order": ["Have", "you", "thought", "about", "which", "country", "would", "suit", "you", "best"], "correct_sentence": "Have you thought about which country would suit you best?", "decoys": []}]}}, {"id": "wp12_t2_write_email", "title": "Task 2: Write an Email", "task_type": "write_email", "content": {"recipient": "support@skillmasteracademy.com", "subject_hint": "Quiz Issue", "scenario": "You are taking an online certification course. Last night, the platform suddenly stopped saving your quiz answers, and you lost most of your work when you refreshed the page. Write an email to technical support.", "requirements": ["Describe the technical problem you experienced.", "Explain when it happened and how much work was lost.", "Ask whether your progress can be recovered or the deadline extended."], "min_words": 80, "recommended_words": "100 - 130 words"}}, {"id": "wp12_t3_academic_discussion", "title": "Task 3: Academic Discussion", "task_type": "academic_discussion", "content": {"course": "Cognitive Psychology", "topic": "Multitasking vs. Single-Tasking", "professor_prompt": {"name": "Dr. Foster", "title": "Professor of Psychology", "question": "Many people believe multitasking helps them become more productive because they can handle several responsibilities at once. However, cognitive research suggests that rapidly switching between tasks may reduce focus and increase errors. What do you think: Is multitasking generally an effective productivity strategy, or is focusing on one task at a time better? Why?"}, "peer_posts": [{"student": "Shaira", "avatar_bg": "bg-teal-600", "stance": "I think multitasking can be effective for simple tasks. For example, answering routine emails while waiting for files to load may save time. Some activities require little mental effort, so combining them is practical. I think multitasking is useful when tasks are not too demanding."}, {"student": "Henry", "avatar_bg": "bg-violet-600", "stance": "I think focusing on one task at a time is better because concentration improves quality. Constantly switching attention wastes mental energy and increases mistakes. Complex tasks especially require deep focus to be done well. In my opinion, single-tasking leads to better long-term productivity."}], "min_words": 100, "recommended_words": "100 - 150 words"}}]}]}'::jsonb,
